get '/manager/configure/device_lister' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my $load_type = $c->param('load_type');
	my $ip = $c->param('host');
	my $ping_scan = $c->param('ping_scan');
	# The host box beside Ping and Scan is one field with two buttons: only Ping
	# used to record it, so clearing the box and pressing Scan redrew it from the
	# value still on record and the clear looked like it never saved. Record the
	# box here too, before the panel is drawn, so what is drawn is what was typed.
	&subs::setting_setter({ app => 'misc', setting => 'ping', value => $ip }) if (($load_type // '') eq 'scan' && defined $ip);
	my $devices = &subs::device_lister($timestamp,$load_type,$ip);
	my $networks = &subs::network_groups($devices);
	my $ble_devices = &subs::ble_device_listing();
	my $ping = &subs::setting_grabber({ app => 'misc', setting => 'ping' });

	$c->render(
		template => 'configure/device_lister',
		devices => $devices,
		networks => $networks,
		ble_devices => $ble_devices,
		ping => $ping,
		ping_scan => $ping_scan,
		ip => $ip,
		load_type => $load_type
	);
};

# A printer's own ink and toner, asked over IPP when its row in the Dev panel
# opens. A separate call, so a printer that is off cannot stall the whole device
# listing - the readout fills in a moment later, or says the printer is away.
get '/manager/configure/printer_ink' => sub($c) {
	$c->render(json => &subs::printer_ink_levels($c->param('ip')));
};

post '/manager/configure/device_purpose' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my ($db,$database,$sql) = &subs::database_grabber();
	my $ip = $c->param('ip');
	my $mac = $c->param('mac');
	my $uuid = $c->param('uuid');
	my $purpose = $c->param('purpose');
	my $dev = &subs::db_query('select * from devices where uuid=?',$uuid);
	my $devices = $dev->hashes;
	foreach my $d ( @{$devices} ) {
		my $address = decode_json $d->{'address'};
		foreach my $nic ( keys %{$address} ) {
			foreach my $neigh ( @{$address->{$nic}->{'neigh'}} ) {
				if ($neigh->{'ip'} eq $ip && $neigh->{'mac'} eq $mac) {
					$neigh->{'purpose'} = $purpose;
				}
			}
		}
		my $json_address = encode_json $address;
		&subs::db_update('devices', { address => $json_address }, { uuid => $uuid });
	}
	$c->render('text' => 'done');
};

get '/manager/time_jump' => sub($c) {
	my ($db,$database,$sql) = &subs::database_grabber();
	my $timestamp = $c->param('timestamp');
	my $filter = $c->param('filter');
	my $type = $c->param('type');
	my $app = $c->param('app');
	my $scope = $c->param('scope');
	my $t = &subs::time_span($scope, $timestamp); #timestamp at beginning
	my $t1 = ($timestamp - $t);
	my $t2 = ($t1 + $timestamp + $t1);
	my $query;
	my $date = localtime( time() )->strftime('%a %B %d %Y %I:%M%P');
	# cast: the column is text, so a plain < compares lexicographically and finds
	# nothing once the view is before 1970 (a negative timestamp)
	if ($type eq 'prev') {
		if ($filter ne 'all') {
			$query = &subs::db_query('select timestamp from appointments where app=? and type=? and cast(timestamp as integer) < ? order by cast(timestamp as integer) DESC LIMIT 1',
				$app,$filter,$t);
		}
		else {
			$query = &subs::db_query('select timestamp from appointments where app=? and cast(timestamp as integer) < ? order by cast(timestamp as integer) DESC LIMIT 1',
				$app,$t);
		}
	}
	elsif ($type eq 'next') {
		if ($filter ne 'all') {
			$query = &subs::db_query('select timestamp from appointments where app=? and type=? and cast(timestamp as integer) > ? order by cast(timestamp as integer) ASC LIMIT 1',
				$app,$filter,$t2);
		}
		else {
			$query = &subs::db_query('select timestamp from appointments where app=? and cast(timestamp as integer) > ? order by cast(timestamp as integer) ASC LIMIT 1',
				$app,$t2);
		}
	}

	my $res = $query->hashes;

	unless (defined $res->[0] && defined $res->[0]->{'timestamp'}) {
		$query = &subs::db_query('select timestamp from appointments where app=? and cast(timestamp as integer) = ? order by cast(timestamp as integer) ASC LIMIT 1',
			$app,$timestamp);
		$res = $query->hashes;
	}

	$date = &subs::iso_local($res->[0]->{'timestamp'}) if defined $res->[0] && defined $res->[0]->{'timestamp'};

	$c->render(json => { date => $date, sent_timestamp => $timestamp, new_timestamp => (defined $res->[0] ? $res->[0]->{'timestamp'} : undef) });

};

get '/manager/configure/me_settings' => sub($c) {
	my $pos = &subs::setting_grabber({ app => 'me', setting => 'pos' });
	my $me = &me_setting_list();
	$c->render(
		template => 'configure/me_setting_list',
