get '/manager/configure/ping' => sub($c) {
	my $ip = $c->param('host');
	my $timestamp = $c->param('timestamp');

	my ($db,$database) = &subs::database_grabber();
	my $timeout = .2;
	my $returner = {};
	&subs::setting_setter({ app => 'misc', setting => 'ping', value => $ip });
	# The box can record what is typed without pinging anything: clearing it and
	# reloading must stick, so the box saves itself on change and asks for no run.
	if ($c->param('save_only')) {
		$c->render(json => { saved => 1, host => $ip // '' });
		return;
	}
	if ($ip) {

		my @ip = split '\.', $ip;
		if (scalar @ip == 4) {

			$returner->{$ip}->{'ip'} = $ip;
			$returner->{$ip}->{'result'} = `timeout $timeout ping -c 1 $ip`;
		}
		else {
			my @ifconfig = split "\n\n", `ifconfig`;
			foreach my $if (@ifconfig) {
				my @ifconfig_list = split "\n", $if;

				my @routes = grep { $_ =~ /inet/ } @ifconfig_list;
				foreach my $route (@routes) {
					my @inet = split " ", $route;
					if ($route =~ /inet /) {


						my @items = split " ", $route;
						my $sip = $ip;
						$sip =~ s/[0-9]//gi;

						my $gw = $items[1];
						my @gw = split /\./, $gw;

						my @csv = split ',', $ip;
						if (scalar @csv > 1) {
							foreach my $csv (@csv) {
								pop @gw;
								push @gw, $csv;
								my $ip_address = join '.', @gw;
								$returner->{$ip_address}->{ip} = $ip_address;
								$returner->{$ip_address}->{'result'} = `timeout $timeout ping -c 1 $ip_address`;
							}
						}
						elsif ($sip eq '..' ) {
							my @sips = split '\.\.', $ip;

							foreach my $csv ( $sips[0] .. $sips[1] ) {

								pop @gw;
								push @gw, $csv;
								my $ip_address = join '.', @gw;

								$returner->{$ip_address}->{ip} = $ip_address;
								$returner->{$ip_address}->{'result'} = `timeout $timeout ping -c 1 $ip_address`;
							}
						}
						else {
							pop @gw;
							push @gw, $ip;
							my $ip_address = join '.', @gw;
							$returner->{$ip_address}->{ip} = $ip_address;
							$returner->{$ip_address}->{'result'} = `timeout $timeout ping -c 1 $ip_address`;
						}
					}
				}
			}
		}
	}
	my $html = $c->render_to_string(
		template => 'configure/ping',
		ping => $returner
	);


	$c->render(text => $html);
};

# Code sync is a peer-key route, not a session route: a peer's cookie lapses,
# and a gated reply silently stalls a sync. Both routes require a pinned key
# (no trust-on-first-contact for a tree that can carry secrets) and are
# restricted to the jawnos folder. The exclusion list is the gitignored/secret
# side of the tree: .shots (the ticket and DB copies), the database, voices,
# releases, personal pictures, generated build caches and the agent notes.
sub code_sync_excludes {
	return join ' ', map { "--exclude='$_'" } (
		'jawnos/.git',
		'jawnos/config.json',
		'jawnos/database',
		'jawnos/public/images/jonathans',
		'jawnos/.shots',
		'jawnos/AGENTS.md',
		'jawnos/docs/AGENTS-notes.md',
		'jawnos/releases',
		'jawnos/voices',
		'jawnos/signatorials',
		'jawnos/.pio',
		'jawnos/jp/alarmclock/.pio',
		'jawnos/jt/.pio',
		'jawnos/jw/.pio',
		'jawnos/jt/build',
		'jawnos/jw/build',
		'*.pem',
		'*.key',
		'*.log',
	);
}

sub code_sync_tar {
	my $home = shift;
	my $excludes = &code_sync_excludes();
	return `tar czf - -C "$home" $excludes jawnos 2>/dev/null`;
}

# Extract only a tarball whose every member is under jawnos/; this keeps a
# compromised or mistaken peer from writing .ssh, .president or anything else
# in the home directory.
sub code_sync_unpack {
	my ($tmp, $home) = @_;
	my @members = `tar tzf "$tmp" 2>/dev/null`;
	return 0 unless @members;
	foreach my $m (@members) {
		chomp $m;
		next if $m eq '' || $m eq '.' || $m eq './';
		$m =~ s{^\./}{};
		return 0 unless $m =~ m{^jawnos/} && $m !~ m{(^|/)\.\.(/|$)} && $m !~ m{^/};
	}
	my $rc = system('tar', 'xzf', $tmp, '-C', $home, '--no-same-owner', '--no-same-permissions');
	return 0 unless $rc == 0;
	# The pack excludes .git, so a synced checkout is dirty against its old HEAD
	# and its watcher would refuse to move. Reset it when the synced tree is a
	# shipped commit, or commit it locally when it is peer-only work.
	my ($norm, $nout) = &subs::git_checkout_normalize({ repo => "$home/jawnos", label => 'code sync' });
	if ($subs::logfile && ($norm eq 'reset' || $norm eq 'committed')) {
		open(my $fh, '>>', $subs::logfile);
		print $fh &subs::rightNow() . " code sync: checkout $norm\n";
		close $fh;
	}
	return 1;
}

# A pinned key is required: a known signatorial is not secret, so a stranger
# could otherwise claim it and receive or replace the tree on first contact.
get '/manager/rsync_pack' => sub($c) {
	my $signatorial = $c->param('signatorial');
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($rm && $rm->{'pubkey'} && &subs::peer_verify($c, $rm)) { $c->rendered(403); return; }
	my $tar = &code_sync_tar(&subs::home('~/'));
	$c->res->headers->content_type('application/x-gtar');
	$c->render(data => $tar);
};

post '/manager/rsync_unpack' => sub($c) {
	my $signatorial = $c->param('signatorial');
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($rm && $rm->{'pubkey'} && &subs::peer_verify($c, $rm)) { $c->rendered(403); return; }
	my $body = $c->req->body;
	$body = $body->slurp if ref $body;
	my $limit = 256 * 1024 * 1024;
	unless (defined $body && length($body) && length($body) <= $limit) {
		$c->rendered(length($body // '') > $limit ? 413 : 400);
		return;
	}
	my $home = &subs::home('~/');
	my $tmp = &subs::home('~/.president/rsync_recv_' . &subs::random_string_creator(8) . '.tgz');
	write_file($tmp, $body);
	my $ok = &code_sync_unpack($tmp, $home);
	unlink $tmp;
	unless ($ok) { $c->rendered(400); return; }
	$c->render(text => 'unpacked ' . length($body));
};

# The peer half of the DB backup: serve an encrypted archive by path, so the
# backup can ride http instead of sshpass+rsync. Authorized by the caller's
# signatorial; only *.enc files are ever served.
get '/manager/backup_serve' => sub($c) {
	my $signatorial = $c->param('signatorial');
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($rm && &subs::peer_verify($c, $rm)) { $c->rendered(403); return; }
	my $path = &subs::home($c->param('file') || '');
	unless ($path =~ /\.enc$/ && -f $path) { $c->rendered(404); return; }
	# A remote backup's archive is a one-shot temp under ~/.president, made for
	# this pull; delete it once the body is on the wire rather than leave it for
	# the next boot's ~/.president wipe. Durable backups live beside the database
	# and are never touched here.
	# A puller that has been through the async build fetches the archive in
	# ranges, so a dropped tunnel resumes at the byte it reached instead of
	# starting the whole snapshot again. Only the full (non-range) reply deletes
	# the one-shot temp; a ranged reply leaves it for the confirm or the boot
	# wipe.
	my $size = -s $path;
	$c->res->headers->accept_ranges('bytes');
	my $range = $c->req->headers->range || '';
	if ($range && $range =~ /^bytes=(\d*)-(\d*)$/) {
		my ($start, $end) = ($1, $2);
		$start = 0 if $start eq '';
		$end = $size - 1 if $end eq '';
		if ($start > $end || $start >= $size || $end >= $size) {
			$c->res->headers->content_range("bytes */$size");
			$c->rendered(416);
			return;
		}
		my $len = $end - $start + 1;
		my $buf = '';
		if (open my $fh, '<:raw', $path) {
			sysseek($fh, $start, 0);
			sysread($fh, $buf, $len);
			close $fh;
		}
		$c->res->headers->content_type('application/octet-stream');
		$c->res->headers->content_range("bytes $start-$end/$size");
		$c->res->headers->content_length(length $buf);
		$c->res->body($buf);
		$c->rendered(206);
		return;
	}
	if ($path =~ m{/\.president/}) {
		$c->on(finish => sub { unlink $path; });
	}
	$c->res->headers->content_type('application/octet-stream');
	$c->res->headers->content_length($size);
	$c->res->content->asset(Mojo::Asset::File->new(path => $path));
	$c->rendered(200);
};

# The puller's window into an asynchronous export: the build's state, its
# per-table row counts, and - once ready - the same reply backup_now used to
# return synchronously. The caller is the peer that asked for the snapshot, so
# the job is scoped to its signatorial and cannot be read by anyone else.
get '/manager/configure/backup_status' => sub($c) {
	my $signatorial = $c->param('signatorial');
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($c->session('authentication') eq 'approved' || ($rm && &subs::peer_verify($c, $rm))) {
		$c->rendered(403);
		return;
	}
	my $job = $c->param('job') || '';
	my $snap = ($job && &subs::db_select('sync_snapshots', undef, { uuid => $job, caller => $signatorial })->hashes->[0]);
	unless ($snap) {
		$c->render(json => { status => 'unknown', job => $job });
		return;
	}
	# A worker the kernel killed leaves the row 'building' forever; age it out
	# rather than let the puller poll a dead snapshot until its own bound.
	if (($snap->{'state'} || '') eq 'building' && int($snap->{'updated'} || 0) + 1800000 < &subs::rightNow()) {
		&subs::db_update('sync_snapshots', { state => 'failed', error => 'stale build', updated => &subs::rightNow() }, { uuid => $job });
		$snap->{'state'} = 'failed';
		$snap->{'error'} = 'stale build';
	}
	my $steps = [];
	if ($snap->{'job'}) {
		my $sj = &subs::db_select('sync_jobs', undef, { uuid => $snap->{'job'} })->hashes->[0];
		$steps = eval { decode_json($sj->{'steps'} || '[]') } || [] if $sj;
	}
	my $result = eval { decode_json($snap->{'result'} || '') } || undef;
	$c->render(json => {
		status => ($snap->{'state'} || 'unknown'),
		job => $job,
		steps => $steps,
		size => $snap->{'size'},
		sha256 => $snap->{'sha256'},
		error => $snap->{'error'},
		($result ? (result => $result) : ()),
	});
};

# A teletype (the deck) pulls the house's running database, sealed, onto its own
# SD card. The Dev panel's Backup button hands the deck the snapshot's names and
# the deck fetches the bytes here, so this serves the rolling
# database/backups/jawnos.enc - the house as it stands. If that snapshot is older
# than the utility controller's own backup interval it is taken fresh first, so the
# deck gets a current copy without waiting for the hourly job. A device has no
# session, so this route rides the gate-exempt rail and identifies its caller
# itself: the chip_id must be a device this machine holds, the same identification
# every other embedded request carries (hardened in a later pass).
get '/embedded/teletype/backup' => sub($c) {
	my $chip_id = $c->param('chip_id');
	my $known;
	if ($chip_id) {
		foreach my $d ( @{ &subs::db_select('devices')->hashes } ) {
			next unless $d->{'chip_ids'};
			foreach my $ch ( @{ (eval { decode_json $d->{'chip_ids'} } || []) } ) {
				if ($ch->{'id'} && $ch->{'id'} eq $chip_id) { $known = 1; last; }
			}
			last if $known;
		}
	}
	unless ($known) { $c->rendered(403); return; }
	my $enc = &subs::backups_dir() . '/jawnos.enc';
	my $interval = 3600;   # the utility controller's backups job, by default hourly
	my $uc = eval { decode_json &subs::setting_grabber({ app => '__president', setting => 'utility_controller' }) } || {};
	foreach my $job ( values %{$uc} ) {
		next unless ref $job eq 'HASH' && ref $job->{'backups'} eq 'HASH';
		$interval = 0 + $job->{'backups'}->{'interval'} if $job->{'backups'}->{'interval'};
	}
	my $age = -f $enc ? (time() - (stat $enc)[9]) : 1e9;
	if ($age > $interval) {
		my $cc = &subs::controller_builder();
		$cc->param('reason' => 'teletype_backup');
		eval { &subs::backup_now($cc); };
	}
	unless (-f $enc) { $c->rendered(404); return; }
	$c->res->headers->content_type('application/octet-stream');
	$c->res->content->asset(Mojo::Asset::File->new(path => $enc));
	$c->rendered(200);
};

get '/manager/vault_share' => sub($c) {
	# A linked machine with no key of its own asks for the house key. The request
	# must carry its peer signature and a key already pinned on file - no
	# trust-on-first-contact here, since this hands out the key itself - and the
	# reply is sealed to a one-time secret the asker supplied. Turning off the
	# __president/vault_share setting refuses everyone. The route is exempt from
	# the gate (a keyless machine has no session); peer_verify is its gate.
	my $signatorial = $c->param('signatorial');
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($rm && $rm->{'pubkey'} && &subs::peer_verify($c, $rm)) { $c->rendered(403); return; }
	my $share = &subs::setting_grabber({ app => '__president', setting => 'vault_share' });
	$share = 'yes' unless defined $share && length $share;
	unless ($share eq 'yes') { $c->render(json => { ok => 0, error => 'sharing off' }); return; }
	# the key this machine holds: the vault first, and a worker that resolved it
	# before its vault row went missing still knows it (suds_grabber falls back)
	my $suds = eval { &subs::suds_grabber() };
	$suds ||= ( &subs::vault_read() )[0];
	my $seal = $c->param('seal');
	unless ($suds && $seal && $seal =~ /^[0-9A-Za-z-]{20,80}$/) { $c->render(json => { ok => 0 }); return; }
	my $sealed = &subs::note_encrypter($seal, $suds);
	unless ($sealed) { $c->render(json => { ok => 0 }); return; }
	$c->render(json => { ok => 1, sealed => $sealed });
};

get '/manager/legacy_reseal' => sub($c) {
	# A linked machine asks this one to upgrade its values left from the era when
	# the outer layer was sealed with the empty passphrase (public knowledge, so
	# such values are effectively plaintext at rest). Nothing secret crosses: the
	# work is local and idempotent, and peer_verify against a pinned key is the
	# gate, like vault_share.
	my $signatorial = $c->param('signatorial');
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($rm && $rm->{'pubkey'} && &subs::peer_verify($c, $rm)) { $c->rendered(403); return; }
	my $result = eval { &subs::legacy_reseal() } || { ok => 0 };
	$c->render(json => { %{$result}, by => &subs::signatorial_designer() });
};

post '/manager/key_push' => sub($c) {
	# A linked machine that has just rotated the house key hands the new one
	# over: the request carries its pinned signature and the new key wrapped
	# under the key it replaced, so only a machine still on that key can read it
	# - a machine on a different lineage fails the unwrap and keeps its own. The
	# adoption is the same worker the local rotation runs (generate replaced by
	# adopt), and this machine's own sealed files go to its queue.
	my $signatorial = $c->param('signatorial');
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($rm && $rm->{'pubkey'} && &subs::peer_verify($c, $rm)) { $c->rendered(403); return; }
	my $K = eval { &subs::suds_grabber() };
	my $proved = $c->param('proved');
	unless ($K && $proved) { $c->render(json => { ok => 0, error => 'no key here' }); return; }
	my $Knew = &subs::crypt_simple_unwrap($K, $proved);
	unless (defined $Knew && length $Knew) { $c->render(json => { ok => 0, error => 'not for this key' }); return; }
	$Knew =~ s/\s+$//;
	if ($Knew eq $K) { $c->render(json => { ok => 1, already => 1 }); return; }
	my $result = &subs::rotate_house_key($Knew);
	if ($result->{'ok'}) {
		eval { &subs::minion_grabber()->enqueue('folders_reseal' => [ { before => $result->{'at'}, budget => 600 } ] => { attempts => 2 }) };
	}
	$c->render(json => { ok => $result->{'ok'} ? 1 : 0, error => $result->{'error'}, summary => { settings => $result->{'settings'}, security => $result->{'security'}, links => $result->{'links'} } });
};

post '/manager/operator_door' => sub($c) {
	# A Now Me rotation is pushed over the signed rail to every linked machine.
	# The device probes a fallback House with this pair, so a peer that has not
	# run a settings sync yet (or whose session cookie lapsed) must still be able
	# to store it. peer_verify is the gate; the value is the row Now Me wrote.
	my $signatorial = $c->param('signatorial');
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($rm && $rm->{'pubkey'} && &subs::peer_verify($c, $rm)) { $c->rendered(403); return; }
	my $edt = $c->param('edt');
	my $chip_id = $c->param('chip_id');
	my $value = $c->param('value');
	unless ($edt && $chip_id && defined $value && length $value) {
		$c->render(json => { ok => 0, error => 'missing device or value' });
		return;
	}
	# Store the writer's server_time, so every machine holds the same revision
	# of the row and a later sync does not flip between copies.
	my $server_time = $c->param('server_time') || &subs::rightNow();
	&subs::setting_setter({
		app => $edt,
		setting => 'operator_door',
		subsetting => $chip_id,
		device => ($c->param('device') || &subs::device_setter()),
		value => $value,
		server_time => $server_time,
		timestamp => $server_time,
	});
	$c->render(json => { ok => 1 });
};

post '/manager/configure/remote_rsync' => sub ($c) {
	my $timestamp = $c->param('timestamp');
	my $direction = $c->param('direction');
	my $signatorial = $c->param('signatorial');
	my $uuid = $c->param('uuid');
	my $hostname = `hostname`;
	chomp $hostname;
	my $folder = $c->param('home') || 'jawnos';
	$folder =~ s{.*/}{};
	my $home = &subs::home('~/');
	my $me = &subs::signatorial_designer();
	my $rm = &subs::db_select('remote_machines', undef, { uuid => $uuid, signatorial => $signatorial })->hashes->[0];
	my @result;
	my $summary;
	if ($rm->{'signatorial'}) {
		$rm = &Manager::remote_useragent_maker({ signatorial => $signatorial, rm => $rm });
		$rm->{'ua'}->inactivity_timeout(300);
		if ($direction eq 'from') {
			# pull the peer's tree down over http, unpack it into ~, restart
			my $url = $rm->{'manager'} . '/manager/rsync_pack?signatorial=' . $me . '&folder=' . $folder;
			my $res = eval { $rm->{'ua'}->get($url)->result };
			if ($res && $res->is_success && length $res->body) {
				my $tmp = &subs::home('~/.president/rsync_pull_' . &subs::random_string_creator(8) . '.tgz');
				write_file($tmp, $res->body);
				my $ok = &code_sync_unpack($tmp, $home);
				unlink $tmp;
				if ($ok) {
					$summary = 'Pulled ' . &subs::data_size(length $res->body);
					write_file(&subs::home('~/.president/status'), 'restart');
					push @result, 'Triggered Local Restart';
				}
				else { $summary = 'Pull refused (unsafe archive)'; }
			}
			else { $summary = 'Pull failed'; }
		}
		elsif ($direction eq 'to') {
			# pack our tree and push it to the peer, then ask it to restart
			my $tar = &code_sync_tar($home);
			my $url = $rm->{'manager'} . '/manager/rsync_unpack?signatorial=' . $me . '&folder=' . $folder;
			my $res = eval { $rm->{'ua'}->post($url => { 'Content-Type' => 'application/x-gtar' } => $tar)->result };
			if ($res && $res->is_success) {
				$summary = 'Pushed ' . &subs::data_size(length $tar);
				my $rurl = $rm->{'manager'} . '/manager/president';
				eval { $rm->{'ua'}->inactivity_timeout(23)->post($rurl => form => { signatorial => $me, command => 'restart' })->result };
				push @result, 'Triggered Remote Restart';
			}
			else { $summary = 'Push failed'; }
		}
	}
	else { $summary = 'No such remote machine'; }

	my $result = ($summary ? $summary . '<br>' : '') . join('<br>', @result) . "\n";
	my $whoami = `whoami`;
	chomp $whoami;
	my $json = { type => 'command', whoami => $whoami, hostname => $hostname, uuid => &subs::random_string_creator(), command => 'remote_rsync ' . ($direction || ''), 'return' => $result, timestamp => $timestamp };

	&Websocket::send('server', $json);
	&subs::db_update('remote_machines', { server_time => &subs::rightNow(), connection => 'inactive' }, { uuid => $uuid, signatorial => $signatorial });
	$c->render('text' => $result);
};

post '/manager/configure/remote_upgrade' => sub($c) {
	# The marker carries the owner's pid (see remote_upgrade); compare the flag,
	# not the whole value, or a live 'running:<pid>' never matched. A live owner
	# only blocks inside the same ten-minute bound the pull itself honours.
	my $up_state = &subs::db_query('select value,server_time from settings where app = ? and setting = ? order by cast(server_time as integer) desc limit 1', '__president', 'remote_upgrade')->hashes->[0] || {};
	my ($up_flag, $up_pid) = split /:/, ($up_state->{'value'} || ''), 2;
	$up_flag ||= '';
	my $up_live = ($up_flag eq 'running' && $up_pid && $up_pid =~ /^\d+$/ && $up_pid > 1 && kill(0, $up_pid)) ? 1 : 0;
	# A live owner blocks for longer than any merge: the old ten-minute bound
	# let a second full pull start while the first was still merging 110k rows.
	# A bare 'running' (no pid) keeps the short bound.
	my $up_bound = $up_live ? 1800000 : 600000;
	if ($up_flag eq 'running' && (!$up_pid || $up_live) && int($up_state->{'server_time'} || 0) + $up_bound > &subs::rightNow()) {
		$c->render('text' => 'already running');
		$c->rendered;
		return;
	}
	# The UI uses its session; a peer calling this as the signed pull-now lever
	# (the target names the machine it should pull from) verifies against the
	# roster instead, so a lapsed cookie cannot wedge the sync again.
	my $requester = $c->param('signatorial');
	my $requester_rm = ($requester && &subs::db_select('remote_machines', undef, { signatorial => $requester })->hashes->[0]);
	unless ($c->session('authentication') eq 'approved' || ($requester_rm && &subs::peer_verify($c, $requester_rm))) {
		$c->rendered(403);
		return;
	}
	my $timestamp = $c->param('timestamp');
	my $ip = $c->param('ip');
	my $ssh_port = $c->param('ssh_port');
	my $hostname = $c->param('hostname');
	my $database = $c->param('database');
	my $direction = $c->param('direction');
	my $gimme = $c->param('gimme');
	my $full = $c->param('full');
	my $remote_signatorial = $c->param('signatorial');
	my $remote_device = $c->param('device');
	my $params = {
		timestamp => $timestamp,
		ip => $ip,
		ssh_port => $ssh_port,
		hostname => $hostname,
		database => $database,
		gimme => $gimme,
		full => $full,
		remote_signatorial => $remote_signatorial,
		remote_device => $remote_device,
		marker => 'running:' . $$
	};
	# Claim the marker here, not in the child: the reconnector can walk several
	# peers in one tick, and a child that has not run yet leaves the next one
	# free to fork. The child adopts this claim and replaces it with its own pid.
	&subs::setting_setter({ app => '__president', setting => 'remote_upgrade', value => 'running:' . $$ });
	&subs::subprocessor(sub {
    Mojo::IOLoop->reset;
		&remote_upgrade($c,$params);
	}, { name => 'remote upgrade', fork => 1 });
	$c->render('text' => 'ok');
};

# Dev's migration action: this machine (the donor) asks a linked new device to
# pull the whole house from here. The device keeps its own session and key; the
# request rides the signed pull-now lever, so a lapsed cookie cannot wedge it.
# The key itself is given by Connect (house key seeds the vault) or a ticket; a
# device that already has it takes this pull straight away.
post '/manager/configure/migrate' => sub($c) {
	unless ($c->session('authentication') eq 'approved' && $c->session('privilege') eq 'citizen') {
		$c->render(json => { ok => 0, error => 'citizen only' });
		return;
	}
	my $device_sig = $c->param('signatorial') || '';
	my $rm = ($device_sig && &subs::db_select('remote_machines', undef, { signatorial => $device_sig })->hashes->[0]);
	unless ($rm) {
		$c->render(json => { ok => 0, error => 'device is not linked to this machine yet' });
		return;
	}
	my ($db,$database) = &subs::database_grabber();
	my $donor_sig = &subs::signatorial_designer();
	my $now = &subs::rightNow();
	my $hostname = `hostname`;
	chomp $hostname;
	my $donor_ip = $config->{'domain'} || '127.0.0.1';
	my $ua = &remote_useragent_maker({ signatorial => $device_sig });
	my $res;
	if ($ua->{'manager'}) {
		my $url = $ua->{'manager'} . '/manager/configure/remote_upgrade';
		$res = eval { $ua->{'ua'}->inactivity_timeout(30)->request_timeout(60)->post($url => form => {
			signatorial => $donor_sig,
			ip => $donor_ip,
			ssh_port => $config->{'ssh_port'},
			hostname => $hostname,
			database => $database,
			device => &subs::device_setter(),
			full => 1,
			timestamp => $now,
		})->result };
	}
	my $why = $@ ? $@ : ($res ? '' : 'the device did not answer');
	$why =~ s/\s+/ /g if $why;
	if ($res && !$res->is_success) {
		$why = 'the device answered ' . $res->code . ': ' . substr(($res->body // ''), 0, 160);
	}
	my $started = ($res && $res->is_success) ? 1 : 0;
	my $migration = &subs::random_string_creator(24);
	&subs::db_insert('migrations', {
		uuid => $migration,
		device_signatorial => $device_sig,
		device_name => $rm->{'hostname'},
		donor_signatorial => $donor_sig,
		state => ($started ? 'started' : 'failed'),
		note => ($started ? substr(($res->body // ''), 0, 200) : substr($why, 0, 200)),
		started => $now,
		updated => $now,
		server_time => $now,
	});
	$c->render(json => {
		ok => ($started ? 1 : 0),
		migration => $migration,
		($started ? () : (error => $why)),
	});
};

get '/manager/configure/migrate/status' => sub($c) {
	unless ($c->session('authentication') eq 'approved') {
		$c->render(json => { ok => 0 });
		return;
	}
	my $m = &subs::db_select('migrations', undef, { uuid => $c->param('uuid') || '' })->hashes->[0];
	unless ($m) { $c->render(json => { ok => 0, error => 'no such migration' }); return; }
	my $snap = &subs::db_query('select * from sync_snapshots where caller = ? order by cast(updated as integer) desc limit 1', $m->{'device_signatorial'})->hashes->[0] || {};
	my $steps = [];
	if ($snap->{'job'}) {
		my $sj = &subs::db_select('sync_jobs', undef, { uuid => $snap->{'job'} })->hashes->[0];
		$steps = eval { decode_json($sj->{'steps'} || '[]') } || [] if $sj;
	}
	my $state = $m->{'state'} || 'started';
	$state = 'done' if (($snap->{'state'} || '') eq 'done');
	$state = 'failed' if (($snap->{'state'} || '') eq 'failed');
	if ($state ne ($m->{'state'} || '')) {
		&subs::db_update('migrations', { state => $state, updated => &subs::rightNow() }, { uuid => $m->{'uuid'} });
		$m->{'state'} = $state;
	}
	$c->render(json => {
		ok => 1,
		migration => { uuid => $m->{'uuid'}, state => $state, device => $m->{'device_name'}, note => $m->{'note'} },
		snapshot => { state => ($snap->{'state'} || ''), size => $snap->{'size'}, steps => $steps },
	});
};


# The peer half of remote_deploy: pull, reinstall the desktop app and restart,
# authorized by the caller's signatorial - deploys over http now, no ssh.
post '/manager/self_deploy' => sub($c) {
	my $signatorial = $c->param('signatorial');
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($rm && &subs::peer_verify($c, $rm)) { $c->rendered(403); return; }
	my $repo = &subs::home('~/jawnos');
	# force reconciles a tree git cannot fast-forward (origin's history was
	# rewritten, or local commits exist) by resetting hard to origin/main; off by
	# default so a plain pull never clobbers real work.
	my ($status, $out) = &subs::git_repo_update({ repo => $repo, force => ($c->param('force') ? 1 : 0) });
	if (-d &subs::home('~/.local/share/jawnos/desktop') && -x "$repo/desktop/install.sh") {
		`cd "$repo" && ./desktop/install.sh >/dev/null 2>&1`;
	}
	&subs::install_extras();
	write_file(&subs::home('~/.president/status'), 'restart');
	$c->render(text => "deployed $status\n" . ($out || ''));
};

post '/manager/configure/deploy_neighbours' => sub($c) {
	# Ask every neighbour to pull + restart (the http deploy route). Each device
	# also pulls on its own (git_watcher_check); this is the force-it-now lever.
	my $rms = &subs::db_select('remote_machines')->hashes;
	my @results;
	foreach my $rm ( @{$rms} ) {
		my $res = &subs::remote_deploy($rm);
		push @results, ($rm->{'hostname'} || $rm->{'fqdn'} || $rm->{'ip'}) . ': ' . $res->{'message'};
	}
	$c->render(json => { results => \@results });
};


# ---------------------------------------------------------------------------
# App releases (the APK). scripts/app_release.pl stages a built APK into
# <repo>/releases (gitignored); every machine replicates it as a blob, not
# through git history. A peer asks what a machine holds, then fetches one - the
# app half of "whoever has the newest is the authority".
# ---------------------------------------------------------------------------
our %app_release_sha;
sub app_release_sha {
	my $path = shift;
	my @st = stat $path;
	return '' unless @st;
	my $key = "$path:$st[7]:$st[9]";
	require Digest::SHA;
	unless (exists $app_release_sha{$key}) {
		my $data = eval { read_file($path) };
		$app_release_sha{$key} = defined $data ? Digest::SHA::sha256_hex($data) : '';
	}
	return $app_release_sha{$key};
}

sub app_release_lister {
	my $dir = &subs::home('~/jawnos/releases');
	my @out;
	opendir(my $dh, $dir) or return \@out;
	foreach my $f ( sort readdir($dh) ) {
		next unless my ($product, $vc, $vn) = $f =~ /^jawnos-(app|api)-(\d+)-(.+)\.apk$/;
		my $path = "$dir/$f";
		push @out, {
			product     => $product,
			versionCode => $vc + 0,
			versionName => $vn,
			filename    => $f,
			size        => (-s $path) + 0,
			sha256      => &app_release_sha($path),
		};
	}
	closedir $dh;
	return \@out;
}

# A peer's code as a git bundle: the other half of "whoever has the newest is
# it". The caller sends the commit it holds, and the bundle carries only what is
# new since then when this tree knows it (a fast delta), else the whole history.
# Gated by the signatorial the way the app_release routes are.
get '/manager/code_bundle' => sub($c) {
	my $signatorial = $c->param('signatorial');
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($rm && &subs::peer_verify($c, $rm)) { $c->rendered(403); return; }
	my $repo = &subs::home('~/jawnos');
	my $git = &subs::git_binary();
	my $base = $c->param('base') || '';
	require File::Temp;
	my ($fh, $path) = File::Temp::tempfile(SUFFIX => '.bundle', UNLINK => 1);
	close $fh;
	my $delta = '';
	if ($base =~ /^[0-9a-f]{7,40}$/ && system("cd \"$repo\" && \"$git\" cat-file -e $base 2>/dev/null") == 0) {
		$delta = " ^$base";
	}
	`cd "$repo" && "$git" bundle create "$path" HEAD$delta 2>&1`;
	my $data = '';
	if (open(my $bf, '<', $path)) { binmode $bf; local $/; $data = <$bf>; close $bf; }
	unlink $path;
	unless (length $data) { $c->rendered(500); return; }
	$c->res->headers->content_type('application/octet-stream');
	$c->render(data => $data);
};

get '/manager/app_release' => sub($c) {
	my $signatorial = $c->param('signatorial');
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($rm) { $c->rendered(403); return; }
	my $hostname = `hostname`; chomp $hostname;
	$c->render(json => { hostname => $hostname, signatorial => &subs::signatorial_designer(), releases => &app_release_lister() });
};

get '/manager/app_download' => sub($c) {
	my $signatorial = $c->param('signatorial');
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($rm) { $c->rendered(403); return; }
	my $product = $c->param('product') || 'app';
	my $want = $c->param('versionCode');
	my $pick;
	foreach my $r ( @{ &app_release_lister() } ) {
		next unless $r->{'product'} eq $product;
		next if defined $want && $want ne '' && $r->{'versionCode'} != $want;
		$pick = $r if !$pick || $r->{'versionCode'} > $pick->{'versionCode'};
	}
	unless ($pick) { $c->rendered(404); return; }
	$c->res->headers->content_type('application/vnd.android.package-archive');
	$c->res->headers->content_disposition('attachment; filename="' . $pick->{'filename'} . '"');
	$c->res->content->asset(Mojo::Asset::File->new(path => &subs::home('~/jawnos/releases') . '/' . $pick->{'filename'}));
	$c->rendered(200);
};

# Trigger a fresh app-release pull on demand: the mobile app's "Update app"
# button calls this so a stale 5-minute sync doesn't report "up to date". The
# pull runs in a forked child (a slow peer or a 35 MB download must not block
# the event loop); the caller re-scans the releases dir afterwards.
post '/manager/app_release_sync' => sub($c) {
	unless ($c->session('authentication') eq 'approved') {
		$c->rendered(403);
		return;
	}
	&subs::subprocessor(sub {
		eval { &subs::app_release_sync(); };
	}, { name => 'app release sync (on demand)' });
	$c->render(json => { ok => 1, syncing => 1 });
};

# The local Ollama's model list, for a peer that offers (and routes to) this
# machine's models - the app-release rail, with the same signatorial gate.
get '/manager/ollama_models' => sub($c) {
	my $signatorial = $c->param('signatorial');
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($rm) { $c->rendered(403); return; }
	my $ua = Mojo::UserAgent->new(connect_timeout => 3, inactivity_timeout => 8, request_timeout => 12);
	my $res = eval { $ua->get('http://localhost:11434/api/tags')->result };
	my $models = [];
	if ($res && $res->is_success) {
		my $b = eval { $res->json } || {};
		$models = $b->{'models'} if ref $b->{'models'} eq 'ARRAY';
	}
	my $hn = `hostname`; chomp $hn;
	$c->render(json => { hostname => $hn, models => $models });
};

# A peer's chat turn, run against this machine's Ollama. The caller already
# decided the model lives here; this only carries the call and its answer back.
post '/manager/ollama_chat' => sub($c) {
	my $signatorial = $c->param('signatorial');
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($rm) { $c->rendered(403); return; }
	my $payload = eval { $c->req->json } || {};
	my $ua = Mojo::UserAgent->new(connect_timeout => 5, inactivity_timeout => 300, request_timeout => 600);
	my $res = eval { $ua->post('http://localhost:11434/api/chat' => json => $payload)->result };
	unless ($res) { $c->render(json => { error => 'the local Ollama did not answer' }); return; }
	$c->res->headers->content_type('application/json');
	$c->render(data => $res->body);
};

# The voice models this machine can serve - the *.onnx files and their json under
# voices/. Only the models are shared: the piper binary is per-arch and stays
# local (say_piper_binary), so it is not listed here.
sub voice_lister {
	my $dir = &subs::home('~/jawnos/voices');
	my @out;
	opendir(my $dh, $dir) or return \@out;
	foreach my $f ( sort readdir($dh) ) {
		next unless $f =~ /^[A-Za-z0-9_.-]+\.onnx(\.json)?$/;
		my $path = "$dir/$f";
		next unless -f $path;
		push @out, {
			filename => $f,
			size     => (-s $path) + 0,
			sha256   => &app_release_sha($path),
		};
	}
	closedir $dh;
	return \@out;
}

get '/manager/voice_release' => sub($c) {
	my $signatorial = $c->param('signatorial');
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($rm) { $c->rendered(403); return; }
	my $hostname = `hostname`; chomp $hostname;
	$c->render(json => { hostname => $hostname, signatorial => &subs::signatorial_designer(), voices => &voice_lister() });
};

get '/manager/voice_download' => sub($c) {
	my $signatorial = $c->param('signatorial');
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($rm) { $c->rendered(403); return; }
	my $file = $c->param('file') || '';
	# a plain model filename inside voices/, never a path
	unless ($file =~ /^[A-Za-z0-9_.-]+\.onnx(\.json)?$/) { $c->rendered(404); return; }
	my $path = &subs::home('~/jawnos/voices') . '/' . $file;
	unless (-f $path) { $c->rendered(404); return; }
	$c->res->headers->content_type('application/octet-stream');
	$c->res->headers->content_disposition('attachment; filename="' . $file . '"');
	$c->res->content->asset(Mojo::Asset::File->new(path => $path));
	$c->rendered(200);
};


# Released by the guard in remote_upgrade on every exit, including a die, so a
# pull that crashes part-way no longer leaves a live-looking 'running' marker
# behind. The age/pid check still covers a worker the kernel killed.
{
	package Jawn::RemoteUpgradeLock;
	sub new { my ($class, $val) = @_; return bless { val => $val }, $class; }
	sub release {
		my $self = shift;
		return unless $self->{'val'};
		my $val = $self->{'val'};
		$self->{'val'} = undef;
		eval {
			my $row = &subs::db_query('select value from settings where app = ? and setting = ? order by cast(server_time as integer) desc limit 1', '__president', 'remote_upgrade')->hashes->[0];
			&subs::setting_setter({ app => '__president', setting => 'remote_upgrade', value => '' }) if (($row->{'value'} || '') eq $val);
		};
	}
	sub DESTROY { shift->release }
}

# One encrypted batch of a table's rows: the wire unit of the v3 sync rail. The
# cursor is the last rowid the caller already has, so a dropped tunnel costs the
# batch, not the pull; the total is sent with the first batch for progress.
sub sync_rows_batch {
	my ($remote, $signatorial, $secret, $table, $cut, $after) = @_;
	my $url = $remote->{'manager'} . '/manager/sync_rows?signatorial=' . $signatorial
		. '&table=' . Mojo::Util::url_escape($table)
		. '&cut=' . int($cut) . '&limit=500';
	$url .= '&after=' . Mojo::Util::url_escape($after) if defined $after && $after ne '';
	my $res;
	for my $attempt (1 .. 3) {
		$res = eval { $remote->{'ua'}->inactivity_timeout(60)->request_timeout(120)->get($url)->result };
		last if $res && $res->is_success;
		# A 4xx is the peer's answer (auth, an unknown table); retrying it only
		# delays the fallback. A dropped link or a 5xx is worth another try.
		last if $res && $res->code < 500;
		sleep 1 if $attempt < 3;
	}
	return (undef, 'the peer did not answer') unless $res;
	return (undef, 'HTTP ' . $res->code) unless $res->is_success;
	my $type = $res->headers->content_type || '';
	if ($type !~ m{octet-stream}) {
		# An unsealed reply is the producer refusing the request (auth, an unknown
		# table, or a local failure). A table this side knows and the peer does not
		# is a schema-skew skip, not a failed pull.
		my $err = eval { decode_json($res->body) } || {};
		my $why = $err->{'error'} || 'the peer refused the batch';
		return (undef, $why, ($why eq 'unknown table' ? 1 : 0));
	}
	my $plain = eval { &subs::decrypter($secret, $res->body) };
	return (undef, 'the batch would not decrypt') unless defined $plain && length $plain;
	my $batch = eval { decode_sereal($plain) };
	return (undef, 'the batch would not decode') unless ref $batch eq 'HASH';
	return (undef, $batch->{'error'} || 'the peer refused the batch') unless $batch->{'ok'};
	# The sealed response is what crossed the wire; record it so a v3 pull's size is
	# visible in `backups.size` and the job note, the way a snapshot's size was.
	$batch->{'wire_bytes'} = length($res->body // '');
	return ($batch, undef);
}

# Pull a peer's rows as encrypted batches and merge them with the same per-row
# rules the snapshot path uses. Only the local watermark and `sync_seen` move, and
# only after every table finished: a short batch leaves the next tick to retry.
sub sync_rows_pull {
	my ($c, $params, $sync, $job, $remote_machine, $auuid) = @_;
	# A peer on newer code may carry a table this database has not been migrated for
	# yet; the snapshot path got this through merge_database. Run it here too, then
	# drop the cached table list so the new table is actually requested.
	&update_database($c);
	$subs::sync_table_cache = undef;
	my $remote = $remote_machine || &remote_useragent_maker({ signatorial => $params->{'remote_signatorial'} });
	# The yellow panel names the job's phase, and this path has no export to wait
	# on: it is reading and merging rows. Say so instead of leaving it at the
	# snapshot phase the job was created with.
	&subs::db_query("update sync_jobs set phase = 'merge' where uuid = ?", $job);
	my $remote_signatorial = $params->{'remote_signatorial'} || $remote->{'signatorial'};
	my $signatorial = &subs::signatorial_designer();
	my $suds = &subs::session_suds($c) || &subs::suds_grabber();
	my $security = &subs::db_select('security', ['credential'], { level => 1 })->hash || {};
	my $secret = &subs::decrypter($suds, $security->{'credential'} || '');
	unless (defined $secret && length $secret) {
		$sync->done('failed', 'no shared credential for the row stream');
		return 'failed';
	}
	my $colour = $remote->{'data'}->{'manager_colour'};
	my $deletions = eval { return decode_json($remote->{'deletions'} || '[]') } || [];
	my $rdel = &subs::db_select('remote_machines', ['deletions'], {})->hashes;
	foreach my $rd (@{$rdel}) {
		my $all = eval { return decode_json($rd->{'deletions'} || '[]') } || [];
		push @{$deletions}, @{$all};
	}
	my $configuration = {
		signatorial => $remote_signatorial,
		remote => $remote,
		sync_job => $job,
		colour => $colour,
	};
	my @updateables;
	my @cache_bucket_updateables;
	my $ctx = {
		configuration => $configuration,
		misc_settings => &misc_setting_list(),
		device => &subs::device_setter(),
		deletions => $deletions,
		universal_settings => {},
		updateables => \@updateables,
		cache_bucket_updateables => \@cache_bucket_updateables,
		sync_job => $job,
		auuid => $auuid,
		colour => $colour,
	};
	my $plan = (ref $params->{'plan'} eq 'HASH') ? $params->{'plan'} : {};
	my $default_cut = (defined $params->{'default_cut'} && $params->{'default_cut'} =~ /^[0-9]+$/) ? $params->{'default_cut'} : 0;
	my @tables = @{ &subs::sync_table_list() };
	# With a plan (the digest says what differs), fetch only the tables that moved
	# plus the carry-only streams. Without one, this is a first/cold pull: every
	# table from the window, as the snapshot path did. The carry-only tables have
	# no digest trigger by design (continent is a location stream), so they must
	# always ride along or a device's travel map stops learning where the others are.
	my $have_plan = (ref $params->{'plan'} eq 'HASH' && scalar keys %{$params->{'plan'}}) ? 1 : 0;
	my %carry = map { $_ => 1 } qw(continent ai_budget ai_jobs ai_house notifications);
	my %fetch;
	if (!$have_plan) {
		$fetch{$_} = 1 for @tables;
	}
	else {
		$fetch{$_} = 1 for grep { exists $plan->{$_} || $carry{$_} } @tables;
		# An appointment carries no app configuration of its own. If an appointment
		# is being pulled, carry the settings delta too, or its window opens with an
		# empty app until a later tick notices the settings on their own.
		$fetch{'settings'} = 1 if $fetch{'appointments'};
	}
	# Settings first: the window that an appointment opens reads its app's settings,
	# so they must already be merged when the appointment's header is refreshed.
	my %rank = (settings => 0, appointments => 1);
	my @ordered = sort { ($rank{$a} // 2) <=> ($rank{$b} // 2) || $a cmp $b } grep { $fetch{$_} } @tables;
	my $settings_count = -1;
	my $table_total = scalar @ordered;
	my $count = 0;
	my $watermark = 0;
	my $wire = 0;
	my $failed;
	foreach my $table (@ordered) {
		my $cut = (exists $plan->{$table} && defined $plan->{$table}) ? $plan->{$table} : $default_cut;
		$cut = 0 unless defined $cut && $cut =~ /^[0-9]+$/;
		if ($table eq 'settings') {
			# A machine with no settings at all (a fresh install, a restored empty
			# database) has no watermark to delta against: send the whole table once.
			$settings_count = &subs::db_query('select count(*) as c from settings')->hashes->[0]->{'c'} || 0 if $settings_count < 0;
			$cut = 0 unless $settings_count;
		}
		my ($first, $err, $skip) = &sync_rows_batch($remote, $signatorial, $secret, $table, $cut, '');
		next if $skip;
		unless ($first) {
			$failed = $table . ': ' . ($err || 'no answer');
			last;
		}
		$watermark = $first->{'server_time'} || $watermark if !$watermark;
		$wire += $first->{'wire_bytes'} || 0;
		my $total = $first->{'total'} || 0;
		next unless $total;
		$count++;
		my @queue = @{ $first->{'rows'} || [] };
		my $cursor = $first->{'next'} || '';
		my $done = $first->{'done'} ? 1 : 0;
		my $fetched = scalar @queue;
		my $fetch_error;
		&subs::sync_job_step($job, 'merge:' . $table, { label => 'merge ' . $table, state => 'running', current => $fetched, total => $total });
		my $next_row = sub {
			while (!scalar @queue) {
				return undef if $done || $fetch_error || $cursor eq '';
				my ($batch, $why) = &sync_rows_batch($remote, $signatorial, $secret, $table, $cut, $cursor);
				unless ($batch) { $fetch_error = $why || 'a batch failed'; return undef; }
				@queue = @{ $batch->{'rows'} || [] };
				$cursor = $batch->{'next'} || '';
				$done = $batch->{'done'} ? 1 : 0;
				$wire += $batch->{'wire_bytes'} || 0;
				$fetched += scalar @queue;
				&subs::sync_job_step($job, 'merge:' . $table, { current => $fetched, total => $total });
			}
			my $row = shift @queue;
			delete $row->{'__sync_rowid'} if ref $row eq 'HASH';
			$watermark = $row->{'server_time'} if ref $row eq 'HASH' && defined $row->{'server_time'} && $row->{'server_time'} > $watermark;
			return $row;
		};
		my $short = &merge_table_rows($ctx, $table, $next_row, 0, $count, $table_total);
		if ($short || $fetch_error) {
			$failed = $table . ': ' . ($fetch_error || 'short read');
			last;
		}
	}
	&merge_finish($ctx);
	if ($failed) {
		&subs::sync_job_step($job, 'merge', { state => 'failed', note => $failed });
		$sync->done('failed', $failed);
		return 'failed';
	}
	# The puller's own watermark: what the reconnector hands the peer as `since`
	# next tick. Written only after every table finished, so a short pull retries.
	if (!$params->{'gimme'} && $watermark) {
		&subs::db_query('delete from backups where ost < ? and recipient = ? and signatorial = ? and reason = ?', $watermark, $signatorial, $remote_signatorial, 'remote_upgraded');
		&subs::db_update('backups', { server_time => $watermark, reason => 'remote_upgraded', size => $wire }, {
			recipient => $signatorial,
			signatorial => $remote_signatorial,
		});
		my $seen = &subs::db_query('select count(*) as c from backups where reason = ? and recipient = ? and signatorial = ?', 'remote_upgraded', $signatorial, $remote_signatorial)->hashes->[0] || {};
		unless ($seen->{'c'}) {
			&subs::db_insert('backups', {
				timestamp => &subs::rightNow(),
				server_time => $watermark,
				reason => 'remote_upgraded',
				recipient => $signatorial,
				signatorial => $remote_signatorial,
				destination => $params->{'database'},
				warranty => &subs::ago_calc('-20m', &subs::rightNow()),
				uuid => &subs::random_string_creator(25)
			});
		}
		if (ref $params->{'remote_digest'} eq 'HASH') {
			my $prior = &subs::sync_seen_get($remote_signatorial) || {};
			my %seen_map;
			foreach my $t ( keys %{$params->{'remote_digest'}} ) {
				my $d = $params->{'remote_digest'}->{$t};
				next unless ref $d eq 'HASH';
				my $pk = ($t eq 'settings_durable') ? 'settings' : $t;
				my $cut = $plan->{$pk};
				my $full = (defined $cut && $cut == 0) ? 1 : ((ref $prior->{$t} eq 'HASH' && $prior->{$t}->{'full'}) ? 1 : 0);
				$seen_map{$t} = { %{$d}, full => $full };
			}
			&subs::sync_seen_set($remote_signatorial, \%seen_map);
		}
		&subs::sync_backoff_clear($remote_signatorial);
	}
	&subs::sync_job_step($job, 'merge', { state => 'done', current => 1, total => 1 });
	$sync->done('done', 'rows merged ' . &subs::data_size($wire));
	return 'done';
}

# v3 producer: one table's rows in a bounded, encrypted batch. Deliberately no
# temp SQLite: the caller's cursor is a rowid, and the response is Sereal+zstd
# sealed with the same shared security credential the snapshot container uses.
# The route peer_verifies the caller (or accepts an approved session), exactly
# like the rest of the sync rail.
get '/manager/sync_rows' => sub ($c) {
	my $signatorial = $c->param('signatorial');
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($c->session('authentication') eq 'approved' || ($rm && &subs::peer_verify($c, $rm))) {
		$c->rendered(403);
		return;
	}
	my $suds = &subs::session_suds($c) || &subs::suds_grabber();
	my $security = &subs::db_select('security', ['credential'], { level => 1 })->hash || {};
	my $secret = &subs::decrypter($suds, $security->{'credential'} || '');
	unless (defined $secret && length $secret) {
		$c->render(json => { ok => 0, error => 'no shared credential' });
		return;
	}
	my $table = $c->param('table') || '';
	my %allowed = map { $_ => 1 } @{ &subs::sync_table_list() };
	unless ($allowed{$table}) {
		$c->render(json => { ok => 0, error => 'unknown table' });
		return;
	}
	my $cut = $c->param('cut');
	$cut = 0 unless defined $cut && $cut =~ /^[0-9]+$/;
	my $limit = $c->param('limit');
	$limit = 500 unless defined $limit && $limit =~ /^\d+$/ && $limit > 0 && $limit <= 2000;
	my $after = $c->param('after');
	$after = '' unless defined $after && $after =~ /^\d+$/;
	my $where = ' where server_time >= ?';
	my @args = ($cut);
	my @after_args;
	if ($after ne '') {
		$where .= ' and rowid > ?';
		@after_args = ($after);
	}
	if ($table eq 'appointments') { $where .= " and (status is null or status != 'deleting')"; }
	elsif ($table eq 'settings') { $where .= " and (setting is null or setting not in ('open_tabs','scrollTop','jopen','dimensions'))"; }
	my $total = 0;
	if ($after eq '') {
		$total = &subs::db_query('select count(*) as c from ' . $table . $where, @args)->hashes->[0]->{'c'} || 0;
	}
	my $rows = &subs::db_query('select rowid as __sync_rowid, * from ' . $table . $where . ' order by rowid limit ?', @args, @after_args, $limit + 1)->hashes || [];
	my $more = scalar(@{$rows}) > $limit ? 1 : 0;
	splice @{$rows}, $limit if $more;
	my $next = '';
	$next = $rows->[-1]->{'__sync_rowid'} if $more && scalar @{$rows};
	my $plain = eval { encode_sereal({ ok => 1, table => $table, rows => $rows, total => $total, next => $next, done => ($more ? 0 : 1), server_time => &subs::rightNow() }, { compress => SRL_ZSTD, compress_level => 3 }) };
	unless (defined $plain) {
		$c->render(json => { ok => 0, error => 'could not encode the batch' });
		return;
	}
	my $sealed = eval { &subs::encrypter($secret, $plain) };
	unless (defined $sealed) {
		$c->render(json => { ok => 0, error => 'could not seal the batch' });
		return;
	}
	$c->res->headers->content_type('application/octet-stream');
	$c->render(data => $sealed);
};

	sub remote_upgrade($c,$params) {
	# The marker carries the worker's pid. A restart or a crash is the common case
	# here, and a bare 'running' left behind by a dead worker used to block every
	# pull for the full ten-minute age bound. Only a live owner blocks, and the
	# age bound remains for a pid that was recycled. The caller that has already
	# claimed the marker passes it as `marker`; this child adopts that claim and
	# replaces it with its own pid, so the race window between fork and claim is
	# closed.
	my $adopt = $params->{'marker'} ? 1 : 0;
	my $up_state = &subs::db_query('select value,server_time from settings where app = ? and setting = ? order by cast(server_time as integer) desc limit 1', '__president', 'remote_upgrade')->hashes->[0] || {};
	my ($up_flag, $up_pid) = split /:/, ($up_state->{'value'} || ''), 2;
	$up_flag ||= '';
	my $up_live = ($up_flag eq 'running' && $up_pid && $up_pid =~ /^\d+$/ && $up_pid > 1 && kill(0, $up_pid)) ? 1 : 0;
	my $up_bound = $up_live ? 1800000 : 600000;
	if (!$adopt && $up_flag eq 'running' && (!$up_pid || $up_live) && int($up_state->{'server_time'} || 0) + $up_bound > &subs::rightNow()) {
		return;
	}
	my $up_value = 'running:' . $$;
	&subs::setting_setter({ app => '__president', setting => 'remote_upgrade', value => $up_value });
	# Two forked pulls can pass the check above in the same instant; the last
	# writer keeps the marker and the loser walks away instead of running a
	# second export against the same peer.
	my $up_confirm = &subs::db_query('select value from settings where app = ? and setting = ? order by cast(server_time as integer) desc limit 1', '__president', 'remote_upgrade')->hashes->[0] || {};
	return 'busy' if (($up_confirm->{'value'} || '') ne $up_value);
	my $up_guard = Jawn::RemoteUpgradeLock->new($up_value);
	# One job row drives the yellow dot: its ring is the overall percent and its
	# steps are the bars across the top of the panel. The guard below still stops
	# two pulls at once; the job is what makes the wait legible.
	my $job = &subs::sync_job_start({
		direction => 'pull',
		peer => ($params->{'peer'} || $params->{'ip'} || ''),
		phase => 'export',
		# The path is chosen below. A snapshot-flavoured note here made every
		# v3 pull look like it was waiting on an export until it finished, which
		# is exactly the wrong thing to read while watching the mesh.
		note => 'pulling'
	});
	my $sync = Jawn::SyncJob->new($job);
	my $timestamp = $params->{'timestamp'};
	my $ip = $params->{'ip'};
	my $vip = $ip;
	my $port = $params->{'ssh_port'};
	my $hostname = $params->{'hostname'};
	my $database = $params->{'database'};
	my $gimme = $params->{'gimme'};
	# A migration is a full-table pull that *does* advance the watermark: the
	# window is the whole history, but the merge is a real reconciliation.
	my $full = $params->{'full'} ? 1 : 0;
	my $remote_signatorial = $params->{'remote_signatorial'};
	my $remote_device = $params->{'remote_device'};
	my $remote_machine = $params->{'remote_machine'};
	my @database = split '/', ($database || '');
	my @extender = split /\./, ($database[-1] // '');
	if (@extender) {
		$extender[-1] = 'enc';
		$database[-1] = join '.', @extender;
		$database = join '/', @database;
	}

	my $folder = '~/';
	my $connector;
	my $signatorial = &subs::signatorial_designer();
	my $download_location = &subs::home('~/.president');
	my $temp_folder = &subs::home($download_location . '/' . &subs::random_string_creator(10));

	$remote_machine = &remote_useragent_maker({ signatorial => $remote_signatorial });
	my $auuid = &subs::random_string_creator(10);
	# v3: a normal delta pull is a sequence of encrypted row batches, not a temp
	# SQLite snapshot. A full migration and a windowed deep pull keep the snapshot
	# path, which is what those two were designed for.
	if (($params->{'sync_version'} || 0) >= 3 && !$full && !$gimme) {
		my $status = &sync_rows_pull($c, $params, $sync, $job, $remote_machine, $auuid);
		&Websocket::send('tab', { yellow => 'Complete', 'close' => 'yes', colour => $remote_machine->{'data'}->{'manager_colour'}, state => ($status eq 'done' ? 'done' : 'failed'), progress => 100 });
		return $status;
	}
	# The snapshot path is deliberate for a full migration and a windowed deep
	# pull. Anything else reaching here is a regression and the expensive path:
	# name the reason, in manager.log (the in-app log is a small, racy ring and a
	# forked pull can lose its entry there), since the job note only says
	# 'waiting for a snapshot'.
	my $why_snapshot = 'sync_version=' . ($params->{'sync_version'} || 0) . ' full=' . ($full ? 1 : 0) . ' gimme=' . (defined $gimme && length $gimme ? $gimme : '-') . ' plan=' . (ref $params->{'plan'} eq 'HASH' ? scalar(keys %{$params->{'plan'}}) : 'none') . ' peer=' . ($remote_signatorial || '?');
	if ($subs::logfile) {
		open(my $why_fh, '>>', $subs::logfile);
		print $why_fh &subs::rightNow() . " remote upgrade: snapshot path $why_snapshot\n";
		close $why_fh;
	}
	$log->info('remote upgrade: snapshot path ' . $why_snapshot);
	&subs::log_writer('remote upgrade: snapshot path ' . $why_snapshot);
	if ($remote_machine->{'signatorial'}) {
		&subs::sync_job_step($job, 'export', { label => 'export', state => 'running', note => 'peer is building a snapshot' });
		my $html = '<h2>Running Remote Backup</h2>';
		&Websocket::send('tab', { yellow => $html, uuid => $auuid, colour => $remote_machine->{'data'}->{'manager_colour'}, progress => -1, state => 'running', job => $job });


		my $url = $remote_machine->{'manager'} . '/manager/configure/backup_now?reason=remote_update&async=1&timestamp=' . $timestamp . '&signatorial=' . $signatorial;
		# The per-table plan: each table is exported only above the point the
		# caller already holds. A table the plan omits still rides the legacy
		# window, so a peer on this code and one on older code behave alike.
		if (ref $params->{'plan'} eq 'HASH' && scalar keys %{$params->{'plan'}}) {
			$url .= '&cuts=' . Mojo::Util::url_escape(&subs::sync_map_encode($params->{'plan'}));
		}
		if ($full) {
			$gimme = undef;
			$url .= '&full=1';
		}
		if ($gimme && $gimme =~ /[A-Za-z0-9]/gi) {
			$gimme = &subs::ago_calc($gimme, &subs::rightNow());
			$url .= '&gimme=' . $gimme;
		}
		else {
			$gimme = undef;
		}
		my $ua = $remote_machine->{'ua'};

		my $res = eval { return $ua->insecure(1)->inactivity_timeout(180)->request_timeout(300)->get($url)->result };

		if ($res) {

			my $body = eval { return decode_json $res->body } || {};

			# A snapshot can take minutes to build on a slow machine. The peer
			# answers 'building' at once and the work goes on there; wait on its
			# status rather than holding this request open past the inactivity
			# timeout that used to abandon the pull. An older peer ignores async=1
			# and still replies with the finished snapshot.
			if (($body->{'status'} || '') eq 'building') {
				my $snapshot_job = $body->{'job'} || '';
				my $status_url = $remote_machine->{'manager'} . '/manager/configure/backup_status?signatorial=' . $signatorial . '&job=' . Mojo::Util::url_escape($snapshot_job);
				my $waited = 0;
				my $state = 'building';
				my $sbody = {};
				while ($snapshot_job && $waited < 1800) {
					sleep 2;
					$waited += 2;
					# Keep this pull's own lease young: a snapshot can take longer
					# than the ten-minute marker bound, and a second child must not
					# start pulling the same peer under it.
					if (($waited % 60) == 0) {
						&subs::setting_setter({ app => '__president', setting => 'remote_upgrade', value => 'running:' . $$ });
					}
					my $sres = eval { $ua->inactivity_timeout(20)->request_timeout(30)->get($status_url)->result };
					$sbody = eval { return decode_json $sres->body } || {};
					$state = $sbody->{'status'} || 'unknown';
					if ($state eq 'ready' && ref $sbody->{'result'} eq 'HASH') {
						$body = $sbody->{'result'};
						$body->{'sha256'} = $sbody->{'sha256'} if $sbody->{'sha256'};
						last;
					}
					if ($state eq 'busy' || $state eq 'failed' || $state eq 'unknown') {
						last;
					}
					# Mirror the peer's per-table rows so the receiving screen shows
					# real progress instead of a spinner.
					my ($rc, $rt, $note) = (0, 0, 'peer is building a snapshot');
					foreach my $s ( @{ $sbody->{'steps'} || [] } ) {
						next unless ref $s eq 'HASH' && ($s->{'key'} || '') =~ /^export:/;
						$rc += ($s->{'current'} || 0);
						$rt += ($s->{'total'} || 0);
						if (($s->{'state'} || '') eq 'running') {
							(my $t = $s->{'key'}) =~ s/^export://;
							$note = $t . ' ' . ($s->{'current'} || 0) . '/' . ($s->{'total'} || 0);
						}
					}
					&subs::sync_job_step($job, 'export', { current => $rc, total => $rt, note => $note });
				}
				if ($state eq 'busy') {
					&subs::sync_job_step($job, 'export', { state => 'skipped', note => 'peer was already exporting' });
					$sync->done('skipped', 'peer was already exporting');
					&subs::setting_setter({ app => '__president', setting => 'remote_upgrade', value => '' });
					return 'busy';
				}
				if ($state ne 'ready') {
					my $why = ($state eq 'failed') ? ($sbody->{'error'} || 'the peer failed to build the snapshot') : 'the peer did not finish the snapshot';
					&subs::sync_job_step($job, 'export', { state => 'failed', note => $why });
					$sync->done('failed', $why);
					&Websocket::send('tab', { yellow => '<h2>Export failed</h2>', 'close' => 'yes', colour => $remote_machine->{'data'}->{'manager_colour'}, state => 'failed', progress => 100 });
					&subs::setting_setter({ app => '__president', setting => 'remote_upgrade', value => '' });
					return 'failed';
				}
			}

			if (($body->{'status'} || '') eq 'busy') {
				# A peer already exporting to someone else is not a failure: it is
				# normal contention, and the backoff retries shortly. Keep the dot
				# quiet rather than painting a red cross every two minutes.
				&subs::sync_job_step($job, 'export', { state => 'skipped', note => 'peer was already exporting' });
				$sync->done('skipped', 'peer was already exporting');
				&subs::setting_setter({ app => '__president', setting => 'remote_upgrade', value => '' });
				return 'busy';
			}

			if ($body->{'path'} && $body->{'signatorial'}) {
				&subs::sync_job_step($job, 'export', { state => 'done', current => 1, total => 1 });

				if (1) {
					if ($body->{'remote_update'}) {
						my $html = '<h2>Updating Database</h2>';
						&Websocket::send('tab', { yellow => $html, uuid => $auuid, colour => $remote_machine->{'data'}->{'manager_colour'}, progress => 1, state => 'running'  });
						&update_database({ commands => $body->{'update_commands'} });
					}
					`mkdir -p $temp_folder` unless -e "$temp_folder";
					my $temporary_file = $temp_folder . '/tmpman_' . &subs::random_string_creator(4) . '.enc';
					if ($remote_machine->{'tunnel'} eq 'yes') {
						my $tun = &subs::tunnel_port_mapper({ signatorial => $remote_signatorial });
						$vip = '127.0.0.1';
						$remote_machine->{'manager'} = 'https://127.0.0.1:' . $tun->{'PORT_AHOY'};
					}
					if ($body->{'raw_data'} && $body->{'size'} < 2000000) {
						write_file($temporary_file, $body->{'raw_data'});
						&subs::sync_job_step($job, 'download', { label => 'download', state => 'done', current => 1, total => 1 });
					}
					else {
						my $html = '<h2>Syncing Remote Backup ' . &subs::data_size($body->{'size'}) . '</h2>';
						&Websocket::send('tab', { yellow => $html, uuid => $auuid, colour => $remote_machine->{'data'}->{'manager_colour'}, progress => 2, state => 'running'  });
						my $dl_total = $body->{'size'} || 0;
						&subs::sync_job_step($job, 'download', { label => 'download', state => 'running', current => 0, total => $dl_total });
						# pull the encrypted archive over http - no ssh, no stored
						# password. The peer serves it through the same tunnel and
						# session as every other manager-to-manager request. Ask for
						# ranges so a dropped tunnel resumes at the byte it reached
						# instead of starting the whole snapshot over.
						my $turl = $remote_machine->{'manager'} . '/manager/backup_serve?signatorial=' . $signatorial . '&file=' . Mojo::Util::url_escape($body->{'archive_path'});
						my $part = $temporary_file . '.part';
						my $want_sha = $body->{'sha256'} || '';
						my $chunk = 4 * 1024 * 1024;
						my $offset = 0;
						$offset = -s $part if (-e $part && (!$dl_total || (-s $part) <= $dl_total));
						my $short_download = 0;
						if (open my $fh, ($offset ? '>>:raw' : '>:raw'), $part) {
							my $fails = 0;
							while (!$dl_total || $offset < $dl_total) {
								my $end = $dl_total ? ($offset + $chunk - 1) : '';
								$end = $dl_total - 1 if $dl_total && $end >= $dl_total;
								my $header = $dl_total ? { Range => "bytes=$offset-$end" } : {};
								my $tx = eval { $remote_machine->{'ua'}->inactivity_timeout(120)->request_timeout(180)->get($turl => $header) };
								my $tres = $tx ? $tx->result : undef;
								if (!$tres || !$tres->is_success) {
									$fails++;
									last if $fails >= 6;
									sleep 1;
									next;
								}
								$fails = 0;
								my $bytes = $tres->body;
								if ($tres->code == 200) {
									# The peer ignored Range: its body is the whole file.
									close $fh;
									write_file($part, $bytes);
									open $fh, '>>:raw', $part;
									$offset = length($bytes);
									last;
								}
								else {
									print $fh $bytes;
									$offset += length($bytes);
								}
								last unless length($bytes);
								&subs::sync_job_step($job, 'download', { current => $offset, total => ($dl_total || $offset) });
								last unless $dl_total;
							}
							close $fh;
						}
						if ((!$dl_total || $offset == $dl_total) && -s $part) {
							rename $part, $temporary_file;
							if ($want_sha) {
								my $got = eval { require Digest::SHA; Digest::SHA->new(256)->addfile($temporary_file)->hexdigest };
								if ($got && $got ne $want_sha) {
									$short_download = 1;
									$log->error('remote download sha mismatch: got=' . $got . ' expected=' . $want_sha) if $log;
									unlink $temporary_file;
								}
							}
						}
						else {
							$short_download = 1;
							$log->error('remote download short: got=' . ($offset || 0) . ' expected=' . $dl_total) if $log;
							unlink $temporary_file if -e $temporary_file;
						}
						&subs::sync_job_step($job, 'download', { state => ($short_download ? 'failed' : 'done'), current => ($dl_total || $offset || 1), total => ($dl_total || $offset || 1), note => ($short_download ? 'short download' : '') });
					}
					if (-e $temporary_file) {
						my $disposition = &merge_database($c,{
							file => $temporary_file,
							signatorial => $body->{'signatorial'},
							misc_settings => $body->{'misc_settings'},
							remote => $remote_machine,
							gimme => $gimme,
							sync_job => $job,
							colour => $remote_machine->{'data'}->{'manager_colour'}
						});
						`shred -u $temporary_file`;
						`rm -R $temp_folder`;
						if (($disposition->{'status'} || '') ne 'succeed') {
							# Do not confirm a merge that did not finish: the peer would mark the
							# snapshot delivered while this machine still lacks it.
							$sync->done('failed', 'merge did not finish');
							&Websocket::send('tab', { yellow => '<h2>Merge failed</h2>', 'close' => 'yes', colour => $remote_machine->{'data'}->{'manager_colour'}, state => 'failed', progress => 100 });
							&subs::setting_setter({ app => '__president', setting => 'remote_upgrade', value => '' });
							return 'failed';
						}
					} else {

						&subs::sync_job_step($job, 'download', { state => 'failed', note => 'the peer did not send the snapshot' });
						$sync->done('failed', 'the peer did not send the snapshot');
						&Websocket::send('tab', { yellow => 'Complete', 'close' => 'yes', colour => $remote_machine->{'data'}->{'manager_colour'}, state => 'failed', progress => 100  });
						&subs::setting_setter({ app => '__president', setting => 'remote_upgrade', value => '' });
						&subs::say_it('ssh fail');
						`rm -R $temp_folder`;
						return 'failed';
					}
					&subs::setting_setter({ app => '__president', setting => 'remote_upgrade', value => '' });
			#		&subs::db_update('remote_machines', { connection => 'inactive' }, { ip => $ip, signatorial => $remote_machine->{'signatorial'}, uuid => $remote_machine->{'uuid'} });


					&subs::sync_job_step($job, 'confirm', { label => 'confirm', state => 'running' });
					my $defunct_backups = &subs::db_query('select * from backups where ost < ? and recipient = ? and signatorial = ? and reason=?', $body->{'server_time'}, $signatorial, $remote_machine->{'signatorial'}, 'remote_upgraded' )->hashes;
					foreach my $defb ( @{$defunct_backups} ) {
						if ($defb->{'enc_file'} && -e $defb->{'enc_file'}) {
							my $delb = $defb->{'enc_file'};
							`shred -u $delb`;
						}
					}
					my $url = $remote_machine->{'manager'} . '/manager/backup/confirm';
					my $form_data = {
						signatorial => &subs::signatorial_designer(),
						# A windowed (gimme/deep) pull is not proof that this machine holds
						# everything before the window, so it must not advance the peer's
						# watermark past that point.
						gimme => ($gimme ? 1 : 0),
						# The server's confirm reads only these two fields. It used to be
						# handed the whole backup_now reply, which carries misc_settings
						# (every setting on the machine) and update_commands and grew past
						# the point a POST survives the trip: the body stalled on the wire
						# and the peer closed the connection before responding. A few KB
						# is all the other side ever reads, so send that.
						backup_confirm => encode_json({
							backup_data => $body->{'backup_data'},
							ld_server_time => $body->{'ld_server_time'},
						})
					};
					#	&subs::tunnel_stopper({ signatorial => $signatorial });
					# A close here used to die out of the subprocessor with only "Premature
					# connection close" and no URL or status to say where it was aimed.
					# Keep the pull's failed state, and say what the peer answered.
					my $res = eval { $remote_machine->{'ua'}->post($url => form => $form_data)->result };
					if (!$res || !$res->is_success) {
						my $why = $@ || '';
						$why =~ s/\s+/ /g;
						my $rbody = ($res && $res->body) ? substr($res->body, 0, 300) : '';
						$rbody =~ s/\s+/ /g;
						eval { $log->error('remote confirm failed: status=' . (($res && $res->code) || 0) . ' err=' . $why . ' url=' . $url . ' bytes=' . length($form_data->{'backup_confirm'} || '') . ' body=' . $rbody) };
					}
					if ($res && $res->is_success) {
						# A gimme/deep pull is a repair window, not a watermark: deleting
						# the old watermark or moving it to the window's end would claim
						# this machine holds everything before a point it never read.
						if (!$gimme) {
							&subs::db_query('delete from backups where ost < ? and recipient = ? and signatorial = ? and reason=?', $body->{'server_time'}, $signatorial, $remote_machine->{'signatorial'}, 'remote_upgraded' );
							# Record the snapshot that actually moved: this row may predate the
							# size fix and still carry this machine's whole database (~180 MB).
							&subs::db_update('backups', { server_time => $body->{'server_time'}, reason => 'remote_upgraded', size => $body->{'size'} }, {
								recipient => $signatorial,
								signatorial => $remote_machine->{'signatorial'},
							});
							# The puller's own watermark is what tells the reconnector it has
							# caught up (and what it hands the peer as `since`). A cold pull
							# has no row to update yet, so create one; without it the peer
							# looked new every tick and pulled the whole database again.
							my $seen = &subs::db_query('select count(*) as c from backups where reason = ? and recipient = ? and signatorial = ?', 'remote_upgraded', $signatorial, $remote_machine->{'signatorial'})->hashes->[0] || {};
							unless ($seen->{'c'}) {
								&subs::db_insert('backups', {
									timestamp => ($body->{'timestamp'} || &subs::rightNow()),
									server_time => $body->{'server_time'},
									reason => 'remote_upgraded',
									recipient => $signatorial,
									signatorial => $remote_machine->{'signatorial'},
									destination => $body->{'database'},
									enc_file => $body->{'archive_path'},
									size => $body->{'size'},
									warranty => &subs::ago_calc('-20m', &subs::rightNow()),
									uuid => &subs::random_string_creator(25)
								});
							}
						}
						&subs::sync_job_step($job, 'confirm', { state => 'done', current => 1, total => 1 });
						$sync->done('done', 'snapshot merged');
						# The peer's picture is reconciled: remember it, so the planner can
						# skip this exact picture instead of full-reading a peer that is
						# merely behind. `full` records whether this table was read whole:
						# a delta-only pull leaves it false, so the next tick does the one
						# full read rather than pretending the old rows are reconciled. A
						# windowed gimme/deep pull records nothing.
						if (!$gimme && ref $params->{'remote_digest'} eq 'HASH') {
							my $prior = &subs::sync_seen_get($remote_machine->{'signatorial'}) || {};
							my $plan = (ref $params->{'plan'} eq 'HASH') ? $params->{'plan'} : {};
							my %seen;
							foreach my $t ( keys %{$params->{'remote_digest'}} ) {
								my $d = $params->{'remote_digest'}->{$t};
								next unless ref $d eq 'HASH';
								my $pk = ($t eq 'settings_durable') ? 'settings' : $t;
								my $cut = $plan->{$pk};
								my $full = (defined $cut && $cut == 0) ? 1 : ((ref $prior->{$t} eq 'HASH' && $prior->{$t}->{'full'}) ? 1 : 0);
								$seen{$t} = { %{$d}, full => $full };
							}
							&subs::sync_seen_set($remote_machine->{'signatorial'}, \%seen);
						}
						&subs::sync_backoff_clear($remote_machine->{'signatorial'});
					}
					else {
						&subs::sync_job_step($job, 'confirm', { state => 'failed', note => 'the peer did not confirm the merge' });
						$sync->done('failed', 'the peer did not confirm the merge');
					}
				}
			}
			else {
				$sync->done('failed', 'the peer sent no snapshot');
			}
		}
		else {
			$sync->done('failed', 'the peer did not answer');
		}


		&Websocket::send('tab', { yellow => 'Complete', 'close' => 'yes', colour => $remote_machine->{'data'}->{'manager_colour'}, state => ($sync->{'state'} || 'done'), progress => 100  });
	}
	else {
		$sync->done('failed', 'the peer is not reachable');
	}
	&subs::setting_setter({ app => '__president', setting => 'remote_upgrade', value => '' });
	return ($sync->{'state'} || 'done');
};

post '/manager/backup/confirm' => sub($c) {
	# confirmed over the same gate-exempt signed rail: a session or a peer
	# signature (the caller names itself in `signatorial`).
	my $signatorial = $c->param('signatorial');
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($c->session('authentication') eq 'approved' || ($rm && &subs::peer_verify($c, $rm))) {
		$c->rendered(403);
		return;
	}
	my $backup_confirm = eval { return decode_json $c->param('backup_confirm') };
	my $backup_data = $backup_confirm->{'backup_data'};
	my $returner = $backup_data;
	if ($backup_data->{'server_time'}) {
		# This is the *completed* snapshot. It was built with reason
		# `remote_update` (the in-flight name), and storing it under that name
		# meant backup_now's watermark query - which looks for `remote_upgraded`
		# - never found it. Every pull then looked like a cold peer and re-exported
		# the whole database, holding the single export lock while it did and
		# telling every other machine "already exporting". Store the confirmation
		# under the name the watermark actually reads.
		$backup_data->{'reason'} = 'remote_upgraded' if (!$c->param('gimme') && ($backup_data->{'reason'} || '') eq 'remote_update');
		my $signatorial = &subs::signatorial_designer();
		my $defunct_backups = &subs::db_query('select * from backups where recipient = ? and signatorial = ? and ost < ?', $backup_data->{'recipient'}, $signatorial, $backup_confirm->{'ld_server_time'})->hashes;
		foreach my $defb ( @{$defunct_backups} ) {
			if ($defb->{'enc_file'} && -e $defb->{'enc_file'}) {
				my $delb = $defb->{'enc_file'};
				`shred -u $delb`;
			}
			&deletion_registration({ table => 'backups', uuid => $defb->{'uuid'}, scope => 'single', server_time => $defb->{'server_time'} });
			&subs::db_delete('backups', { uuid => $defb->{'uuid'} });
		}
		my $last_updated = &subs::db_query('delete from backups where recipient = ? and signatorial = ? and ost <= ?', $backup_data->{'recipient'}, $signatorial, $backup_data->{'ld_server_time'});
		&subs::db_insert('backups', $backup_data);
	}
	if (-e $backup_data->{'enc_file'}) {
		my $f = $backup_data->{'enc_file'};
		`shred -u $f`;
	}
	# The puller's confirmation is what makes a migration done: mark the
	# snapshot row it was waiting on, so Dev's status follows the real finish
	# rather than the build's ready.
	&subs::db_update('sync_snapshots', { state => 'done', updated => &subs::rightNow() }, { archive_path => $backup_data->{'enc_file'} }) if $backup_data->{'enc_file'};
	$c->render(json => $returner);
};


post '/manager/configure/remote_device_disconnect' => sub ($c) {
	my $ip = $c->param('ip');
	my $signatorial = $c->param('signatorial');
	my ($db,$database,$sql) = &subs::database_grabber();
#	&subs::db_delete('remote_machines', { ip => $ip });
	&subs::db_delete('remote_machines', { signatorial => $signatorial });
	$c->render('text' => 'ok');
};



get '/manager/configure/remote_device_connect' => sub ($c) {
	my $manager = $c->param('manager');
	my $filename = $c->param('filename');
	my $timestamp = $c->param('timestamp');
	my $ip = $c->param('ip');
	my $port = $c->param('port');
	my $password = &subs::session_suds($c);
	my $browser_tab_id = $c->param('browser_tab_id');
	my $browser_tab = $c->param('browser_tab');
	my $name = $c->session('name');
	my $signatorial = $c->param('signatorial');
	my $tunnel = $c->param('tunnel');
	my $uuid = $c->param('uuid');
	my $nic = $c->param('nic');
	my $returner = &remote_device_connect({
		manager => $manager,
		filename => $filename,
		timestamp => $timestamp,
		ip => $ip,
		password => $password,
		name => $name,
		browser_tab_id => $browser_tab_id,
		browser_tab => $browser_tab,
		signatorial => $signatorial,
		nic => $nic,
		tunnel => $tunnel
	});
	my $device = &subs::db_select('devices', undef, { uuid => $uuid })->hash;
	my $address = decode_json $device->{'address'};
	my $neighbour = [];
	@{$neighbour} = grep { $ip eq $_->{'ip'} || $_->{'signatorial'} eq $returner->{'body'}->{'signatorial'} } @{$address->{$nic}->{'neigh'}};
	$neighbour->[0]->{'signatorial'} = $returner->{'body'}->{'signatorial'};
	$neighbour->[0]->{'fqdn'} = $returner->{'body'}->{'fqdn'};
	$neighbour->[0]->{'purpose'} = $returner->{'body'}->{'device'};
	$address = encode_json $address;
	&subs::db_update('devices', { address => $address }, { uuid => $uuid });
	$c->render(json => $returner);
};

sub remote_device_connect($rdata) {
	my $manager = $rdata->{'manager'};
	my $filename = $rdata->{'filename'};
	my $timestamp = $rdata->{'timestamp'};
	my $server_time = &subs::rightNow();
	my $ip = $rdata->{'ip'};
	my $vip = $ip;
	my $name = $rdata->{'name'};
	my $browser_tab_id = $rdata->{'browser_tab_id'};
	my $browser_tab = $rdata->{'browser_tab'};
	my $password = $rdata->{'password'};
	my $tunnel = $rdata->{'tunnel'};
	my $nic = $rdata->{'nic'};
	my $port = $rdata->{'port'} || $ENV{PORT_DOCK};
	my $signatorial = &subs::signatorial_designer();
	my $dock_port = $rdata->{'port_dock'} || 3000;
	my $tuns = {};
	if ($tunnel eq 'yes') {
		$tuns = &subs::tunnel_port_mapper({ signatorial => $rdata->{'signatorial'} });
		$dock_port = $tuns->{'PORT_DOCK'};
		$port = $tuns->{'PORT_AHOY'};
		$manager = 'https://127.0.0.1:' . $port . '/manager';
		$vip = '127.0.0.1';
	}


	my $returner = {};
	$manager =~ s/\/manager$//gi;

	$manager =~ s/:$port/:$dock_port/gi;
	my $bti;
	my $ua = Mojo::UserAgent->new();
	my $manager_file = &manager_file_maker($name);
	my $url = $manager . '/sesh_check?silence=yes&neighbour=' . $browser_tab_id . '&numerics=' . $password . '&president=' . $filename . '&remote_timestamp=' . $timestamp . '&manager_file=' . $manager_file;
	my $res = eval { return $ua->insecure(1)->post($url)->result };

	$returner->{'body'} = eval { return decode_json $res->body };
	$port = $tuns->{'PORT_AHOY'} || $returner->{'body'}->{'port'};
	$manager =~ s/:$dock_port/:$port/gi;
	$manager =~ s/:6100/:$port/gi;
	if ($returner->{'body'}->{'fqdn'} && $ip !~ /[a-zA-Z]/ && $returner->{'body'}->{'signatorial'} ne $signatorial) {

		$returner->{'body'}->{'ip_address'} = $ip;
		my $fqdn = $returner->{'body'}->{'fqdn'};
		my $ping = `timeout .5 ping -c 1 $fqdn`;
		if ($ping =~ /ttl/gi) {
			my @ping = split /\n/, $ping;
			if ($ping[1] =~ /$ip/) {
				$manager =~ s/$ip/$fqdn/gi;

				my $devices = &subs::db_select('devices')->hashes;
				foreach my $d ( @{$devices} ) {
					my $address = eval { return decode_json $d->{'address'} };

					my @neigh = grep { $_->{'ip'} eq $ip } @{$address->{$nic}->{'neigh'}};
					#$neigh[0]->{'ip'} = $fqdn;
					$neigh[0]->{'fqdn'} = $fqdn;
					$neigh[0]->{'purpose'} = $returner->{'body'}->{'device'};
					$neigh[0]->{'ip_address'} = $ip;
					$neigh[0]->{'signatorial'} = $returner->{'body'}->{'signatorial'};
					my $jaddress = encode_json $address;
					&subs::db_update('devices', { address => $jaddress }, { uuid => $d->{'uuid'}} );
				}

				$ip = $fqdn;
			}
		}
	}

	if ($returner->{'body'}->{'authentication'} eq 'approved') {
		$ua = Mojo::UserAgent->new();
		$url = $manager . '/sesh_check?silence=yes&neighbour=' . $browser_tab_id . '&numerics=' . $password . '&president=' . $filename . '&remote_timestamp=' . $timestamp . '&manager_file=' . $manager_file;
		my $double_check = eval { return $ua->insecure(1)->post($url)->result };
		$returner->{'body'} = eval { return decode_json $double_check->body } ;

		my $signatorial = &subs::signatorial_designer();
		if ($returner->{'body'}->{'authentication'} eq 'approved') {# && $returner->{'body'}->{'signatorial'} eq &subs::signatorial_designer()) {
			# A peer that answers with our own signatorial is this machine. Filing a
			# remote machine for ourselves is what let the hub try to sync with itself
			# (and its own mirrors then doubled the stored blob every pass), so never
			# record a self row.
			return $returner if ($returner->{'body'}->{'signatorial'} || '') eq $signatorial;
			my $nd = &subs::db_select('remote_machines', undef, { signatorial => $returner->{'body'}->{'signatorial'} })->hashes;
			my $uuid = $nd->[0]->{'uuid'} ? $nd->[0]->{'uuid'} : &subs::random_string_creator(15);

			$bti = $returner->{'body'}->{'browser_tab_id'};
			my $ssh_port = $returner->{'body'}->{'ssh_port'} || $config->{'ssh_port'};
			my $remote_device = $returner->{'body'}->{'device'};

			my $buttons = [
				{ name => 'RD', class => 'neighbour_disconnect', direction => 'disconnect' },
				{ name => 'Upgrade', class => 'remote_upgrade' },
				{ name => 'cxl_up', class => 'remote_upgrade_clear' },
				{ name => '-> Me', class => 'remote_rsync', direction => 'from' },
				{ name => 'Me ->', class => 'remote_rsync', direction => 'to' }
			];
			$returner->{'button'} .= '<a target="_blank" href="' . $manager . '/manager"><button>Go</button></a> ';
			# the peer's self-reported version, so a neighbour that is behind is
			# obvious in the panel instead of a guess.
			$returner->{'button'} .= '<span class="neighbour_version" hint="their version" style="opacity:0.6;">v' . ($returner->{'body'}->{'version'} || '?') . '</span><br>';
			foreach my $b ( @{$buttons} ) {
				$returner->{'button'} .= '<button direction="' . $b->{'direction'} . '" device="' . $remote_device .'"
					home="' . $returner->{'body'}->{'pwd'} . '" signatorial="' . $returner->{'body'}->{'signatorial'} . '"
					hostname="' . $returner->{'body'}->{'hostname'} . '" uuid="' . $uuid . '" ssh_port="' . $ssh_port .'" ip="' . $ip . '"
					database="' . $returner->{'body'}->{'database'} .  '" nic="' . $nic . '"
					class="' . $b->{'class'} . '">' . $b->{'name'} . '</button>';
			}
			$returner->{'button'} .= '<span class="remote_machine_specials"><br>' .
				'G: <input type="text" name="gimme" class="gimme_input" uuid="' . $uuid . '" signatorial="' . $returner->{'body'}->{'signatorial'} . '"></span>';
			$returner->{'status'} = 'Connected';

			my $secret = &subs::db_select('security', ['credential'], { level => 1 })->hash->{credential};
			my $double = &subs::decrypter($password,$secret);
			my $opens = &subs::door_row() ? &subs::door_check($password) : (defined $double && secure_compare($password, $double));
			if ($opens) {
				$returner->{'password'} = $secret;
				my $hs = `hostname`;
				chomp $hs;
				$returner->{'hostname'} = $hs;
				my $who = `whoami`;
				chomp $who;
				$returner->{'username'} = $who;
				$returner->{'colour'} = '#' . &subs::random_colour_grabber();
				#$ua->insecure(1)->get($manager . '/manager/say_it?words=' . &subs::setting_grabber({ app => 'me', setting => 'my_name' }) || $hs)->result;

				my $json_buttons = encode_json $buttons;
				my $remote_data = encode_json $returner->{'body'};
				my $cookie_jar = $ua->cookie_jar;
				my @cookies;
				for my $cookie (@{$cookie_jar->find(Mojo::URL->new($manager))}) {
					push @cookies, {
						name => $cookie->name,
						value => $cookie->value,
						domain => $vip,
						path => '/'
					};
				}

				my $cookies = encode_json \@cookies;

				my $remote_machine = {
					ip => $ip,
					fqdn => $returner->{'body'}->{'fqdn'},
					port => $tuns->{'PORT_AHOY'} || $port,
					ws_port => $tuns->{'PORT_MSG'} || $returner->{'body'}->{'ws_port'},
					dock_port => $tuns->{'PORT_DOCK'} || $returner->{'body'}->{'dock_port'},
					status => 'connected',
					manager => $manager,
					timestamp => $timestamp,
					server_time => $server_time,
					buttons => $returner->{'button'},
					data => $remote_data,
					signatorial => $returner->{'body'}->{'signatorial'},
					cookie => $cookies,
					connection => 'active',
					uuid => $uuid,
					nic => $nic,
					manager_file => $returner->{'body'}->{'manager_file'},
					device => $returner->{'body'}->{'device'},
					hostname => $returner->{'body'}->{'hostname'},
					version => $returner->{'body'}->{'version'},
					tunnel => $tunnel,
					mirrors => eval { return encode_json $returner->{'body'}->{'mirrors'} } || undef,
					archive => eval { return encode_json $returner->{'body'}->{'archive'} } || undef,
					archive_dir => $returner->{'body'}->{'archive_dir'}
				};

				if (scalar @{$nd} > 0 && $nd->[0]->{'uuid'}) {
					&subs::db_update('remote_machines', $remote_machine, { signatorial => $returner->{'body'}->{'signatorial'} });
				}
				else {
					&subs::db_insert('remote_machines', $remote_machine);
				}
			}
		}
	}
	return $returner;
}




post '/manager/configure/remote_machine_input' => sub($c) {
	my $signatorial = $c->param('signatorial');
	my $uuid = $c->param('uuid');
	my $value = $c->param('value');
	my $name = $c->param('name');
	# ssh credentials are gone - only benign fields ride this route now
	if ($name && $name ne 'username' && $name ne 'password') {
		&subs::db_update('remote_machines', { $name => $value }, { signatorial => $signatorial, uuid => $uuid });
	}

	$c->render(text => 'ok');
};

# A peer's signing key can outlive the row it was pinned to: a replaced row, a
# re-imaged machine, or a duplicate discovery leaves the old key on file and
# every signed request from the real machine comes back 403 (which reads as
# "not a known peer", not "wrong key"). A person logged in here can re-pin the
# key the machine actually holds. Session-gated (not in the peer allowlist), and
# it only accepts a PEM public key.
post '/manager/configure/remote_machine_key_reset' => sub($c) {
	my $signatorial = $c->param('signatorial') || '';
	my $pubkey = $c->param('pubkey') || '';
	return $c->render(json => { ok => 0, error => 'no machine named' }) unless $signatorial =~ /^[0-9a-fA-F]{16,64}$/;
	$pubkey =~ s/\r//g;
	$pubkey =~ s/\s+$//;
	unless ($pubkey eq '' || index($pubkey, '-----BEGIN PUBLIC KEY-----') == 0) {
		return $c->render(json => { ok => 0, error => 'that is not a public key' });
	}
	my $known = &subs::db_select('remote_machines', ['signatorial'], { signatorial => $signatorial })->hashes->[0];
	return $c->render(json => { ok => 0, error => 'no such machine' }) unless $known;
	&subs::db_update('remote_machines', { pubkey => $pubkey }, { signatorial => $signatorial });
	$c->render(json => { ok => 1, cleared => ($pubkey eq '' ? 1 : 0) });
};

post '/manager/configure/remote_machine/tunnel/toggle' => sub($c) {
	my $ssh_port = $c->param('ssh_port');
	my $ip = $c->param('ip');
	my $signatorial = $c->param('signatorial');
	my $uuid = $c->param('uuid');
	my $status = $c->param('status');
	my $nic = $c->param('nic');
	my $domain = $config->{'domain'} || $c->req->url->to_abs->host;
	my $device = &subs::db_select('devices', undef, { uuid => $uuid })->hashes->[0];
	my $address = eval { return decode_json $device->{'address'} };
	my @remote_device = grep { $_->{'ip'} eq $ip } @{$address->{$nic}->{'neigh'}};
	my $rd = $remote_device[0];
	if ($status eq 'active') {
		$status = 'off';
	} else {
		$status = 'active';
	}
	$rd->{'tunnel'} = $status;

	@{$address->{$nic}->{'neigh'}} = grep { $_->{'ip'} ne $ip } @{$address->{$nic}->{'neigh'}};
	push @{$address->{$nic}->{'neigh'}}, $rd;
	@{$address->{$nic}->{'neigh'}} = sort { $a->{'ip'} cmp $b->{'ip'} } @{$address->{$nic}->{'neigh'}};
	my $jaddress = encode_json $address;
	&subs::db_update('devices', { address => $jaddress }, { uuid => $uuid });

	my $tun = { ip => $ip, signatorial => $signatorial, domain => $domain };
	if ($status eq 'active') {
		&subs::tunnel_starter($tun);
	} else {
		&subs::tunnel_stopper($tun);
	}
	$c->render(json => $rd);
};

get '/manager/configure/tunnel/list' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my $returner = {
		html => $c->render_to_string(
			template => 'configure/tunnels',
		)
	};

	$c->render(json => $returner);

};


post '/manager/configure/remote_machine/tunnel/request' => sub($c) {
	my $signatorial = $c->param('signatorial');
	my $status = $c->param('status');
	my $ports = eval { return decode_json $c->param('ports') } || {};
	my $batch_uuid = $c->param('batch_uuid');
	my $returner = { status => $status, batch_uuid => $batch_uuid, signatorial => $signatorial };
	my @netstats = split /\n/, `netstat -avnpt 2>/dev/null`;
	&subs::db_query('delete from tunnels where signatorial = ? and batch_uuid != ?', $signatorial, $batch_uuid);
	&subs::db_query('delete from tunnels where status=? and server_time < ?', 'reserved', &subs::rightNow() - 60000);
	foreach my $p ( @gb::ports ) {
		my $reservation_uuid = &subs::random_string_creator(29);
		my $new_port = &port_scan();
		$returner->{$p} = { dest => $ports->{$p}, source => $new_port, reservation_uuid => $reservation_uuid };
		&subs::db_insert('tunnels', { in_port => $new_port, uuid => $reservation_uuid, status => 'reserved' });

	}
	sub port_scan() {
		my $port;
		my @random_numbers = map { 50000 + int(rand(65000 - 50000 + 1)) } 1 .. 300;
		foreach my $n ( @random_numbers ) {
			$port = $n;
			my $next = 0;
			foreach my $p ( @gb::ports ) {
				$next = 1 if $ENV{$p} == $n;
			}
			if ($next == 0) {
				my $full_address = '127.0.0.1:' . $n;
				my $ss = `ss -t | grep $port`;
				if ($ss =~ /\Q$port/gi) {
					$next = 1;
					next;
				}
			}


			next if $next == 1;
			my $tun = &subs::db_query('select * from tunnels where in_port = ? and (status = ? or status = ?) order by in_port desc limit 1', $port, 'reserved', 'active')->hashes->[0];
			next if $tun->{'uuid'};
			last;
		}
		return $port;
	}


	$c->render(json => $returner);
};


post '/manager/configure/remote_machine/tunnel/confirm' => sub($c) {
	my $remote_address = $c->tx->remote_address;
	my $tunnel = eval { return decode_json $c->param('tunnel') } || {};
	my $signatorial = $c->param('signatorial');
	my $uuid = $c->param('uuid');
	my $returner = { tunnel => $tunnel };
	my $tun = &subs::db_select('tunnels', undef, { uuid => $uuid })->hashes->[0];
	my $tunnel_duties = eval { return decode_json &subs::setting_grabber({ app => '__president', setting => 'tunnel_duties' }) } || [];
	my $tunnel_duty_count = scalar @{$tunnel_duties};
	if ($tun->{'uuid'}) {
		$tunnel->{'status'} = 'active';
		$tunnel->{'signatorial'} = $signatorial;
		$tunnel->{'direction'} = 'out';
		$tunnel->{'ip'} = $remote_address;
		&subs::db_update('tunnels', $tunnel, { uuid => $uuid, status => 'reserved' });
		push @{$tunnel_duties}, $tunnel unless grep { $_->{'batch_uuid'} eq $tunnel->{'batch_uuid'} } @{$tunnel_duties};
	}
	if (scalar @{$tunnel_duties} != $tunnel_duty_count) {
		my $jtd = encode_json $tunnel_duties;

		&subs::setting_setter({ app => '__president', setting => 'tunnel_duties', value => $jtd });
	}
	&Websocket::send('server', { console => 'tunnelLister()' });
	# and the Dev panel: a tunnel coming up adds the peer to this hub's addresses,
	# so refresh it live rather than wait for a manual Scan
	&Websocket::send('server', { console => 'deviceLister()' });
	$c->render(json => $returner);
};

post '/manager/configure/remote_machine/tunnel/close' => sub($c) {
	my $tunnel = eval { return decode_json $c->param('tunnel') } || {};
	my $signatorial = $c->param('signatorial');
	my $status = $c->param('status');
	&subs::db_update('tunnels', { server_time => &subs::rightNow(), status => 'closed' }, { uuid => $tunnel->{'uuid'}, signatorial => $tunnel->{'signatorial'} });
	&Websocket::send('server', { console => 'tunnelLister()' });
	&Websocket::send('server', { console => 'deviceLister()' });

	$c->render(json => { tunnel => $tunnel, signatorial => $signatorial, status => $status });

};

websocket '/manager/tunnel/ws' => sub ($c) {
	# A peer behind NAT dials out here and names itself with the same
	# signatorial the sibling tunnel routes (request/confirm/close) use. The
	# hub only serves a signatorial it already knows as a remote machine.
	my $signatorial = $c->param('signatorial');
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	unless ($rm) {
		$c->rendered(403);
		return;
	}
	# A signatorial is a name, not a secret - it rides in query strings and in the
	# mirror lists peers share - so a rostered name alone is not enough: the peer
	# must also sign the handshake, exactly like every request on the HTTP peer
	# rail. peer_verify pins the key on first contact and refuses a changed key.
	unless (&subs::peer_verify($c, $rm)) {
		$c->rendered(403);
		return;
	}
	$c->rendered(101);
	# The peer's reserved ports live in its tunnels rows: in_port is the port
	# reserved on this hub, out_port the service on the peer. The hub listens on
	# in_port and forwards to the peer's out_port (tunnel.pl hub_session).
	my $tuns = &subs::db_select('tunnels', undef, { signatorial => $signatorial, status => 'active' })->hashes || [];
	my %listen;
	foreach my $t ( @{$tuns} ) {
		next unless $t->{'name'} && $t->{'in_port'};
		$listen{$t->{'name'}} = { source => $t->{'in_port'}, dest => $t->{'out_port'} };
	}
	&Tunnel::hub_session($c->tx, { signatorial => $signatorial, listen => \%listen });
	# The tunnel data plane is up now: enrol (or refresh) the peer immediately
	# rather than waiting for the 5-minute tunnel_checker loop, so a headless hub
	# can remote_upgrade / remote_relay_request it the moment it dials in. Forked
	# so the blocking sesh_check never stalls the websocket loop.
	&subs::subprocessor(sub {
		sleep 1;  # let the peer's peer_session settle before we dial it
		&subs::tunnel_peer_enrol($signatorial);
	}, { name => 'tunnel peer enrol ' . substr($signatorial, 0, 8) });
};

post '/manager/tunnel/alive' => sub($c) {
	my $chip_chyea = $c->param('chip_chyea');
	my $signatorial = $c->param('signatorial');
	# This route sits on the gate-exempt peer rail (hooks.pl) so a tunnelled peer
	# whose session has lapsed can still prove its data plane. Exempt is not open:
	# the caller signs the request like every other peer-rail call (the checker
	# posts it on remote_useragent_maker's UA), so authenticate it against the
	# roster row it names - without this, anyone quoting a signatorial could make
	# this hub dial every peer it knows with an attacker's chip_chyea.
	my $self_row = &subs::db_query('select * from remote_machines where signatorial = ?', $signatorial)->hashes->[-1];
	unless ($self_row && &subs::peer_verify($c, $self_row)) {
		$c->rendered(403);
		return;
	}
	my $network = $c->param('network');
	my $interval = $c->param('interval');
	my $remote_address = $c->tx->remote_address;
	my $remote_machines = &subs::remote_machine_lister();
	foreach my $rm ( @{$remote_machines} ) {
		my $data = { signatorial => $rm->{'signatorial'}, rm => $rm };
		if ($signatorial eq $rm->{'signatorial'}) {
			$data->{'chip_chyea'} = $chip_chyea;
			if ($network) {

				my $net = eval { return decode_json $network } || {};
				$net->{'public_address'} = $remote_address;

				$network = encode_json $net;
				$rm->{'network'} = $network;
				$data->{'rm'}->{'network'} = $network;
				&subs::db_update('remote_machines', { server_time => &subs::rightNow(), network => $network }, { signatorial => $rm->{'signatorial'} });
			}
		}
		$rm = &remote_useragent_maker($data);
	}

	$c->render(json => { chip_chyea => $chip_chyea, signatorial => $signatorial, mirrors => $remote_machines });
};

post '/manager/configure/remote_device_locker' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my $uuid = $c->param('uuid');
	my $ip = $c->param('ip');
	my $status = $c->param('status');
	my $nic = $c->param('nic');
	my $device = &subs::db_select('devices', undef, { uuid => $uuid })->hashes->[0];
	my $address = eval { return decode_json $device->{'address'} };

	my @remote_device = grep { $_->{'ip'} eq $ip } @{$address->{$nic}->{'neigh'}};

	my $rd = $remote_device[0];
	if ($status eq 'yes') {
		$rd->{'locked'} = 'no';
	}
	else {
		$rd->{'locked'} = 'yes';
	}
	@{$address->{$nic}->{'neigh'}} = grep { $_->{'ip'} ne $ip } @{$address->{$nic}->{'neigh'}};
	push @{$address->{$nic}->{'neigh'}}, $rd;
	@{$address->{$nic}->{'neigh'}} = sort { $a->{'ip'} cmp $b->{'ip'} } @{$address->{$nic}->{'neigh'}};
	my $jaddress = encode_json $address;
	&subs::db_update('devices', { address => $jaddress }, { uuid => $uuid });

	$c->render(json => $rd);
};

sub remote_useragent_maker($data) {
	my $ip = $data->{'ip'};
	my $signatorial = $data->{'signatorial'};
	my $rm = $data->{'rm'};
	my $uuid = $data->{'uuid'};
	my $auth_test = $data->{'auth_test'};
	my $ua = Mojo::UserAgent->new();
	$ua = $ua->max_response_size(0);
	# every request on the peer rail names this machine and carries a signature
	$ua->on(start => sub { my ($ua, $tx) = @_; &subs::peer_sign_request($tx->req); });
	unless ($rm) {
		if ($uuid) {
			$rm = &subs::remote_machine_lister({ uuid => $uuid, limit => 1 });
		} elsif ( $ip && $signatorial ) {
			$rm = &subs::remote_machine_lister({ signatorial => $signatorial, limit => 1 });
		} else {
			$rm = &subs::remote_machine_lister({ signatorial => $signatorial, limit => 1 });
		}
	}
	else {
		$rm = &subs::remote_machine_tunnel_processor($rm);
	}
	my $remote_address = $rm->{'ip'};
	my $port_dock = $rm->{'port_dock'} || 3000;
	my $port = $rm->{'port'};

	my $manager = $rm->{'manager'};
	if ($rm->{'cookie'}) {
		my $cookie_jar = decode_json $rm->{'cookie'};
		# The cookie was stored with the address the peer was reached on (often a
		# LAN ip), but the manager url is usually its fqdn: a cookie scoped to the
		# ip is never sent to the fqdn host. Scope it to whatever host we are about
		# to call, so the stored session actually rides along.
		my $host = eval { Mojo::URL->new($manager)->host };
		foreach my $cookie ( @{$cookie_jar} ) {
			$ua->cookie_jar->add(
				Mojo::Cookie::Response->new(
					name => $cookie->{'name'},
					value => $cookie->{'value'},
					domain => ($host || $cookie->{'domain'}),
					path => $cookie->{'path'}
				)
			);
		}
		$rm->{'ua'} = $ua;
		$rm->{'ua'}->inactivity_timeout(3000);
		$rm->{'ua'}->insecure(1);
		my $domain = $config->{'domain'} || $ip;
		if ($auth_test eq 'yes' || $data->{'chip_chyea'}) {
			my $url = $rm->{'manager'} . '/manager/remote_auth_test?signatorial=' . &subs::signatorial_designer() . '&auth_test=' . $auth_test;
			if ($data->{'chip_chyea'}) {
				$rm->{'ua'}->inactivity_timeout(2);
				$url .= '&chip_chyea=' . $data->{'chip_chyea'};
			}
			$url .= '&domain=' . $config->{'domain'};
			if ($auth_test eq 'yes' && defined $data->{'since'}) {
				$url .= '&since=' . int($data->{'since'});
			}
			if ($auth_test eq 'yes' && ref $data->{'digest'} eq 'HASH') {
				my %cuts = map { $_ => ($data->{'digest'}->{$_}->{'max'} || 0) } keys %{$data->{'digest'}};
				$url .= '&cuts=' . Mojo::Util::url_escape(&subs::sync_map_encode(\%cuts));
			}
			$url .= '&tombstone_cursor=' . int($data->{'tombstone_cursor'} || 0) if $auth_test eq 'yes';
			# The handshake is a cheap route that must answer quickly. The UA's other
			# timeout (3000s) exists so a snapshot pull can wait on a peer building a
			# large export; inheriting it here meant one stuck peer froze the whole
			# reconnector for fifty minutes, and every later peer in the roster waited
			# behind it. Bound this one request and put the long timeout back for the
			# requests that need it.
			my $long_timeout = $rm->{'ua'}->inactivity_timeout;
			$rm->{'ua'}->inactivity_timeout(15);
			my $res = eval { return $rm->{'ua'}->insecure(1)->get($url => {Accept => '*/*'} => 'Content!')->result };
			$rm->{'ua'}->inactivity_timeout($long_timeout);
			if (eval { $res->is_success }) {
				$rm->{'res'} = $res;
			} else {
				$rm->{'ua'} = undef;
			}
		}
	}
	else {
	}
	$rm->{'data'} = eval { return decode_json $rm->{'data'} };

	return $rm;
}

post '/manager/neighbour_status' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my $ip = $c->param('ip');
	my $status = $c->param('status');
	my ($db,$database,$sql) = &subs::database_grabber();
	my $remote_machines = &subs::db_query('select * from remote_machines where ip=?', $ip);
	my $re_ma = $remote_machines->hashes;
	my $rm = $re_ma->[-1];

	if ($rm->{'status'} eq 'mirror') {
		$rm->{'status'} = 'off';
	}
	else {
		$rm->{'status'} = 'mirror';
	}
	&subs::db_update('remote_machines', { status => $rm->{'status'} }, { ip => $ip });
	$c->render(json => $rm);
	my $remote_address = $c->tx->remote_address;
	`timeout .5 ping -c 1 $remote_address`;
};

