# A press in the app menu says what it opened, and the recent list - the app
# menu's front page - is written from it, so the next open leads with it.
post '/manager/start_menu/used' => sub($c) {
	my $recent = &start_menu_used($c->param('used'));
	$c->render(json => { recent => $recent });
};

# The X on a recent item takes the app back off the list, which is only ever
# the cache rewritten without it.
post '/manager/start_menu/forget' => sub($c) {
	my $recent = &start_menu_forget($c->param('forget'));
	$c->render(json => { recent => $recent });
};

# The apps the start menu was last used to open, freshest first. The app menu
# is a recent list and the shelf rail is how everything else is reached, so
# it lives in the president's cache like the System view's snapshot; cache entries are
# per device, so each screen keeps its own list. The warranty is asked for
# outright: __president has no warranty setting, and the fallback resolves to
# "now", which the alarm's cache purge then deletes a minute later.
sub start_menu_recent() {
	my $recent = &subs::cache_get({ app => '__president', context => 'start_menu', subcontext => 'recent' });
	return [ ref $recent eq 'ARRAY' ? @{$recent} : () ];
}

# A press's key is the button's id, or its hint when it has none. It is a
# cache value that the list renders back into the page, so the press and the
# forget both cut it down to plain words first.
sub start_menu_key_clean($key) {
	$key =~ s/[^A-Za-z0-9 _\-]//g;
	$key =~ s/^\s+//; $key =~ s/\s+$//;
	return substr($key, 0, 60);
}

# The freshest ten are kept.
sub start_menu_used($key) {
	$key = &start_menu_key_clean($key);
	return &start_menu_recent() unless length $key;
	my $recent = &start_menu_recent();
	@{$recent} = grep { $_ ne $key } @{$recent};
	unshift @{$recent}, $key;
	pop @{$recent} while scalar @{$recent} > 10;
	&subs::cache_set({ app => '__president', context => 'start_menu', subcontext => 'recent', warranty => '-1y' }, $recent);
	return $recent;
}

# What the X on an item asks for: the app leaves the list, whatever its place.
sub start_menu_forget($key) {
	$key = &start_menu_key_clean($key);
	return &start_menu_recent() unless length $key;
	my $recent = [ grep { $_ ne $key } @{ &start_menu_recent() } ];
	&subs::cache_set({ app => '__president', context => 'start_menu', subcontext => 'recent', warranty => '-1y' }, $recent);
	return $recent;
}

sub start_menu_maker($c) {
	my $fingerprint = 0;
	my $returner = {};
	my $menu = $c->param('menu');

	if (1 == 0) {
		&Websocket::send('server', { console => '$(\'#alert\').html(\'<h1>Fingerprint NOW!</h1><img src="/images/jbuttons/ne pas.png"><button id="alert_cancel">Hide</button>\').show()' });
		if ($device eq 'mobile') {
			my $tf = `termux-fingerprint`;
			my $f = eval { return decode_json $tf } || {};
			if ($f->{'auth_result'} eq 'AUTH_RESULT_SUCCESS') {
				$fingerprint = 1;
			}
		}
		elsif ($device eq 'computer' ) {
			my $f = `fprintd-verify`;
			my @f = split /\n/, $f;
			if ($f[-1] eq 'Verify result: verify-match (done)') {
				$fingerprint = 1;
			}
		}
		else {
			$fingerprint = 1;
		}
		&Websocket::send('server', { console => '$(\'#alert\').hide()' });
	}
	$fingerprint = 1;
	if ($fingerprint == 1) {
		my $html = $c->render_to_string(
			template => 'start_menu/start_menu',
			parking_lot => &parking_lot_grabber($c),
			config => &subs::config_reader(),
			padlock => &subs::db_select('security', ['level'], { level => 'padlock' })->hashes,
			menu => $menu,
			recent => &start_menu_recent()
		);
		# Static files carry no Cache-Control, so browsers cached the icons
		# heuristically and kept showing stale ones. Version the local images
		# so the start menu always pulls the current set.
		my $v = &subs::rightNow();
		my $set = &subs::icon_set();
		if ($set) {
			$html =~ s{src="(/[^"]*\.(?:png|jpe?g|gif))"}{'src="' . &subs::icon_for($1, $set) . '"'}ge;
		}
		$html =~ s/"([^"]*\.(?:png|jpe?g|gif|svg))"/"$1?v=$v"/g;
		$returner = { html => $html };

	}
	else {
		&lock_session($c);
	}

	return $returner;
}

sub parking_lot_grabber($c) {
	my $parking_lot = {};
	my $spaces = &subs::db_query('select * from websockets where room is not null')->hashes;

	foreach my $pl ( @{$spaces} ) {
		my $others = &subs::db_select('websockets', undef, { browser_tab_id => $pl->{'browser_tab_id'} })->hashes;
		foreach my $ot ( @{$others} ) {
			if ($ot->{'music_data'}) {
				$pl->{'music_data'} = $ot->{'music_data'};
			}
			elsif ($ot->{'jp_data'}) {
				$pl->{'jp_data'} = $ot->{'jp_data'};
			}
		}
		$parking_lot->{$pl->{'room'}} = $pl;
	}
	return $parking_lot;
}

