# Ticket management is the citizen's desk: minting, deleting, suspending,
# renewing and reinstating are the owner's acts, and the hooks' path
# allowances do not enforce that on their own. A neighbouring machine on the
# mesh is admitted too, over the same signed rail the other peer routes use: it
# names itself in `signatorial` and peer_verify checks its signature. The desk
# is exactly the thing a device without a ticket of its own needs, and the
# request it holds may live on a neighbour's database, so the owner must be
# able to answer it from a machine that is not the citizen session itself.
#
# A pinned pubkey is required, unlike the trust-on-first-contact peer routes:
# this desk hands out citizenship, so a machine that has merely linked and not
# yet completed a signed exchange must not reach it before its key is on file.
sub ticket_desk_allowed($c) {
	return 1 if $c->session('authentication') eq 'approved' && $c->session('privilege') eq 'citizen';
	my $signatorial = $c->param('signatorial');
	my $rm = ($signatorial && &subs::db_select('remote_machines', undef, { signatorial => $signatorial })->hashes->[0]);
	return 1 if $rm && $rm->{'pubkey'} && &subs::peer_verify($c, $rm);
	return 0;
}

# The request desk's policy and its blacklist are rows read by the newest
# write, not device-scoped settings: the public page is served by the server
# while the owner may sit at a phone, so a choice made anywhere has to be seen
# everywhere the mesh carries the settings table.
sub ticket_policy() {
	my $row = &subs::db_query('select value from settings where app=? and setting=? order by server_time desc limit 1', 'box_office', 'request_policy')->hashes->[0];
	my $policy = eval { return decode_json $row->{'value'} } || {};
	$policy->{'guest_warranty'} = '-1d' unless defined $policy->{'guest_warranty'} && length $policy->{'guest_warranty'};
	$policy->{'issue_guest_on_request'} = 0 unless defined $policy->{'issue_guest_on_request'};
	return $policy;
}

sub ticket_policy_set($policy) {
	&subs::setting_setter({ app => 'box_office', setting => 'request_policy', value => encode_json $policy });
}

sub ticket_blacklist() {
	my $row = &subs::db_query('select value from settings where app=? and setting=? order by server_time desc limit 1', 'box_office', 'blacklist')->hashes->[0];
	return eval { return decode_json $row->{'value'} } || [];
}

sub ticket_blacklist_save($list) {
	&subs::setting_setter({ app => 'box_office', setting => 'blacklist', value => encode_json $list });
}

# The call blacklist is that same desk list seen from the phone: every entry
# that carries a phone, as the bare digits the app compares. A listed number is
# turned away before it can ring (the app's CallScreeningService reads this), so
# the numbers are handed to the phone on its own route.
sub ticket_blacklist_numbers() {
	my @numbers;
	foreach my $b ( @{&ticket_blacklist()} ) {
		next unless ref $b eq 'HASH';
		my $number = &ticket_contact_clean('phone', $b->{'phone'});
		push @numbers, $number if $number;
	}
	my %seen;
	return [ grep { !$seen{$_}++ } @numbers ];
}

# Block a number straight from the desk or from the phone's recents: one entry,
# keyed by the number so a second press never doubles it. The label is the app
# that owns the number when the house knows it, blank otherwise.
sub ticket_blacklist_block($number,$label,$note) {
	my $clean = &ticket_contact_clean('phone', $number);
	return '' unless $clean;
	my $list = &ticket_blacklist();
	foreach my $b ( @{$list} ) {
		next unless ref $b eq 'HASH';
		return $clean if &ticket_contact_clean('phone', $b->{'phone'}) eq $clean;
	}
	push @{$list}, {
		name => defined $label && length $label ? &subs::format_name($label) : '',
		email => '',
		phone => $clean,
		note => defined $note && length $note ? $note : 'blocked call',
		timestamp => &subs::rightNow()
	};
	&ticket_blacklist_save($list);
	return $clean;
}

# The house's numbers by name, for the app's in-call screen and its contact
# list: the same settings 'phone' rows the Phone app shows, keyed by the bare
# digits so the native side compares them the way it compares the blacklist.
sub phone_names() {
	my $rows = &subs::db_query('select app, value from settings where setting=? and value != ?', 'phone', '')->hashes;
	my %names;
	foreach my $r ( @{$rows} ) {
		my $number = &ticket_contact_clean('phone', $r->{'value'});
		next unless $number;
		$names{$number} = $r->{'app'};
	}
	# every extra line a person keeps - their home, their work - names a call too,
	# so the in-call screen shows the person rather than a bare number
	my $lists = &subs::db_query('select app, value from settings where setting=? and value != ?', 'phones', '')->hashes;
	foreach my $r ( @{$lists} ) {
		my $list = eval { return decode_json $r->{'value'} } || [];
		$list = [ $list ] if ref $list eq 'HASH';
		next unless ref $list eq 'ARRAY';
		foreach my $c ( @{$list} ) {
			next unless ref $c eq 'HASH';
			my $number = &ticket_contact_clean('phone', $c->{'value'});
			next unless $number;
			$names{$number} ||= $r->{'app'};
		}
	}
	return \%names;
}

# Every number the house holds, split the way the Phone app's panes want it: the
# people it knows, and the numbers that are only numbers (a stranger's call makes
# its number an app of its own, so those rows are the ones still to be named).
# One row per app, carrying every line the person keeps - the plain phone row
# first, then the typed list - so a person with a home and a work number is listed
# once, not once per number.
sub phone_directory() {
	my $lines = &subs::contact_lines('phone');
	my (@known, @numbers);
	foreach my $app ( keys %{$lines} ) {
		my @l = @{ $lines->{$app} };
		next unless scalar @l;
		my $row = { app => $app, value => $l[0]->{'value'}, numbers => \@l };
		if ( $app =~ /^\d+$/ ) { push @numbers, $row; }
		else { push @known, $row; }
	}
	@known = sort { lc $a->{'app'} cmp lc $b->{'app'} } @known;
	@numbers = sort { $a->{'app'} cmp $b->{'app'} } @numbers;
	return { known => \@known, numbers => \@numbers };
}

# The desk's blacklist seen as calls: the numbers to refuse, each with whatever
# the desk knew about it (a name when the request carried one, the note).
sub phone_blocked() {
	my @blocked;
	foreach my $b ( @{&ticket_blacklist()} ) {
		next unless ref $b eq 'HASH';
		my $number = &ticket_contact_clean('phone', $b->{'phone'});
		next unless $number;
		push @blocked, {
			number => $number,
			name => $b->{'name'} || '',
			note => $b->{'note'} || '',
			stamp => $b->{'timestamp'} || '',
		};
	}
	return \@blocked;
}

# A small square picture of a person for the app's call screen: the house's own
# image when there is one, downscaled once and kept beside the database, keyed by
# the source's name, size and mtime so a new picture makes a new thumbnail. The
# app shows its own logo when there is none, so nothing is drawn here for that.
sub phone_avatar_thumb($file) {
	return '' unless $file && -e $file;
	my $dir = &subs::database_dir() . '/thumbs';
	mkdir $dir unless -d $dir;
	my @stat = stat($file);
	my $base = $file;
	$base =~ s{.*/}{};
	$base =~ s/[^A-Za-z0-9._-]+/-/g;
	my $thumb = $dir . '/' . $base . '-' . ($stat[7] || 0) . '-' . ($stat[9] || 0) . '.jpg';
	return $thumb if -e $thumb && -s $thumb > 0;
	`magick "$file" -resize 160x160^ -gravity center -extent 160x160 -quality 82 "$thumb" 2>/dev/null`;
	return (-e $thumb && -s $thumb > 0) ? $thumb : '';
}

# The person's picture as a data URI, for the one fetch the app makes: it hands
# the whole directory over at once, so an image per call would be a fetch the app
# (which may be ringing with no page up) cannot wait for.
sub phone_avatar_data($app) {
	my $settings = &subs::settings_grabber({ app => $app }) || {};
	return '' unless $settings->{'main_image'};
	my ($destination,$asset) = &subs::file_device_renamer({ file => $settings->{'main_image'}, app => $app, type => 'image' });
	my $thumb = &phone_avatar_thumb($destination . $asset);
	return '' unless $thumb;
	open(my $fh, '<', $thumb) or return '';
	binmode $fh;
	local $/;
	my $bytes = <$fh>;
	close $fh;
	return '' unless defined $bytes && length $bytes;
	return 'data:image/jpeg;base64,' . encode_base64($bytes, '');
}

sub ticket_contact_clean($kind,$value) {
	return '' unless defined $value && length $value;
	if ($kind eq 'email') {
		$value = lc $value;
	}
	elsif ($kind eq 'phone') {
		$value =~ s/\D+//g;
		$value =~ s/^1//;
	}
	else {
		$value = &subs::unformat_name($value);
	}
	return $value;
}

# A request matches the blacklist when any one of its identifiers does.
sub ticket_blacklist_match($info) {
	my $name = &ticket_contact_clean('name', $info->{'name'});
	my $email = &ticket_contact_clean('email', $info->{'email'});
	my $phone = &ticket_contact_clean('phone', $info->{'phone'});
	foreach my $b ( @{&ticket_blacklist()} ) {
		next unless ref $b eq 'HASH';
		return 1 if $name && $name eq &ticket_contact_clean('name', $b->{'name'});
		return 1 if $email && $email eq &ticket_contact_clean('email', $b->{'email'});
		return 1 if $phone && $phone eq &ticket_contact_clean('phone', $b->{'phone'});
	}
	return 0;
}

# Is this requester already known to the house? The same rows the mailbox uses
# to name a thread: an email or a phone number kept on an app - the plain setting
# or a typed entry beside it (their work line, a second mailbox).
sub ticket_request_known($info) {
	my @known;
	my $email = &ticket_contact_clean('email', $info->{'email'});
	push @known, &subs::contact_apps('email', $email) if $email;
	my $phone = &ticket_contact_clean('phone', $info->{'phone'});
	push @known, &subs::contact_apps('phone', $phone) if $phone;
	@known = grep { defined $_ && length $_ } @known;
	my %seen;
	@known = grep { !$seen{$_}++ } @known;
	return \@known;
}

# The door's throttle: one request per browser tab at a time, and one per
# address per ten minutes. Over the line the form answers exactly as it does
# to a queued request, so the door never says who is on the list.
sub ticket_request_allowed($c) {
	my $browser_tab_id = $c->param('browser_tab_id') || '';
	if ($browser_tab_id) {
		my $open = &subs::db_query('select uuid from tickets where browser_tab_id=? and status=? and server_time > ? order by server_time desc limit 1', $browser_tab_id, 'request', &subs::rightNow() - 3600000)->hashes->[0];
		return 0 if $open && $open->{'uuid'};
	}
	my ($db) = &subs::database_grabber();
	return 1 unless $db;
	my $ip = $c->tx->remote_address;
	my $now = &subs::rightNow();
	my $seen = &subs::db_query('select server_time from cache where context=? and uuid=? order by server_time desc limit 1', 'ticket_request', $ip)->hashes->[0];
	return 0 if $seen->{'server_time'} && $seen->{'server_time'} > $now - 600000;
	&subs::db_query('delete from cache where context=? and uuid=?', 'ticket_request', $ip);
	&subs::db_query('insert into cache (uuid, context, app, server_time, timestamp) values (?,?,?,?,?)', $ip, 'ticket_request', 'box_office', $now, $now);
	return 1;
}

sub ticket_request_pending_html() {
	return '<h3>Request received</h3><p>Your request is with the house. If it is approved, this page will let itself in.</p>';
}

# What an approval mints: the box office's own mint, with the house's suds
# when a citizen is not the one pressing the button, and the requesting tab
# carried over so the waiting page can be let in.
sub ticket_request_mint($c, $request, $privilege, $warranty) {
	my $info = eval { return decode_json $request->{'information'} } || {};
	my $host = $c->req->url->base->host;
	my $addresses = eval { &subs::device_lister(&subs::rightNow(), '')->[0]->{'address'} } || {};
	my $nic;
	foreach my $key ( sort keys %{$addresses} ) {
		next unless $addresses->{$key}->{'ip'};
		if ($addresses->{$key}->{'ip'} eq $host || $key eq $host) { $nic = $key; last; }
	}
	my $domain = &subs::config_reader()->{'domain'};
	$nic = $domain if !$nic && $domain && $addresses->{$domain};
	$nic = ( grep { $addresses->{$_}->{'ip'} } sort keys %{$addresses} )[0] unless $nic;
	my $suds = &subs::session_suds($c) || &subs::suds_grabber();
	return undef unless $nic && $suds;
	my $data = &qrcode_generator({
		timestamp => &subs::rightNow(),
		app => 'box_office',
		name => $request->{'name'},
		privilege => $privilege,
		project => $info->{'project'},
		nic => $nic,
		warranty => $warranty,
		keep_warranty => 1
	});
	$data->{'browser_tab_id'} = $request->{'browser_tab_id'};
	$data->{'information'} = $request->{'information'};
	return $data;
}

sub ticket_request_notify($c, $request, $info) {
	my $who = $info->{'name'} || $info->{'email'} || 'Someone';
	my $awaiting = scalar @{ &subs::db_query('select uuid from tickets where status=?', 'request')->hashes };
	my (undef,$database) = &subs::database_grabber();
	&Websocket::send('tab', { type => 'ticket_request_arrival', count => $awaiting, message => $who . ' asks for a ticket' });
	# an open box office refreshes itself; the visible test keeps a hidden window
	# from rebuilding under the user
	&Websocket::send('server', { console => '$("#box_office").is(":visible") && typeof boxOffice == "function" ? boxOffice() : 0;' });
	&notification_sender({ app => 'box_office', role => 'citizen', title => 'Ticket Request', message => $who . ' asks for a ticket', image => $gb::known_appts->{'box_office'}->{'icon'} }, $database);
}

get '/manager/qrcode_generator' => sub($c) {
	unless (&ticket_desk_allowed($c)) {
		$c->render(json => { error => 'denied' });
		return;
	}
	my $timestamp = $c->param('timestamp');
	my $app = &subs::unformat_name($c->param('app'));
	my $name = &subs::unformat_name($c->param('name') || 'visitor');
	my $privilege = $c->param('privilege') || 'visitor';
	my $project = $c->param('project');
	my $debriefer = $c->param('debriefer');
	my $nic = $c->param('nic');
	my $warranty = $c->param('warranty');

	my $data = &qrcode_generator({
		timestamp => $timestamp,
		app => $app,
		name => $name,
		privilege => $privilege,
		project => $project,
		debriefer => $debriefer,
		nic => $nic,
		warranty => $warranty
	});
	&subs::db_insert('tickets', $data);
	&subs::setting_setter({ app => 'box_office', setting => 'last_privilege', value => $privilege });
	&subs::setting_setter({ app => 'box_office', setting => 'last_nic', value => $nic });
	&subs::setting_setter({ app => 'box_office', setting => 'last_name', value => $name });
	$c->render(json => $data);
};

sub qrcode_generator($params) {
	my $timestamp = $params->{'timestamp'} || &subs::rightNow();
	my $app = $params->{'app'};
	my $name = $params->{'name'};
	my $project = $params->{'project'};
	my $debriefer = $params->{'debriefer'};
	my $nic = $params->{'nic'};
	my $suds = $params->{'suds'};
	my $warranty = $params->{'warranty'};
	my $privilege = $params->{'privilege'};
	my $db = $params->{'db'};
	my $database = $params->{'database'};
	my $sql = $params->{'sql'};


	my $server_time = &subs::rightNow();
	unless ($db) {
		($db,$database,$sql) = &subs::database_grabber('new');
	}
	my $random_password = &subs::random_string_creator(40);
	my $sj = { ts => $timestamp, p => &subs::random_string_creator(25), uuid => &subs::random_string_creator(10) };

	my $secret_json = encode_json $sj;
	$suds = &subs::note_encrypter($sj->{'p'}, $suds);
	my $secret = &subs::note_encrypter($random_password, $secret_json);
	$secret = url_escape `echo "$secret" | base64 -w 0`;

	my $uuid = $sj->{'uuid'};

	my $domain;
	unless ($params->{'db'}) {
		if ($nic eq &subs::config_reader()->{'domain'}) {
			$domain = $nic;
		}
		else {
			my $x = &subs::device_lister($timestamp, '')->[0]->{'address'};
			$domain = $x->{$nic}->{'ip'};
		}
	}
	else {
		$domain = '127.0.0.1';
	}
	my $port = $ENV{PORT_AHOY};
	if ($device eq 'server') {
		$port = 443;
	}
	my $url = 'https://' . $domain . ':' . $ENV{'PORT_DOCK'} . '/box_office/' . $sj->{'uuid'} . '?s=' . $secret;
	$warranty = $warranty || &subs::setting_grabber({ app => 'box_office', setting => 'warranty' });
	# the issue form's warranty box is a choice about this ticket, not a new
	# house default; a request minted in the background must not move it
	unless ($params->{'db'} || $params->{'keep_warranty'}) {
		&subs::setting_setter({ app => 'box_office', setting => 'warranty', value => $warranty });
	}
	# "forever" is the apps' warranty: a far-future epoch no expiry check or
	# sweep will ever pass, so a ticket baked into an app never expires
	$warranty = (($warranty || '') =~ /^\s*forever\s*$/i) ? &subs::forever_warranty() : &subs::ago_calc($warranty,$timestamp);
	my $duration = $warranty - $timestamp;

	my $qr = `qrencode -o - $url`;
	my $image = 'data:image/png;base64,' . encode_base64($qr);
	my $data = {
		timestamp => $timestamp,
		uuid => $sj->{'uuid'},
		warranty => $warranty,
		url => $url,
		server_time => $server_time,
		name => $name,
		image => $image,
		privilege => $privilege,
		verification => $secret,
		status => 'active',
		duration => $duration,
		app => $app,
		password => $random_password,
		port => $ENV{PORT_AHOY},
		ip => $domain,
		secret => $secret,
		nic => $nic,
		project => $project,
		suds => $suds,
		debriefer => $debriefer
	};
	return $data;
}

sub qrcode_updater($c) {
	my ($db,$database,$sql) = &subs::database_grabber();
	my $timestamp = $c->param('timestamp');
	my $q = &subs::db_query('select * from tickets');
	my $tickets = $q->hashes;
	my $level_one_q = &subs::db_query('select timestamp from security where level=1 order by timestamp DESC limit 1');
	my $level_one = $level_one_q->hashes;

	foreach my $t ( @{$tickets} ) {
		# a request (or anything else that was never minted) has no secret to
		# re-encrypt; decoding its empty one used to die and take the whole
		# box office down with it
		next unless $t->{'secret'} && $t->{'password'};
		my $secretive = $t->{'secret'};
		my $ver = url_unescape `echo "$secretive" | base64 --decode`;
		my $ts = &subs::note_decrypter($t->{'password'},$ver);

		my $sj = decode_json $ts;
		if ( $t->{'port'} ne $ENV{PORT_AHOY} || $level_one->[0]->{'timestamp'} >= $t->{'server_time'}) {
		#	$sj->{'ts'} = &subs::rightNow();
			my $secret_json = encode_json $sj;
			my $secret = &subs::note_encrypter($t->{'password'}, $secret_json);
			$secret = url_escape `echo "$secret" | base64 -w 0`;
			my $x = &subs::device_lister($timestamp, '')->[0]->{'address'};
			my $url = 'https://' . $x->{$t->{'nic'}}->{'ip'} . ':' . $ENV{'PORT_DOCK'} . '/box_office/' . $t->{'uuid'} . '?s=' . $secret;
			my $qr = `qrencode -o - $url`;
			my $image = 'data:image/png;base64,' . encode_base64($qr);
			&subs::db_update('tickets', {
				ip => $x->{$t->{'nic'}}->{'ip'},
			#	url => $url,
			#	image => $image,
				port => $ENV{PORT_AHOY},
				server_time => &subs::rightNow(),
			#	secret => $secret,
			},
			{ uuid => $t->{'uuid'} });
		}
	}
}

get '/manager/box_office' => sub($c) {
	# the desk lists every ticket's link and secret: only the citizen reads it
	unless (&ticket_desk_allowed($c)) {
		$c->render(text => '');
		return;
	}
	my $app = &subs::unformat_name('box_office');
	my $view = $c->param('view') || &subs::setting_grabber({ app => 'misc', setting => 'box_office_view' });
	my $timestamp = $c->param('timestamp');
	my ($db,$database,$sql) = &subs::database_grabber();
	&qrcode_updater($c);
	my $ticks = &subs::db_query('select * from tickets');
	my $tickets = $ticks->hashes;
	my $devices = &subs::device_lister($timestamp, '');
	my $addresses = $devices->[0]->{'address'};
	my $warranty = $c->param('warranty') || &subs::setting_grabber({ app => $app, setting => 'warranty' }) || &subs::setting_grabber({ app => 'me', setting => 'warranty' });
	my $projs = &subs::db_query('select * from settings where (setting=? or setting=?) and value=?', 'pos','mab', 'project');
	my $projects = $projs->hashes;
	my $persons = &subs::db_query('select * from settings where (setting=? or setting=?) and value=? or value = ?', 'pos','mab','person', 'customer');
	my $requests = [ grep { ($_->{'status'} || '') eq 'request' } @{$tickets} ];
	foreach my $r ( @{$requests} ) {
		$r->{'access_log'} = [];
		$r->{'info'} = eval { return decode_json $r->{'information'} } || {};
		$r->{'known'} = &ticket_request_known($r->{'info'});
	}
	foreach my $t ( @{$tickets} ) {
		my $al = eval { return decode_json $t->{'access_log'} } || [];
		$t->{'access_log'} = $al;
	}
	my $people = $persons->hashes;
	# this path rides the bare signed rail (see hooks.pl), so the device/string
	# stash the hook sets for a gated path is absent; the desk template and
	# window_maker both read them, so set them here for citizen and peer alike
	$Manager::random_caching_string = &subs::jawn_version();
	$c->stash('device' => &subs::device_setter(), 'string' => $Manager::random_caching_string);
	my $content = $c->render_to_string(
		template => 'box_office',
		timestamp => $timestamp,
		config => &subs::config_reader(),
		addresses => $addresses,
		tickets => $tickets,
		requests => $requests,
		blacklist => &ticket_blacklist(),
		policy => &ticket_policy(),
		nic => &subs::setting_grabber({ app => $app, setting => 'last_nic' }),
		name => &subs::setting_grabber({ app => $app, setting => 'last_name' }) || &subs::setting_grabber({ app => 'me', setting => 'my_name' }),
		privilege => &subs::setting_grabber({ app => $app, setting => 'last_privilege' }) || 'visitor',
		warranty => $warranty,
		projects => $projects,
		people => $people,
		config => &subs::config_reader(),
		view => $view
	);

	if ($c->param('source') ne 'list') {
		$content = &window_maker({ user_agent => $c->param('user_agent'), app => $app, contents => $content }, $timestamp);
	}
	$c->render('text' => $content);
};


any '/box_office/ticket_request' => sub($c) {
	my $call = $c->param('call');
	my $privilege = $c->param('privilege');
	my $team = $c->param('team');
	my $club = $c->param('club');
	my $community = $c->param('community');
	my $timestamp = $c->param('timestamp');
	if ($call eq 'form') {
		my $content = $c->render_to_string(
			template => 'store/ticket_request',
		);
		$c->render(json => { content => $content });
	}
	elsif ($call eq 'privilege') {
		my $content = $c->render_to_string(
			template => 'store/ticket_request_privilege',
			privilege => $privilege,
			team => $team,
			club => $club,
			community => $community
		);
		$c->render(json => { content => $content });
	}
	elsif ($call eq 'submit') {
		my $data = eval { return decode_json $c->param('data') } || {};
		my $info = {
			name => &subs::unformat_name($data->{'name'} || ''),
			email => &ticket_contact_clean('email', $data->{'email'}),
			phone => &ticket_contact_clean('phone', $data->{'phone'}),
			description => substr($data->{'description'} || '', 0, 1000),
			privilege => 'guest',
			team => $data->{'team'},
			club => $data->{'club'},
			community => $data->{'community'}
		};
		my $browser_tab_id = $c->param('browser_tab_id') || '';
		my $policy = &ticket_policy();
		# the door's rules: a blacklisted identifier and a flood both get the
		# queued answer, so the form never says who is on the list
		if (&ticket_blacklist_match($info) || !&ticket_request_allowed($c)) {
			$log->info('ticket request dropped: ' . $info->{'name'} . ' (' . $c->tx->remote_address . ')');
			$c->render(json => { status => 'pending', html => &ticket_request_pending_html() });
			return;
		}
		my $request = {
			uuid => &subs::random_string_creator(35),
			name => $info->{'name'},
			timestamp => $timestamp || &subs::rightNow(),
			server_time => &subs::rightNow(),
			status => 'request',
			privilege => 'guest',
			browser_tab_id => $browser_tab_id,
			ip => $c->tx->remote_address,
			information => encode_json $info
		};
		if ($policy->{'issue_guest_on_request'}) {
			# the house keeps the door open: a guest ticket is minted on the spot
			my $minted = &ticket_request_mint($c, $request, 'guest', $policy->{'guest_warranty'});
			if ($minted) {
				&subs::db_insert('tickets', $minted);
				$c->render(json => { status => 'approved', url => $minted->{'url'} });
				return;
			}
		}
		&subs::db_insert('tickets', $request);
		&ticket_request_notify($c, $request, $info);
		$c->render(json => { status => 'pending', html => &ticket_request_pending_html() });
	}
	elsif ($call eq 'check') {
		# the waiting page asks whether its ticket has been granted: the tab's
		# own id is the claim, and only a fresh ticket answers it
		my $browser_tab_id = $c->param('browser_tab_id') || '';
		my $ticket = $browser_tab_id ? &subs::db_query('select url from tickets where browser_tab_id=? and status=? and server_time > ? order by server_time desc limit 1', $browser_tab_id, 'active', &subs::rightNow() - 1800000)->hashes->[0] : undef;
		if ($ticket->{'url'}) {
			$c->render(json => { status => 'approved', url => $ticket->{'url'} });
		}
		else {
			$c->render(json => { status => 'pending' });
		}
	}
	else {
		$c->render(template => 'guest_layouts/denial');
	}
};

# The desk's decisions, all citizen acts: approve mints the ticket the request
# asked for (and keeps its information and requesting tab), decline forgets
# the request, blacklist remembers the identifiers so the door refuses them
# before a request is ever queued.
post '/manager/box_office/approve' => sub($c) {
	unless (&ticket_desk_allowed($c)) {
		$c->render(json => { error => 'denied' });
		return;
	}
	my $uuid = $c->param('ticket');
	my $privilege = $c->param('privilege') || 'guest';
	$privilege = 'guest' unless $gb::chairs->{$privilege};
	my $warranty = $c->param('warranty') || &ticket_policy()->{'guest_warranty'};
	my $request = &subs::db_query('select * from tickets where uuid=? and status=?', $uuid, 'request')->hashes->[0];
	unless ($request->{'uuid'}) {
		$c->render(json => { error => 'no request' });
		return;
	}
	my $minted = &ticket_request_mint($c, $request, $privilege, $warranty);
	unless ($minted) {
		$c->render(json => { error => 'no key' });
		return;
	}
	&subs::db_delete('tickets', { uuid => $uuid });
	&subs::db_insert('tickets', $minted);
	&Websocket::send('server', { console => 'typeof ticket_list == "function" && ticket_list();' });
	$c->render(json => { ticket => $minted->{'uuid'}, url => $minted->{'url'} });
};

post '/manager/box_office/decline' => sub($c) {
	unless (&ticket_desk_allowed($c)) {
		$c->render(json => { error => 'denied' });
		return;
	}
	my $uuid = $c->param('ticket');
	my $request = &subs::db_query('select * from tickets where uuid=? and status=?', $uuid, 'request')->hashes->[0];
	unless ($request->{'uuid'}) {
		$c->render(json => { error => 'no request' });
		return;
	}
	$log->info('ticket request declined: ' . $request->{'name'});
	&subs::db_delete('tickets', { uuid => $uuid });
	$c->render(json => { declined => $uuid });
};

post '/manager/box_office/blacklist' => sub($c) {
	unless (&ticket_desk_allowed($c)) {
		$c->render(json => { error => 'denied' });
		return;
	}
	my $uuid = $c->param('ticket');
	my $request = &subs::db_query('select * from tickets where uuid=? and status=?', $uuid, 'request')->hashes->[0];
	unless ($request->{'uuid'}) {
		$c->render(json => { error => 'no request' });
		return;
	}
	my $info = eval { return decode_json $request->{'information'} } || {};
	my $list = &ticket_blacklist();
	push @{$list}, {
		name => $info->{'name'},
		email => $info->{'email'},
		phone => $info->{'phone'},
		note => $info->{'description'},
		timestamp => &subs::rightNow()
	};
	&ticket_blacklist_save($list);
	&subs::db_delete('tickets', { uuid => $uuid });
	$c->render(json => { blacklisted => $info->{'name'} });
};

post '/manager/box_office/blacklist/remove' => sub($c) {
	unless (&ticket_desk_allowed($c)) {
		$c->render(json => { error => 'denied' });
		return;
	}
	my $stamp = $c->param('stamp');
	my $list = &ticket_blacklist();
	@{$list} = grep { ($_->{'timestamp'} || '') ne $stamp } @{$list};
	&ticket_blacklist_save($list);
	$c->render(json => { count => scalar @{$list} });
};

post '/manager/box_office/policy' => sub($c) {
	unless (&ticket_desk_allowed($c)) {
		$c->render(json => { error => 'denied' });
		return;
	}
	my $policy = &ticket_policy();
	$policy->{'issue_guest_on_request'} = $c->param('issue_guest_on_request') && $c->param('issue_guest_on_request') eq 'on' ? 1 : 0;
	$policy->{'guest_warranty'} = $c->param('guest_warranty') || '-1d';
	&ticket_policy_set($policy);
	$c->render(json => $policy);
};

# Upgrading a holder is the box office's act too: the chair is the ticket's,
# and the next time the link is opened the session wears the new privilege.
post '/manager/ticket_privilege' => sub($c) {
	unless (&ticket_desk_allowed($c)) {
		$c->render(json => { error => 'denied' });
		return;
	}
	my $uuid = $c->param('uuid');
	my $privilege = $c->param('privilege');
	unless ($uuid && $gb::chairs->{$privilege}) {
		$c->render(json => { error => 'bad request' });
		return;
	}
	&subs::db_update('tickets', { privilege => $privilege, server_time => &subs::rightNow() }, { uuid => $uuid });
	$c->render(json => { uuid => $uuid, privilege => $privilege });
};

get '/box_office/:uuid' => sub($c) {
	my $uuid = $c->stash('uuid');
	my $secret = $c->param('s');
	my $ip = $c->tx->remote_address;
	my $server_time = &subs::rightNow();
	my $timestamp = $c->param('timestamp') || $server_time;
	my ($db,$database) = &subs::database_grabber();

	my $base_host = $c->req->url->base->host;

	if ($base_host ne $config->{'domain'} && $ip ne $c->tx->local_address) {
		$c->render(template => 'guest_layouts/denial');
		return;
	}

	my $base_url = 'https://' . $base_host . ':' . $ENV{PORT_AHOY};
	unless ($db) {
		$c->redirect_to($base_url . '/manager');
		return;
	}
	my $tick = &subs::db_query('select * from tickets where uuid=?', $uuid);
	my $ticke = $tick->hashes;
	unless (scalar @{$ticke} > 0) {
		$c->redirect_to($base_url . '/manager');
		return;
	}

	my $ticket = $ticke->[0];
	my $access_log = eval { return decode_json $ticket->{'access_log'} } || [];
	my $access = { server_time => $server_time, status => 'denial', ip => $ip };

	my $v = $ticket->{'verification'};
	my $ver = url_unescape `echo "$secret" | base64 --decode`;
	my $verification = &subs::note_decrypter($ticket->{'password'}, $ver) ;
	my $vrai = eval { return decode_json $verification } || {};
	unless ($vrai->{'p'}) {
		$c->redirect_to($base_url . '/manager');
		return;
	}
	# the ticket's token is the credential; a legacy row may still carry a sealed
	# copy of the key, adopted only when this machine has none - otherwise the
	# machine's vault is the key and nothing here touches it
	my $genuine = (!$vrai->{'uuid'} || $vrai->{'uuid'} eq $ticket->{'uuid'}) ? 1 : 0;
	my $suds;
	if ($ticket->{'suds'}) {
		$suds = &subs::note_decrypter($vrai->{'p'}, $ticket->{'suds'});
		chomp $suds if $suds;
		$suds = undef unless $suds && &subs::suds_current($suds);
	}
	$suds ||= eval { &subs::suds_grabber() };

	if (($genuine && $suds) && $ticket->{'privilege'} && $ticket->{'status'} eq 'active') {
		&update_database($c);
		my $d = { app => 'customs', role => 'citizen', title => 'Your Majesty', message => &subs::format_name($ticket->{'privilege'}) . ': ' . &subs::format_name($ticket->{'name'}), image => "/images/make believe/crown.png" };
		unless ($c->req->url->base->port eq 3000) {
			&subs::say_it($ticket->{'name'});
			&notification_sender($d,$database);
		}
		if ($ticket->{'privilege'} eq 'blacklisted') {
			# blacklisted is the deny: the denial page is the whole answer (no
			# redirect after it), and the session itself is marked denial, so these
			# cookies meet that page on every later request - public pages and
			# static assets included - and carry no usable credential
			$c->session('authentication' => 'denial');
			$c->session('privilege' => 'blacklisted');
			$c->session('suds_id' => undef);
			$c->session('database' => undef);
			$c->render(template => 'guest_layouts/denial');
		}
		else {
			$c->session('role' => $ticket->{'privilege'});
			my $warranty = &subs::ago_calc(&subs::setting_grabber({ 'app' => $ticket->{'name'}, setting => 'warranty' }), $timestamp);
			#&subs::db_insert('appointments',{ uuid => &subs::random_string_creator(40), app => $ticket->{'name'}, warranty => $warranty, type => "entry", timestamp => $timestamp, server_time => $server_time });
			$c->session('database' => $database);
			$c->session('authentication' => 'approved');
			&subs::vault_seed($suds);
			$c->session('suds_id' => &subs::suds_id($suds));
			$c->session('server_time' => $server_time);
			$c->session('warranty' => $ticket->{'warranty'});
			$c->session('source' => 'ticket');
			$c->session('ticket_uuid' => $ticket->{'uuid'});
			$c->session('name' => $ticket->{'name'});
			$c->session('privilege' => $ticket->{'privilege'});
			$c->session('project' => $ticket->{'project'});
			$c->session('app' => $ticket->{'app'} );
			$c->session('padlock' => $server_time) if (scalar @{&subs::db_select('security', [ 'level' ], { level => 'padlock' })->hashes} > 0);
			$access->{'status'} = 'approved';


			my $mail_ws_url = 'wss://' . $c->req->url->base->host . ':' . $ENV{PORT_MSG} . '/mail/ws';
			# the splash always wears the drawing (the hand the denial page shows too)
			my $image = &subs::icon_drawn($gb::known_appts->{$ticket->{'privilege'}}->{'icon'});
			my %js = (
				title => 'Box Office',
				layout => 'gate',
				template => 'guest_layouts/box_office',
				'authentication' => 'approved',
				port => $ENV{PORT_AHOY},
				ws_port => $ENV{PORT_MSG},
				alarm_port => $ENV{PORT_BELL},
				device => $device,
				manager_file => &manager_file_maker($c->session('name')),
				ticket => $ticket,
				image => $image,
				# the redirect screen's mark: the house's own logo, which sinks into
				# its lower loop (the hole) rather than showing a privilege icon
				logo => &subs::setting_grabber({ app => 'me', setting => 'logo' })
			);
			my $msg = encode_json { app => 'server', ticket => $ticket, timestamp => $timestamp };
			if ($ticket->{'privilege'} eq 'citizen') {
				$js{'redirector'} = $base_url . '/manager';
				$js{'debriefer'} = $ticket->{'debriefer'};
				$js{'js'} = encode_json \%js;
				$c->render(%js);
			}
			elsif ($ticket->{'privilege'} eq 'resident') {
				$js{'debriefer'} = $ticket->{'debriefer'};
				$js{'redirector'} = $base_url . '/store?app=' . $ticket->{'app'};
				$js{'js'} = encode_json \%js;
				$c->render(%js);
			}
			elsif ($ticket->{'privilege'} eq 'guest') {
				$js{'redirector'} = $base_url . '/';
			#	$js{'debriefer'} = $deb;
				$js{'js'} = encode_json \%js;
				$c->render(%js);
			}
		}
	}
	else {
		# a blacklisted ticket marks the session even when it is expired or
		# suspended: the secret proves whose browser it is, and a blacklisted one
		# is allowed no public pages afterwards (an expired ticket still is)
		if ($ticket->{'privilege'} && $ticket->{'privilege'} eq 'blacklisted' && $genuine) {
			$c->session('authentication' => 'denial');
			$c->session('privilege' => 'blacklisted');
			$c->session('suds_id' => undef);
			$c->session('database' => undef);
		}
		$c->render(template => 'guest_layouts/denial');
	}
	unless ( grep { $_->{'server_time'} >= $server_time - 5000 } @{$access_log} ) {
		unshift @{$access_log}, $access;
		splice @{$access_log}, 20;
		$ticket->{'access_log'} = encode_json $access_log;
		$ticket->{'server_time'} = &subs::rightNow();
		&subs::db_update('tickets', $ticket, { uuid => $ticket->{'uuid'} });
	}
};

