post '/manager/configure/merge_database' => sub($c) {

	my $filename = $c->param('filename');
	my $action = $c->param('action');
	&subs::subprocessor(sub {
    Mojo::IOLoop->reset;
		my $configuration = {
			file => $filename,
			signatorial => &subs::signatorial_designer(),
			misc_settings => &misc_setting_list()
		};
		my $disposition = &merge_database($c,$configuration);
		my $temporary_file = $disposition->{'temporary_file'};
		#`shred -u $temporary_file` if -e $temporary_file;
		#`shred -u $temporary_file-shm` if -e $temporary_file;
		#`shred -u $temporary_file-wal` if -e $temporary_file;
		$disposition = encode_json $disposition;
	}, { name => 'merge database' });
	my $disposition = { status => 'working' };
	$c->render(json => $disposition);
};

# Merge one table's rows into the live database. The row source is a closure so the
# encrypted-snapshot path (rowid batches from a temp SQLite) and the row-stream path
# share every table-specific rule: uuid upsert, protected settings, utility
# controller keys, window state, continent temporary rows, file mirrors, deletions.
# The body keeps its original `next` statements: a one-pass ROW label makes a row's
# `next` leave just that row, while a `next` inside a nested loop still binds to it.
sub merge_table_rows {
	my ($ctx, $q, $next_row, $results_size, $count, $table_total) = @_;
	my $configuration = $ctx->{'configuration'};
	my $misc_settings = $ctx->{'misc_settings'};
	my $device = $ctx->{'device'};
	my $deletions = $ctx->{'deletions'};
	my $universal_settings = $ctx->{'universal_settings'};
	my $updateables = $ctx->{'updateables'};
	my $cache_bucket_updateables = $ctx->{'cache_bucket_updateables'};
	my $sync_job = $ctx->{'sync_job'};
	my $auuid = $ctx->{'auuid'};
	my $colour = $ctx->{'colour'};
	my $merge_short = 0;
	# A peer on newer code can carry a column this database has not been migrated for.
	# The insert then fails ("table X has no column named Y") and the same batch is
	# pulled again on every tick - the column equivalent of the unknown-table skip in
	# sync_rows_pull. Drop the columns this table does not have; `uuid` always stays
	# because it names the row.
	my %local_columns = map { $_->{'name'} => 1 } @{ &subs::db_query('select name from pragma_table_info(?)', $q)->hashes || [] };
	my %skewed_columns;
						if ($sync_job) {
							my %step = (label => 'merge ' . $q, state => 'running', current => 0);
							$step{'total'} = $results_size if $results_size;
							$step{'note'} = $results_size . ' row' . ($results_size == 1 ? '' : 's') if $results_size;
							&subs::sync_job_step($sync_job, 'merge:' . $q, \%step);
						}
						#&subs::say_it('Now merging ' . $results . ' ' .$q);
						my $progress = $count / $table_total * 100;
						my $html = '<h3>Now merging ' . $results_size . ' ' . $q . '</h3><br>';
						&Websocket::send('tab', { yellow => $html, uuid => $auuid, colour => $colour,
							progress => int($count / (($table_total) || 1) * 100), state => 'running' });
						my $percentage = 0;
						my $last_percent = 0;
						my $last_alert = &subs::rightNow();
						my $job_alert = $last_alert;
						my $start_time = $last_alert;
						# Book-keeping for the audit trail: a table can report "N/N done"
						# while an insert silently failed inside the eval below. Count what
						# the snapshot held, what the cursor actually yielded, and what
						# landed, so a short merge names itself in the log instead of
						# looking complete.
						my $rows_read = 0;
						my $rows_inserted = 0;
						my $rows_updated = 0;
						my @insert_errors;
						# Read the snapshot in bounded batches instead of holding one cursor
						# across the loop. Every row does app-database work (select, insert,
						# sync_job writes); if any of those finishes the snapshot's statement
						# - which is what the log showed: every table read exactly one row,
						# the rest silently lost - a materialised batch is immune. It also
						# keeps a whole table's rows out of memory.
	my $merge_one = sub {
		my ($r, $n) = @_;
		ROW: for my $once (1) {
			if (%local_columns && ref $r eq 'HASH') {
				my @unknown = grep { $_ ne 'uuid' && !$local_columns{$_} } keys %{$r};
				if (@unknown) {
					delete @{$r}{@unknown};
					$skewed_columns{$_} = 1 for @unknown;
				}
			}
							my @resulters = @{&subs::db_select($q, undef, { uuid => $r->{'uuid'} })->hashes};
							my $h = $resulters[0];
							$percentage = $results_size ? sprintf("%.2f", $n / $results_size * 100) : 0;
							if ($sync_job && &subs::rightNow() >= ($job_alert + 250)) {
								&subs::sync_job_step($sync_job, 'merge:' . $q, { current => $n, total => $results_size });
								$job_alert = &subs::rightNow();
							}
							if ($r->{'timestamp'}) {
								if ($percentage >= $last_percent && $results_size > 1 && &subs::rightNow() >= ($last_alert + 250)) {
									my $speed = abs sprintf("%.2f", $n / ($start_time - &subs::rightNow()) * 1000);
									my $remaining = &subs::duration_sayer(((&subs::rightNow() - $start_time) / $percentage) * (100 - $percentage) / 1000);
									my $html = '<b style="font-size:20px">' . $n . ' / ' . $results_size . ' ' . &subs::format_name($q) . ' ' . $percentage . '% @ ' . $speed . '/sec ' . $remaining . '</b><br>' .
										'<progress style="width:70%;height:60px;" value="' . $n . '" max="' . $results_size . '"></progress>';
									$last_percent = $percentage;
									$last_alert = &subs::rightNow();
									&Websocket::send('tab', { yellow => $html, uuid => $auuid, colour => $colour });
								}
								if ($q eq 'websites') {
									&web_history_deleter($r->{'app'});
								}
								if ($q eq 'continent') {
									if ($r->{'type'} eq 'temporary' && $r->{'app'} eq '__president') {
										my $continents = &subs::db_query('select * from continent where app = ? and type = ? and signatorial = ? and server_time > ?', $r->{'app'}, $r->{'type'}, $r->{'signatorial'}, $r->{'server_time'})->hashes;
										if (scalar @{$continents} > 0) {
											next;
										}
										else {
											&subs::db_delete('continent', { app => $r->{'app'}, type => $r->{'type'}, signatorial => $r->{'signatorial'} });
										}
									}
								}
								if ($q eq 'settings') {
									# Window/tab state is the machine's own view, not a setting: a
									# peer's snapshot must never open or move a window here.
									if (($r->{'setting'} || '') =~ /^(?:open_tabs|scrollTop|jopen|dimensions)$/) { next; }
									# The utility controller keeps every machine's jobs in one blob keyed
									# by that machine's signatorial. The generic whole-row replace below
									# would let whichever peer synced last win outright, wiping the other
									# machines' keys (their runtimes then reseed to the built-in
									# defaults - the "jobs all turned off" that started this). Merge the
									# blob per key instead: union the keys, and for a key both sides
									# hold keep the one whose __settings.last_change is newer (ours is
									# always authoritative for our own signatorial).
									if (($r->{'setting'} || '') eq 'utility_controller' && ($r->{'app'} || '') eq '__president') {
										my $sig = &subs::signatorial_designer();
										my %device_key = map { $_ => 1 } @gb::device_types;
										my $local = eval { decode_json &subs::setting_grabber({ app => '__president', setting => 'utility_controller', benign => 1 }) } || {};
										my $theirs = eval { decode_json $r->{'value'} } || {};
										my $merged = {};
										foreach my $k ( keys %{$local} ) { $merged->{$k} = $local->{$k}; }
										foreach my $k ( keys %{$theirs} ) {
											# our own row and the vestigial device-type rows are never taken from
											# a peer: our row is authoritative (the runtime reads only it, keyed
											# by our signatorial), and a device-type row must not be resurrected
											# once pruned. Only other machines' rows merge by last_change.
											next if $k eq $sig || $device_key{$k};
											if (!$merged->{$k}) { $merged->{$k} = $theirs->{$k}; next; }
											my $la = $merged->{$k}->{'__settings'}->{'last_change'} || 0;
											my $lb = $theirs->{$k}->{'__settings'}->{'last_change'} || 0;
											$merged->{$k} = $theirs->{$k} if $lb > $la;
										}
										my $jmerged = encode_json $merged;
										my $jcur = encode_json $local;
										if ($jmerged ne $jcur) {
											# name any navigation toggle this merge is about to change, per row -
											# a third machine's stale copy must not read a job off unnoticed
											foreach my $k ( keys %{$merged} ) {
												my $was = $local->{$k}->{'navigation'}->{'toggle'} // '-';
												my $now = $merged->{$k}->{'navigation'}->{'toggle'} // '-';
												&subs::log_writer('utility merge: ' . substr($k, 0, 8) . ' navigation ' . $was . '->' . $now . ' from ' . substr($r->{'signatorial'} // '?', 0, 8)) if $was ne $now;
											}
											&subs::setting_setter({ app => '__president', setting => 'utility_controller', value => $jmerged, server_time => &subs::rightNow(), sync => 1 });
										}
										next;
									}
									$universal_settings->{$r->{'app'}} = &subs::settings_grabber({ app => $r->{'app'}, device => $device, benign => 1 }) unless $universal_settings->{$r->{'app'}};
									my $protected = 0;
									foreach my $pr ( @gb::protected ) {
										if ($r->{'app'} eq $pr) {
											$protected = 1;
										}
									}
									#next if $protected == 1;
									unless ($universal_settings->{$r->{'app'}}->{'unique'} eq 'checked' || $protected == 1) {
										push @{$cache_bucket_updateables}, $r->{'app'} unless grep { $_ eq $r->{'app'} } @{$cache_bucket_updateables};
										# A row we already hold at the peer's own server_time counts as present:
										# the write below copies the peer's server_time verbatim, so with a strict
										# '>' the test was false again on the very next sync and every one of
										# the ~29k settings rows was deleted and reinserted, every sync, forever
										# (the 'Now merging N settings' that looked stuck). '>=' skips the row we
										# already hold, and still lets a genuinely newer peer value land.
										my $time_check = $r->{'subsetting'} ? &subs::db_query('select app,setting,value from settings where app=? and setting=? and subsetting = ? and server_time >= ?',
												$r->{'app'}, $r->{'setting'}, $r->{'subsetting'}, $r->{'server_time'})->hashes :
											&subs::db_query('select app,setting,value from settings where app=? and setting=? and server_time >= ?',
												$r->{'app'}, $r->{'setting'}, $r->{'server_time'})->hashes;
										if (scalar @{$time_check} == 0) {
											eval {
												&subs::setting_setter({
													app => $r->{'app'},
													setting => $r->{'setting'},
													value => $r->{'value'},
													server_time => $r->{'server_time'},
													uuid => &subs::random_string_creator(20),
													device => $device,
													subsetting => $r->{'subsetting'},
													sync => 1
												});
											};
										}
										# Do not reload the app's whole settings map for every row: a
										# pull carries hundreds of changed settings, and each reload
										# copies every value of that app (some are multi-megabyte
										# blobs). One load per app is enough to answer `unique`.
										next;
									}
								#	push @cache_bucket_updateables, $r->{'app'} unless grep { $_ eq $r->{'app'} } @cache_bucket_updateables;
								#	&subs::setting_setter($r);
									next;
								}
								if ($q eq 'security') {
									if ($r->{'level'} == 1) {
										my $sec_uuid = &subs::db_select('security', ['uuid'], { level => 1 })->hash->{uuid};
										$r->{'level'} = 2 unless $sec_uuid eq $r->{'uuid'};
									}
								}

								if ($r->{'app'} && ($r->{'measures'} || $h->{'measures'})) {
									my $r_measures = eval { return decode_json $r->{'measures'} } || [];
									my $h_measures = eval { return decode_json $h->{'measures'} } || [];
									my $change = 0;
									foreach my $h_m ( @{$h_measures} ) {
										my @r_m = grep { $_->{'uuid'} eq $h_m->{'uuid'} } @{$r_measures};
										my $r_m = $r_m[0];
										$r_m->{'timestamp'} = $r_m->{'timestamp'} || $r_m->{'ts'} || $r_m->{'server_time'};
										if (scalar @r_m == 0) {
											push @{$r_measures}, $h_m;
											$change = 1;
										}
										elsif ($h_m->{'timestamp'} > $r_m->{'timestamp'}) {
											@{$r_measures} = grep { $_->{'uuid'} ne $h_m->{'uuid'} } @{$r_measures};
											push @{$r_measures}, $h_m;
											$change = 1;
										}
										$r->{'measures'} = encode_json $r_measures if $change == 1;
									}
								}

								if ($configuration->{'remote'}->{'manager'} && $r->{'app'} && ($r->{'file'} || $h->{'file'}) && $r->{'type'} ne 'snapshot' && $r->{'type'} ne 'backup' && $r->{'account'} ne 'gallery') {
									my $files = eval { return decode_json $r->{'file'} } || [];
									my $h_files = eval { return decode_json $h->{'file'} } || [];
									if (eval { $files->{'f'} }) { $files = [ $files ]; }
									if (eval { $h_files->{'f'} }) { $h_files = [ $h_files ]; }
									if ($q eq 'appointments') {
										$universal_settings->{$r->{'app'}}->{'enc'} = &subs::setting_grabber({ app => $r->{'app'}, device => $device, benign => 1 }) unless $universal_settings->{$r->{'app'}}->{'enc'};
										if ($universal_settings->{$r->{'app'}}->{'enc'} eq 'on' && !$r->{'encryption_standard'} && $r->{'server_time'} > &subs::ago_calc('10m', &subs::rightNow()) && scalar @{$files} > 0) {
											next;
										}
									}

									if (scalar @resulters > 0) {
										foreach my $home_file ( @{$h_files} ) {
											if ($home_file->{'server_time'} <= $r->{'server_time'} ) {
												unless ( grep { $home_file->{'uuid'} eq $_->{'uuid'} } @{$files}) {
												#	&delete_file({ app => $h->{'app'}, app_uuid => $h->{'uuid'}, file_uuid => $home_file->{'uuid'} });
													push @{$files}, $home_file;
													$r->{'server_time'} = &subs::rightNow();
												}
											}
											else {
												unless ( grep { $home_file->{'uuid'} eq $_->{'uuid'} } @{$files}) {
													push @{$files}, $home_file;
												}
											}
										}
									}
									my $file_count = 0;
									foreach my $fi ( @{$files} ) {
										$file_count++;
										foreach my $file_type ( qw/f thumb/ ) {
											next unless $fi->{$file_type};
											my $file = $fi->{$file_type};
											$last_percent = $percentage;
											$percentage = sprintf("%.2f", ($n + ($file_count / scalar @{$files})) / $results_size * 100);


											if ($percentage >= $last_percent && $results_size > 0 && &subs::rightNow() >= ($last_alert + 250)) {
												my $speed = abs sprintf("%.2f", $n / ($start_time - &subs::rightNow()) * 1000);
												my $remaining = &subs::duration_sayer(((&subs::rightNow() - $start_time) / $percentage) * (100 - $percentage) / 1000);
												my $html = '<b style="font-size:20px">' . sprintf("%.2f", ($n + ($file_count / scalar @{$files}))) . ' / ' . $results_size . ' ' . &subs::format_name($q) . ' ' . $percentage . '% @ ' . $speed . '/sec ' . $remaining .'</b><br>' .
													'<progress style="width:70%;height:60px;" value="' . $n . '" max="' . $results_size . '"></progress>';
												$last_percent = $percentage;
												$last_alert = &subs::rightNow();
												&Websocket::send('tab', { yellow => $html, uuid => $auuid, colour => $colour });
											}
											my ($destination,$asset,$type) = &subs::file_device_renamer({ file => $file, app => $r->{'app'}, misc_settings => $misc_settings, type => $fi->{'type'} });
											$fi->{'type'} = $type unless $fi->{'type'};
											my $dest = $destination . $asset;

											if (my @h_fil = grep { $_->{'uuid'} eq $fi->{'uuid'} } @{$h_files} ) {
												my $h_file = $h_fil[0];

												my ($hdestination,$hasset) = &subs::file_device_renamer({ file => $h_file->{$file_type}, app => $h->{'app'}, misc_settings => $misc_settings, type => $h_file->{'type'} });
												unless ($asset eq $hasset) {
													if (-e $destination . $hasset) {
														my $hassethoff = $destination . $hasset;
														`shred -u $hassethoff`;
													}
												}
											}

											unless (-e $dest) {
												`mkdir -p $destination`;
												$destination = $destination . $asset;
												if ($configuration->{'remote'}) {
													#$file = url_unescape $file;
													my $url = $configuration->{'remote'}->{'manager'} . '/file_open?timestamp=' . $r->{'server_time'} . '&as_is=yes&file=' . $file;
													my $file_data = $configuration->{'remote'}->{'ua'}->get($url)->result;
													if ($file_data) {
														unless ($file_data->body eq 'not found') {
															my $fd = $file_data->body;
															$fd = decode_base64 $fd;
															write_file($dest,$fd);
														}
													}
												}
											}
											$file = $dest;
											$fi->{$file_type} = $file;
										}
									}
									$r->{'file'} = encode_json $files;
								}
								unless ( grep { ($_->{'uuid'} eq $r->{'uuid'} ) && $_->{'table'} eq $q } @{$deletions} ) {
									if (scalar @resulters == 0) {
										my $inserted = eval { &subs::db_insert($q,$r)};
										if ($@) { push @insert_errors, ($r->{'uuid'} || '?') . ': ' . ($@ =~ s/\s+/ /gr); }
										elsif ($inserted) { $rows_inserted++; }
										else { push @insert_errors, ($r->{'uuid'} || '?') . ': refused'; }
									}
									else {
										$rows_updated++ if $h->{'server_time'} < $r->{'server_time'};
										eval { &subs::db_update($q,$r, { uuid => $r->{'uuid'} } ) } unless $h->{'server_time'} >= $r->{'server_time'};
									}
									if ($q eq 'appointments' && (!$h->{'server_time'} || $r->{'server_time'} > $h->{'server_time'})) {
										push @{$updateables}, { app => $r->{'app'}, uuid => $r->{'uuid'} } unless grep { $_->{'app'} eq $r->{'app'} } @{$updateables};
									}
								}
							}
		}
	};
	for (my $n = 0; !$results_size || $n < $results_size; $n++) {
		my $r = $next_row->();
		last unless $r;
		$rows_read++;
		$merge_one->($r, $n);
	}
						my $short = ($results_size && $rows_read < $results_size) ? ' SHORT' : '';
						# An insert that failed is not a merged table, for the same reason a
						# short read is not: claiming success stores the peer's picture in
						# `sync_seen` and the missing rows are never asked for again. Report
						# both, and let the pull retry.
						my $merge_errors = scalar @insert_errors;
						$merge_short = 1 if $short || $merge_errors;
						my $errors = $merge_errors ? ' errors=' . join(' | ', @insert_errors[0 .. ($#insert_errors > 2 ? 2 : $#insert_errors)]) : '';
						my $skew = scalar keys %skewed_columns ? ' skipped-columns=' . join(',', sort keys %skewed_columns) : '';
						&subs::log_writer('merge ' . $q . ': snapshot=' . $results_size . ' read=' . $rows_read . ' inserted=' . $rows_inserted . ' updated=' . $rows_updated . $short . $errors . $skew);
						if ($sync_job) {
							&subs::sync_job_step($sync_job, 'merge:' . $q, { state => ($short || $merge_errors) ? 'failed' : 'done', current => ($results_size || $rows_read), total => ($results_size || $rows_read), note => $short ? 'read ' . $rows_read . ' of ' . $results_size : ($merge_errors ? $merge_errors . ' row errors' : '') });
						}
	return $merge_short;
}

# The post-merge work shared by the snapshot path and the row-stream path: refresh
# the header/budget for appointments that moved, apply the deletions that came with
# the pull, and drop the relational caches an app's settings invalidate.
sub merge_finish {
	my ($ctx) = @_;
	my $configuration = $ctx->{'configuration'} || {};
	my $updateables = $ctx->{'updateables'} || [];
	my $cache_bucket_updateables = $ctx->{'cache_bucket_updateables'} || [];
	my $auuid = $ctx->{'auuid'};
	my $colour = $ctx->{'colour'};
	my $percentage = 0;
	my $last_percent = 0;
	my $last_alert = &subs::rightNow();
	my $start_time = $last_alert;
	my $results_size = scalar @{$updateables};
	for (my $n = 0; $n < $results_size; $n++) {
		my $u = $updateables->[$n];
		next unless ref $u eq 'HASH' && $u->{'app'};
		&budget_runner($u->{'app'});
		&subs::appt_header_printer({ app => $u->{'app'}, timestamp => &subs::rightNow() });
		&Websocket::send('tab', { console => 'appointmentDetailGrabber(\'' . $u->{'app'} . '\',\'' . $u->{'uuid'} .'\');' });
		$percentage = sprintf("%.2f", $n / $results_size * 100);
		$percentage = .0000001 if $percentage == 0;
		if ($percentage >= $last_percent && $results_size > 1 && &subs::rightNow() >= ($last_alert + 250)) {
			my $speed = abs sprintf("%.2f", $n / ($start_time - &subs::rightNow()) * 1000);
			my $remaining = &subs::duration_sayer(((&subs::rightNow() - $start_time) / $percentage) * (100 - $percentage) / 1000);
			my $html = '<b style="font-size:20px">' . $n . ' / ' . $results_size . ' ' . &subs::format_name('informations') . ' ' . $percentage . '% @ ' . $speed . '/sec ' . $remaining . '</b><br>' .
				'<progress style="width:70%;height:60px;" value="' . $n . '" max="' . $results_size . '"></progress>';
			$last_percent = $percentage;
			$last_alert = &subs::rightNow();
			&Websocket::send('tab', { yellow => $html, uuid => $auuid, colour => $colour });
		}
	}
	&deletion_performer($configuration->{'remote'}->{'deletions'}) if $configuration->{'remote'};
	if ( scalar @{$cache_bucket_updateables} > 0 ) {
		my $buc = &subs::cache_get({ app => 'relational', context => 'buckets' });
		my $bub = &subs::cache_get({ app => 'relational', context => 'bubbles' });
		foreach my $cbd ( @{$cache_bucket_updateables} ) {
			delete $buc->{$cbd};
			delete $bub->{$cbd};
		}
		&subs::cache_set({ app => 'relational', context => 'buckets' }, $buc);
		&subs::cache_set({ app => 'relational', context => 'bubbles' }, $bub);
	}
}

# Merge an encrypted snapshot: the full-migration / deep-gimme / v2 path. A normal
# v3 delta never gets here - `sync_rows_pull` feeds the same merge_table_rows and
# merge_finish directly from the row batches.
sub merge_database($c,$configuration) {
	&update_database($c);
	my $filename = $configuration->{'file'};
	my $remote_misc_settings = $configuration->{'misc_settings'};
	my $misc_settings = &misc_setting_list();
	my $device = &subs::device_setter();
	my $deletions = eval { return decode_json $configuration->{'remote'}->{'deletions'} } || [];

	my $rdel = &subs::db_select('remote_machines', [ 'deletions' ], {})->hashes;
	foreach my $rd ( @{$rdel} ) {
		my $all_deletions = eval { return decode_json $rd->{'deletions'} } || [];
		push @{$deletions}, @{$all_deletions};
	}


	my $port = $config->{'ssh_port'};
	my $auuid = &subs::random_string_creator(10);
	my $colour = $configuration->{'colour'};
	my $html = '<h3>Starting Merge ' . $filename . '</h3>';
	&Websocket::send('tab', { yellow => $html, uuid => $auuid, colour => $colour });
	my ($db,$database) = &subs::database_grabber();
	my $disposition->{'status'} = 'fail';
	# A table the cursor could not finish is not a merge. `remote_upgrade` writes
	# the peer's picture into `sync_seen` after a successful merge, so reporting
	# succeed after a short read made a partial pull look like a full
	# reconciliation - the next tick then skipped the table and the rows stayed
	# missing. Keep the disposition honest so the pull retries.
	my $merge_short = 0;
	my $path = $filename;
	my $download_location = &subs::home('~/.president');
	my $temp_folder = &subs::home($download_location . '/' . &subs::random_string_creator(10));
	`mkdir -p $temp_folder` unless -e "$temp_folder";
	my $temporary_file = $temp_folder . '/tmpman.db';
	my $credentials = &subs::db_query('select level,credential from security where level != ? order by server_time DESC', 'padlock');
	my $creds = $credentials->hashes;
	my $signatorial = &subs::signatorial_designer();
	my $last_update_time = &subs::db_select('backups', undef, { recipient => $signatorial, signatorial => $configuration->{'signatorial'} })->hashes->[-1];
	$last_update_time = $last_update_time->{'server_time'} || 0;
	$last_update_time = $configuration->{'gimme'} if $configuration->{'gimme'};
	@{$creds} = grep { $_->{'level'} ne 'padlock' } @{$creds};
	@{$creds} = reverse @{$creds};
	my $encryption_standard = &subs::setting_grabber({ app => 'misc', setting => 'encryption_standard' } ) || "aes-256-ctr";
	my @updateables;
	my @cache_bucket_updateables;
	my $suds = &subs::session_suds($c) || &subs::suds_grabber();
	my $merge_ctx;
	foreach my $cred ( @{$creds} ) {
		my $crud = &subs::decrypter($suds,$cred->{'credential'});
		my $html = '<h3>Testing Keys</h3>';

		&Websocket::send('tab', { yellow => $html, uuid => $auuid, colour => $colour });
		if ($path =~ /enc$/gi) {
			my $data = `tail $path`;

			my @split_data = split $universal_splitter, $data;

			unless ($data =~ /\Q$universal_splitter/gi) {
				# The marker is appended after the ciphertext. If it is not in the tail,
				# the file we downloaded is not the finished container (truncated, or
				# not the archive at all) - say so instead of silently skipping the key.
				$log->error('merge container: standard marker missing; tail=' . length($data) . ' bytes') if $log;
				next;
			}

			$encryption_standard = &subs::decrypter($crud, $split_data[1]);
			&subs::openssl_file_crypt('d', $encryption_standard, $crud, $path, $temporary_file, 1, 1);

			my $tsql = Mojo::SQLite->new('sqlite:' . $temporary_file);
			my $decrypted_size = (-s $temporary_file) || 0;
			my $snapshot_db = eval { $tsql->db ? 1 : 0 };
			my $snapshot_ok = ($decrypted_size > 5000 && $snapshot_db && $tsql->dsn !~ /:$/) ? 1 : 0;
			# A merged table leaves a "merge <table>" line; a pull that never gets
			# there has failed at the container itself, and used to leave only "merge
			# did not finish" with no reason. Say which credential opened what.
			$log->error('merge snapshot: level=' . ($cred->{'level'} || '?') . ' archive=' . ((-s $path) || 0)
				. ' decrypted=' . $decrypted_size . ' db=' . ($snapshot_db ? 1 : 0) . ' dsn=' . $tsql->dsn) if $log && !$snapshot_ok;
			if ($snapshot_ok) {
				my $tdb = $tsql->db;

				my $backups = &subs::db_query('select * from backups order by server_time DESC' )->hashes;

				my $start_server_time = 0;
				if ( scalar @{$backups} > 1 ) {
					$start_server_time = $backups->[1]->{'server_time'};
				}

				my $html = '<h3>Now merging</h3>';
				&Websocket::send('tab', { yellow => $html, uuid => $auuid, colour => $colour });
				$disposition->{'temporary_file'} = $temporary_file;
				my $stats = [];
				my $tables = `sqlite3 $temporary_file .tables`;

				my @u = sort split ' ', $tables;

				my $count = 0;
				my $universal_settings = {};
				my $sync_job = $configuration->{'sync_job'};
				&subs::sync_job_update($sync_job, { phase => 'merge', current => 0, total => scalar @u }) if $sync_job;
				$merge_ctx = {
					configuration => $configuration,
					misc_settings => $misc_settings,
					device => $device,
					deletions => $deletions,
					universal_settings => $universal_settings,
					updateables => \@updateables,
					cache_bucket_updateables => \@cache_bucket_updateables,
					sync_job => $sync_job,
					auuid => $auuid,
					colour => $colour,
				};
				foreach my $q ( @u ) {
					next if grep { $q eq $_ } @{$gb::forbidden->{'tables'}};
					# Count first, then read the snapshot's rows in bounded batches. A
					# full convergence carries a whole table (110k appointments), so
					# ->hashes on everything would hold it all in memory on top of the
					# merge; the batch reader below keeps one page at a time.
					my $results_size = ($tdb->query('select count(*) as c from ' . $q)->hash->{'c'} || 0) + 0;
					if ($results_size > 0) {
						$count++;
						&subs::sync_job_update($sync_job, { current => $count }) if $sync_job;
						my @merge_batch;
						my $merge_rowid = 0;
						my $merge_all;
						my $next_row = sub {
							unless (scalar @merge_batch) {
								return undef if $merge_all;
								my $rows = eval { $tdb->query('select rowid as __merge_rowid, * from ' . $q . ' where rowid > ? order by rowid limit 500', $merge_rowid)->hashes };
								if (!$rows) {
									# a table without a rowid (a view) is read whole, once
									$merge_all = 1;
									$rows = $tdb->query('select * from ' . $q)->hashes;
								}
								@merge_batch = @{$rows || []};
								return undef unless scalar @merge_batch;
							}
							my $row = shift @merge_batch;
							$merge_rowid = delete $row->{'__merge_rowid'} if exists $row->{'__merge_rowid'};
							return $row;
						};
						my $short = &merge_table_rows($merge_ctx, $q, $next_row, $results_size, $count, scalar @u);
						$merge_short = 1 if $short;
					}
					$disposition->{'disposition'} = $database;
					$disposition->{'status'} = $merge_short ? 'failed' : 'succeed';
					my $known_backup = &subs::db_select('backups', undef, { uuid => $backups->[0]->{'uuid'} })->hashes;
					if ($known_backup->[0]->{'reason'} =~ /remote/gi) {
						my $defunct_backups = &subs::db_query('delete from backups where recipient=? and signatorial=? and destination=? and server_time < ? and uuid != ?',
							$backups->[0]->{'recipient'}, $backups->[0]->{'signatorial'}, $backups->[0]->{'destination'}, $backups->[0]->{'server_time'}, $backups->[0]->{'uuid'});
						$disposition->{'backup_uuid'} = $backups->[0]->{'uuid'};
					}
				}
				last;
			}
		}
	}
	&merge_finish($merge_ctx) if $merge_ctx;
	&Websocket::send('tab', { yellow => 'close', 'close' => 'yes', uuid => $auuid, colour => $colour });
	&subs::say_it('fail') unless $disposition->{'status'} eq 'succeed';
	`shred -u $temporary_file` if -e $temporary_file;
	`shred -u $temporary_file-shm` if -e $temporary_file;
	`shred -u $temporary_file-wal` if -e $temporary_file;
	`rm -R $temp_folder`;
	return $disposition;
}



get '/manager/budget' => sub($c) {
	my $totals = {};
	my $tally = {};
	my $budgets = {};
	my $new_settings = eval { return decode_json $c->param('new_settings') } || {};
	foreach my $ns ( keys %{$new_settings} ) {
		if ($new_settings->{$ns} =~ /[A-Za-z0-9.,-]/gi) {
			if ($ns =~ /_time/gi) {
				$new_settings->{$ns} = &subs::ago_calc($new_settings->{$ns}, &subs::rightNow());
			}
			&subs::setting_setter({ app => 'budget', setting => $ns, value => $new_settings->{$ns} });
		}
		else {
			&subs::setting_deleter({ app => 'budget', setting => $ns });
		}
	}
	my @dollas = qw/amount tax aux total/;
	my @categories = qw/category subcategory/;
	my $categories = { };
	for (my $n = 1; $n <= 100; $n++) {
		my $u = 'subcategory' . $n;
		push @categories, $u;
	#	$categories->{$u} = {};
	}

	my $timestamp = $c->param('timestamp');
	my $time_machine = $c->param('time_machine');

	my $settings = &subs::settings_grabber({ app => 'budget' });
	my $display = $c->param('display') || $settings->{'display'};
	if ($settings->{$display . '_display'} ne '') {
		my $d = eval { decode_json $settings->{$display . '_displays'} };
		foreach my $k ( keys %{$d->{$settings->{$display . '_display'}}} ) {
			$c->param($k, $d->{$settings->{$display . '_display'}}->{$k});
			&subs::setting_setter({ app => 'budget', setting => $k, value => $d->{$settings->{$display . '_display'}}->{$k} });
		}
		$d->{$settings->{$display . '_display'}}->{$display . '_display'} = $settings->{$display . '_display'};
		$settings = &subs::settings_grabber({ app => 'budget' });
	}
	my $display_categorization = $settings->{'display_categorization'};
	my $scope = $settings->{'scope'} || 'hour';
	my $movement = eval { decode_json $c->param('movement') || $settings->{'movement'} } || ['all'];

	my $project = eval { decode_json $c->param('projects') || $settings->{'projects'} } || ['all'];
	my $account = eval { decode_json $c->param('accounts') || $settings->{'accounts'} } || ['all'];
	my $columns = eval { decode_json $c->param('columns') || $settings->{'columns'} } || ['all'];
	my $timeshift = $c->param('timeshift');
	my ($db,$database,$sql) = &subs::database_grabber();
	my @columns = qw/app when occurences occurence_budget duration duration_budget duration_percent total_budget manufacturer item vendor account project amount tax aux total/;
	my $tr = {};

	my @time_scopes = ('next', 'this','last');
	my @time_widths;

	my @time_lengths = qw/minute hour day week month year/;
	if ($settings->{'s_visual'} eq 'allocation') {
		@time_scopes = undef;
		for (my $n = 0; $n <= 366; $n++) {
			push @time_scopes, $n;
		}
		@time_lengths = qw/second minute hour mday month year wday yday isdst/;
		@time_widths = ( 60, 60, 24, 31, 12, 150, 7, 365, 2 );
	}
	else {
		for (my $n = 2; $n <= 30; $n++) {
			push @time_scopes, $n . 'last';
			unshift @time_scopes, $n . 'next';
		}
	}


	my ($bt,$t1,$t2);
	# a father_time window ends on the next period's first instant, so that bound
	# is exclusive; an end_time the user picked stays inclusive
	my $t2_comp = '<=';
	if ($settings->{'start_time'} || $settings->{'end_time'}) {
		$bt = $settings->{'start_time'};
		$t2 = $settings->{'end_time'};
		if ($settings->{'start_time'} && !$settings->{'end_time'}) {
			$t2 = &subs::rightNow();
		}
		elsif (!$settings->{'start_time'} && $settings->{'end_time'}) {
			$bt = &subs::rightNow();
		}
	}
	else {
		if ($time_machine) {
			$timestamp = &time_machine_resolve($time_machine,$timestamp);
		}
		if ($timeshift) {
			$timestamp = &subs::ago_calc($timeshift,$timestamp);
		}
		$bt = &subs::time_span($scope, $timestamp); #timestamp at beginning
		$t1 = ($timestamp - $bt);
		$t2 = ($timestamp);
		# the multiplier widens the window in whole periods, the same way the
		# inventory's Nnext windows read it
		($bt, $t2) = &father_time({
			scope => $scope,
			ts => $settings->{'time_when'},
			lock => $settings->{'s_lock'},
			timestamp => $timestamp,
			periods => $settings->{'when_multiplier'} || 1
		});
		$t2_comp = '<';
	}
	my $total_duration = $t2 - $bt;
	my $last_inventory = $bt;
	my $accountals = &subs::db_query('select distinct(app) from settings where (setting=? or setting =?) and value=? order by app', 'pos', 'mab', 'account');
	my $accounts = $accountals->hashes;

	push @{$accounts}, { app => 'gallery' };
	unshift @{$accounts}, { app => 'all' };

	my $all_accounts = $accounts;
	unless (grep { $_ eq 'all' } @{$account}) {
		my @acco;
		foreach my $a ( @{$account} ) {
			push @acco, grep { $_->{'app'} eq $a } @{$accounts};
		}
	$accounts = \@acco;
	}

	my $acc = {};

	my $all_columns = \@columns;
	if (grep { $_ eq 'all' } @{$columns}) {
		$columns = $all_columns;
	}

	my $projections = &subs::db_query('select distinct(app) from settings where (setting=? or setting=?) and value=? order by app', 'pos', 'mab', 'project');
	my $projects = $projections->hashes;
	unshift @{$projects}, { app => 'all' };
	my $all_projects = $projects;
	unless (grep { $_ eq 'all' } @{$project}) {
		my @proj;
		foreach my $a ( @{$project} ) {
			push @proj, grep { $_->{'app'} eq $a } @{$projects};
		}
		$projects = \@proj;
	}

	# the invoices display is a document ledger, not a money tally: collect the
	# documents once. (The old code ran this query inside the account loop as well,
	# which returned the same unrestricted window once per account and multiplied
	# every transaction - and its total - by the number of accounts.)
	my $documents = [];
	if ($display eq 'invoices') {
		my $docr = &subs::db_query("select * from appointments where type in ('invoice','quote') and timestamp >= ? and timestamp $t2_comp ? order by timestamp desc", $last_inventory, $t2)->hashes;
		foreach my $doc ( @{$docr} ) {
			$doc->{'data'} = eval { return decode_json $doc->{'data'} } || {};
			my $numbers = $doc->{'data'}->{'numbers'} || {};
			my $paid = 0;
			foreach my $p ( @{$doc->{'data'}->{'payments'} || []} ) {
				$paid += $p->{'amount'} if defined $p->{'amount'} && $p->{'amount'} =~ /[0-9]/;
			}
			$doc->{'paid'} = $paid;
			$doc->{'balance'} = defined $numbers->{'balance'} ? $numbers->{'balance'} : ($numbers->{'total'} || 0) - $paid;
			$doc->{'formatted_type'} = &subs::format_name($doc->{'type'});
			$doc->{'formatted_item'} = &subs::format_name($doc->{'data'}->{'item'});
			$doc->{'formatted_total'} = &subs::price_formatter($numbers->{'total'} || 0);
			$doc->{'formatted_paid'} = &subs::price_formatter($paid);
			$doc->{'formatted_balance'} = &subs::price_formatter($doc->{'balance'});
			$doc->{'formatted_status'} = $doc->{'status'} ? &subs::format_name($doc->{'status'}) : ($doc->{'type'} eq 'quote' ? 'Draft' : 'Open');
			$totals->{'documents'}->{'count'}++;
			$totals->{'documents'}->{$doc->{'type'}}->{'count'}++;
			foreach my $key ( qw/total paid balance/ ) {
				my $value = $key eq 'total' ? ($numbers->{'total'} || 0) : $key eq 'paid' ? $paid : $doc->{'balance'};
				$totals->{'documents'}->{$key} += $value;
				$totals->{'documents'}->{$doc->{'type'}}->{$key} += $value;
			}
		}
		push @{$documents}, @{$docr};
	}
	my $transactions;
	foreach my $accounting ( @{$accounts}) {
		next if $acc->{$accounting->{'app'}};
		$accounting->{'balance'} = 0;
		$accounting->{'settings'} = &subs::settings_grabber({ app => $accounting->{'app'} });
		my $inventory = &subs::db_query('select * from appointments where app=? and type=? and movement=? order by timestamp', $accounting->{'app'}, 'transaction','inventory');
		my $inv = $inventory->hashes;
		my $final_t = {};
		foreach my $i ( @{$inv} ) {
			if ($i->{'timestamp'} < $bt) {
				$accounting->{'balance'} = $i->{'amount'};
				$accounting->{'starting_balance'} = $i->{'amount'};
				push @{$accounting->{'journals'}}, { amount => $accounting->{'balance'}, timestamp => $i->{'timestamp'} };
				$last_inventory = $i->{'timestamp'};
				$final_t = $i;
				$final_t->{'timestamp'} = $bt;
			}
		}
#		push @{$transactions}, $final_t if $final_t->{'timestamp'};
		# the money moves now come from the warehouse ledger; the balance anchors
		# (inventory-movement appointments) are kept where they are for now, so the
		# statement is unchanged while the money it tallies lives on the ledger
		my $money_moves = &subs::db_query("select * from warehouse where kind = 'money' and account = ? and timestamp >= ? and timestamp $t2_comp ? order by timestamp",
			$accounting->{'app'},$last_inventory,$t2)->hashes;
		my $money_anchors = &subs::db_query("select * from appointments where account = ? and type != ? and movement = ? and timestamp >= ? and timestamp $t2_comp ? order by timestamp",
			$accounting->{'app'}, 'inventory', 'inventory', $last_inventory,$t2)->hashes;
		push @{$transactions}, sort { $a->{'timestamp'} <=> $b->{'timestamp'} } (@{$money_moves}, @{$money_anchors});
		if (grep { $_ eq 'all' } @{$movement}) {

		}
		else {
			my $transactionality = [];
			foreach my $m ( @{$movement} ) {
				push @{$transactionality}, grep { $_->{'type'} eq $m } @{$transactions};
			}
			$transactions = $transactionality;
		}
		$last_inventory = $bt;
		$acc->{$accounting->{'app'}} = $accounting;
	}
	unless ( grep { $_ eq 'all' } @{$project} ) {
		my $tp = [];
		foreach my $tr ( @{$project} ) {
			push @{$tp}, grep { $_->{'project'} eq $tr } @{$transactions};
		}
		$transactions = $tp;
	}

	foreach my $t ( @{$transactions} ) {
		if ($t->{'movement'} eq 'inventory') {
			$acc->{$t->{'account'}}->{'balance'} = $t->{'amount'};
			push @{$acc->{$t->{'account'}}->{'journals'}}, { amount => $acc->{$t->{'account'}}->{'balance'}, timestamp => $t->{'timestamp'} };
			$last_inventory = $t->{'timestamp'};
			next;
		}
		$tally->{$t->{'app'}} = {
			income => [],
			expense => [],
			transfer => [],
			totals => {},
			settings => &subs::settings_grabber({ app => $t->{'app' } })
		} unless $tally->{$t->{'app'}};


		my $pushable = $display_categorization;

		if ($display_categorization eq 'category') {
			$pushable = $tally->{$t->{'app'}}->{'settings'}->{'category'};
			if ($pushable eq '') {
				$pushable = 'unknown';
			}
		}
		elsif ($display_categorization eq undef || $display_categorization eq '') {
			$pushable = $t->{'app'};
		}
		else {
			$pushable = $t->{$display_categorization};
		}

		$tally->{$pushable} = {
			income => [],
			expense => [],
			transfer => [],
			totals => { },
			settings => &subs::settings_grabber({ app => $pushable })
		} unless $tally->{$pushable};

	#	$t->{'movement'} = 'expense' unless $t->{'movement'};
		$acc->{$t->{'account'}}->{'balance'} = $acc->{$t->{'account'}}->{'balance'} + $t->{'total'};
		push @{$acc->{$t->{'account'}}->{'journals'}}, { amount => $acc->{$t->{'account'}}->{'balance'}, timestamp => $t->{'timestamp'} };
		if ($t->{'timestamp'} < $bt) {
			$acc->{$t->{'account'}}->{'starting_balance'} = $acc->{$t->{'account'}}->{'balance'};
		}
		elsif ($t->{'timestamp'} >= $bt && $t->{'timestamp'} <= $t2) {
			foreach my $dolla (@dollas) {
				for (my $ca = 0; $ca <= scalar @categories; $ca++) {
					my $cat = $categories[$ca];
					my $cath = $cat;
					if ($tally->{$t->{'app'}}->{'settings'}->{$cat}) {
						my $distinct = $tally->{$t->{'app'}}->{'settings'}->{$cat};
						if (0 == 0) {
							$cath = $distinct;
						}
						unless ($categories->{$cath}->{'info'}->{$distinct}) {
							$categories->{$cath}->{'info'}->{$distinct} = &subs::settings_grabber({ app => $tally->{$t->{'app'}}->{'settings'}->{$cat} });
						}
						if ($ca > 1) {
							$cath = $categories->{$cath}->{'info'}->{'subcategory' . ($ca - 1)};
						}
						elsif ($ca > 0) {
							$cath = $categories->{$cath}->{'info'}->{'category'};
						}
						$categories->{$cath}->{$tally->{$t->{'app'}}->{'settings'}->{$cat}}->{'ca'} = $ca;
						if ($dolla eq 'amount') {
							push @{$categories->{$cath}->{$tally->{$t->{'app'}}->{'settings'}->{$cat}}->{'list'}}, $t;
						}
						$categories->{$cath}->{$tally->{$t->{'app'}}->{'settings'}->{$cat}}->{$dolla} += $t->{$dolla} if $t->{$dolla} =~ /[0-9]/;
					}
				}
			}
			if ($t->{'movement'} eq 'income') {
				$t->{'t'} = 'income';
				$t->{'occurences'} = 1;
				$t->{'duration'} = abs $t->{'duration'};
				foreach my $dolla ( @dollas ) {
					$t->{$dolla} = abs $t->{$dolla} if $t->{$dolla} =~ /[0-9]/;
				}
				foreach my $col ( @columns ) {
					$totals->{'income'}->{$col} += $t->{$col} unless $t->{$col} =~ /[a-zA-Z]/ || $t->{$col} !~ /[0-9]/;
				}
			}
			elsif ($t->{'movement'} eq 'transfer') {
				$t->{'t'} = 'transfer';
				$t->{'occurences'} = 1;
				$t->{'duration'} = abs $t->{'duration'};
				#unless (grep { $_->{'uuid'} eq $t->{'uuid'} } @{$tally->{$t->{'app'}}->{$t->{'movement'}}}) {
					foreach my $col ( @columns ) {
						$totals->{'transfer'}->{$col} += $t->{$col} unless $t->{$col} =~ /[a-zA-Z]/ || $t->{$col} !~ /[0-9]/;
					}
				#}
			}
			elsif ($t->{'movement'} eq 'expense') {
				$t->{'t'} = 'expense';
				$t->{'movement'} = 'expense';
				$t->{'occurences'} = 1;
				$t->{'duration'} = (abs $t->{'duration'}) * -1;
				foreach my $dolla ( @dollas ) {
					$t->{$dolla} = ($t->{$dolla});# * -1;
				}
				foreach my $col ( @columns ) {
					$totals->{'expense'}->{$col} += $t->{$col} unless $t->{$col} =~ /[a-zA-Z]/ || $t->{$col} !~ /[0-9]/;
				}
			}
			foreach my $col ( @columns ) {
				unless ($t->{$col} =~ /[a-zA-Z]/ || $t->{$col} !~ /[0-9]/) {
					$totals->{'total'}->{$col} += $t->{$col};
					$tally->{$pushable}->{'totals'}->{$t->{'movement'}}->{$col} += $t->{$col};
				}
			}
			push @{$tally->{$pushable}->{$t->{'movement'}}}, $t;
			@{$tally->{$pushable}->{$t->{'movement'}}} = sort { $b->{'timestamp'} <=> $a->{'timestamp'} } @{$tally->{$pushable}->{$t->{'movement'}}};
		}
	}
	foreach my $d ( keys %{$gb::transaction_types} ) {
		$totals->{$d}->{'duration_percent'} = &subs::percent_formatter(abs $totals->{$d}->{'duration'} / $total_duration);
		$totals->{$d}->{'duration'} = &subs::duration_sayer(abs $totals->{$d}->{'duration'} / 1000);
	}
	foreach my $app ( keys %{$tally} ) {
		foreach my $dr ( keys %{$gb::budget_modes} ) {
			my $budget = &budget_calculator({
				app => $app,
				budget => $tally->{$app}->{'settings'}->{'budget'},
				circumstance => $dr,
				scope => $scope,
				value => $tally->{$app}->{'totals'}->{$dr},
				settings => $tally->{$app}->{'settings'}
			});
			$tally->{$app}->{'budget'}->{$dr} = $budget if $budget->{'eval'};
		}
	}
	if ($display eq 'budgets') {
		$settings->{'budget_displays'} = eval { return decode_json $settings->{'budget_displays'} } || {};
	}
	elsif ($display eq 'statement') {
		$settings->{'statement_displays'} = eval { return decode_json $settings->{'statement_displays'} } || {};
	}
	elsif ($display eq 'daily_sheet') {
		$settings->{'daily_sheet_displays'} = eval { return decode_json $settings->{'daily_sheet_displays'} } || {};
	}
	my $data = {
		timestamp => $timestamp,
		accounts => $acc,
		categories => $categories,
		all_accounts => $all_accounts,
		account => $account,
		tally => $tally,
		transactions => $transactions,
		documents => $documents,
		budgets => $budgets,
		all_projects => $all_projects,
		projects => $projects,
		project => $project,
		totals => $totals,
		template => 'budget',
		time_machine => $time_machine,
		scope => $scope,
		movement => $movement,
		timeshift => $timeshift,
		display => $display,
		start => $bt,
		end => $t2,
		total_duration => $total_duration,
		settings => $settings,
		all_columns => $all_columns,
		columns => $columns,
		dollas => \@dollas,
		time_scopes => \@time_scopes,
		time_lengths => \@time_lengths
	};


	my $content = $c->render_to_string(%{$data});
	my $contents = &window_maker({ user_agent => $c->param('user_agent'), app => 'budget', title => 'Budget', contents => $content },$timestamp);
	$data->{'html'} = $contents;
	$c->render(json => $data);
};

post '/manager/budget/edit' => sub($c) {
	my $app = $c->param('app');
	my $timestamp = $c->param('timestamp');
	my $circumstance = $c->param('circumstance');
	my $value = $c->param('value');
	my $previous = $c->param('previous');
	my $existing_budgets;
	&subs::cache_delete({ app => $app, context => 'autocalc' });
	if (defined $previous && length $previous) {
		# The entry this edit replaces is named exactly, so the app's other entries
		# are left alone and a recommendation keeps its own scope and measure. An
		# empty value removes it.
		my @entries = grep { length } split ',', (&subs::setting_grabber({ app => $app, setting => 'budget' }) || '');
		@entries = grep { $_ ne $previous } @entries;
		push @entries, $value if defined $value && length $value;
		$existing_budgets = join ',', @entries;
	}
	else {
		$existing_budgets = $value;
		foreach my $br ( keys %{$gb::budget_modes} ) {
			my $budget = &budget_calculator({
				app => $app,
				circumstance => $br,
				value => 1,
				scope => 'hour',
				budget => &subs::setting_grabber({ app => $app, setting => 'budget' })
			});

			if ($budget->{'circumstance'} && $budget->{'circumstance'} ne $circumstance) {
				if ($existing_budgets) {
					$existing_budgets = $existing_budgets . ',' . $budget->{'budget'};
				}
				else {
					$existing_budgets = $budget->{'budget'};
				}
			}

		}
	}
	# A letter-bearing budget (a measure like "8681.139steps/d", or a quantity like
	# "3.4quantity/week") is claimed by more than one mode as they are all re-read -
	# the duration pass takes any letters - so the same string can be appended twice;
	# keep it once.
	my %seen_budget;
	$existing_budgets = join ',', grep { !$seen_budget{$_}++ } split ',', ($existing_budgets // '');
	&subs::setting_setter({ app => $app, setting => 'budget', value => $existing_budgets });
	$c->render(json => { existing_budgets => $existing_budgets, new_budget => $value });
};

post '/manager/budget/display/save' => sub($c) {
	my $name = &subs::unformat_name($c->param('name'));
	my $timestamp = $c->param('timestamp');
	my $data = eval { return decode_json $c->param('data') } || [];
	my $type = $c->param('type') || 'statement';

	if (scalar @{$data} == 0) {
		$c->render(json => {});
	}
	my $settings = &subs::settings_grabber({ app => 'budget' });

	my $display_settings = { start_time => $settings->{'start_time'}, end_time => $settings->{'end_time'} };
	foreach my $s ( keys %{$settings} ) {
		if (my @ds = grep { $_ eq $s } @{$data}) {
			$display_settings->{$s} = $settings->{$s};
		}
	}
	my $returner = { data => $data, config => $display_settings };

	my $cd = eval { return decode_json $settings->{$type . '_displays'} } || {};
	$cd->{$name} = $display_settings;
	my $jcd = encode_json $cd;
	&subs::setting_setter({ app => 'budget', setting => $type . '_displays', value => $jcd });


	$c->render(json => $returner);
};

post '/manager/budget/display/delete' => sub($c) {
	my $name = &subs::unformat_name($c->param('name'));
	my $display = $c->param('display');
	my $sd = eval { return decode_json &subs::setting_grabber({ app => 'budget', setting => $display . '_displays' }) } || {};
	if ($sd->{$name}) {
		$sd->{$name} = undef;
	}
	my $jsd = encode_json $sd;
	&subs::setting_setter({ app => 'budget', setting => $display . '_displays', value => $jsd });
	$c->render(json => $sd);
};


get '/manager/budget/current_information' => sub($c) {
	my $app = $c->param('app');
	my $timestamp = $c->param('timestamp');
	my $circumstance = $c->param('circumstance');

	my $ci = &budget_current_information($app,$circumstance,$timestamp);

	$c->render(text => $ci->{'template'});
};

# A circumstance's own reading, written the way the budget panel shows it: a base
# mode (occurences, duration, total, quantity) wears that mode's formatter, and a
# measure wears its own name, the way the autocalc writes one ("8681.139steps").
# The lookup is guarded on purpose: a bare chained deref of an absent measure
# would autovivify the key in %{$gb::budget_modes}, and then every later
# budget_calculator in this process would take the measure for a base mode and
# skip reading it (its budget value came back undef).
sub budget_value_formatter {
	my ($circumstance, $value) = @_;
	my $mode = $gb::budget_modes->{$circumstance};
	if ($mode && $mode->{'formatted'}) {
		my $formatted = eval { &{$mode->{'formatted'}}($value) };
		return $formatted if defined $formatted;
	}
	return sprintf("%.3f", $value) . $circumstance;
}

sub budget_current_information($app,$circumstance,$timestamp) {

	my $autocalc = &subs::cache_get({ app => $app, context => 'autocalc', subcontext => $circumstance });
	my $budget = &subs::cache_get({ app => $app, context => 'budget', subcontext => $circumstance });
	unless ($autocalc->{$budget}) {
		$autocalc = &Manager::budget_autocalc({
			app => $app,
			circumstance => $circumstance,
		});
	}

	# Both comparisons are read for the same share of the period, so an hour or a
	# day only part done is not held against the whole of its budget and its whole
	# typical. A completed (or rolling) window has share 1 and reads as before.
	my $share = (defined $budget->{'elapsed'} && $budget->{'elapsed'} >= 0 && $budget->{'elapsed'} < 1) ? $budget->{'elapsed'} : 1;
	my $typical = $autocalc->{$budget->{'scope_name'}}->{'result'} || 0;
	my $budget_share = ($budget->{'budgeted'} || 0) * $share;
	my $typical_share = $typical * $share;
	my $value = $budget->{'value'} || 0;
	my $ov = sprintf("%.5f", $typical_share - $budget_share);
	my $improvement = {
		share => $share,
		difference => $value - $budget_share,
		overall => &budget_value_formatter($circumstance, $ov),
		formatted_difference => &budget_value_formatter($circumstance, $value - $budget_share),
		percentage => eval { return &subs::percent_formatter(($value - $budget_share) / $typical_share) } || 0,
		overall_percentage => eval { return &subs::percent_formatter(($typical_share - $budget_share) / $typical_share) } || 0
	};
	my $goal = &goal_reading($app, $circumstance);
	my $c = &subs::controller_builder();
	my $template = $c->render_to_string(
		template => 'apps/budget_current_information',
		circumstance => $circumstance,
		improvement => $improvement,
		budget => $budget,
		autocalc => $autocalc,
		goal => $goal
	);
	return { template => $template, circumstance => $circumstance, improvement => $improvement, autocalc => $autocalc, budget => $budget, goal => $goal };
}

sub budget_runner($app) {
	&subs::subprocessor(sub {
		my ($db) = &subs::database_grabber();
		my $scope;
		my $timestamp = &subs::rightNow();
		my $budgets = &subs::db_query('select distinct(app) as app,* from settings where app=? and setting = ? and device = ? and value is not null',$app,'budget', $device)->hashes;
		my $sb = eval { return decode_json &subs::setting_grabber({ app => $app, setting => 'special_budgets' }) } || [];
		my $am = eval { return decode_json &subs::setting_grabber({ app => $app, setting => 'app_measures' }) } || {};
		# the base readings, any special budgets, and the app's measures: a measure
		# budget (19869steps/week, 175weight/month) is a budget like any other and
		# gets its light the same way
		my @budget_modes = ( @{$sb}, keys %{$gb::budget_modes}, keys %{$am} );
		foreach my $b ( @{$budgets} ) {
			my $app = $b->{'app'};
			my @buds = split /,/, $b->{'value'};
			foreach my $circumstance ( @budget_modes ) {
				my $cache_budget = &subs::cache_get({ app => $app, context => 'budget', subcontext => $circumstance });
				if ($cache_budget->{'scope'}) {
					$scope = $cache_budget->{'scope'};
				}
				foreach my $bud ( @buds ) {
					my @bt = split '/', $bud;
					$scope = $bt[-1];

					my $budget = &Manager::budget_calculator({
						app => $app,
						circumstance => $circumstance,
						scope => $scope,
						budget => $bud
					});
					if ($budget->{'is_scope'} && $circumstance eq $budget->{'circumstance'}) {
						&subs::cache_set({ app => $app, context => 'budget', subcontext => $circumstance }, $budget);
						my $msg = {
							app => $app,
							type => 'budget',
							budget => {
								colour => $budget->{'colour'},
								circumstance => $budget->{'circumstance'},
							}
						};
						&Websocket::send('tab', $msg);
						my $ci = &budget_current_information($app,$circumstance,$timestamp);
						&Websocket::send('tab', {
							type => 'html',
							content => $ci->{'template'},
							selector => '.budget_current_information[app="' . $app .'"][circumstance="' . $circumstance . '"]'
						});

					}
				}
			}
		}
		&centre_view_grabber({ app => &subs::unformat_name($app), timestamp => &subs::rightNow(), cached => 'no' });

	}, { name => 'budget runner' });
}


# The calc a measure reads with: its own remembered one (steps sum, weight
# average), else the app's s_calc as the fallback. Used wherever a measure's
# value is taken - the budget runner, the panel - so a steps budget and a weight
# budget read right at the same time, whatever the display is showing.
sub measure_calc_for {
	my ($app, $measure, $fallback) = @_;
	my $calc = &subs::setting_grabber({ app => $app, setting => 'measure_calc', subsetting => $measure });
	$calc = $fallback unless (defined $calc && length $calc);
	return (defined $calc && length $calc) ? $calc : 'sum';
}


# One budget/goal entry read apart: a leading "<=" or ">=" says which way it
# runs (under is good, or over is good), the number is the target, the name that
# follows is the measure ($ for money, absent for occurences), and "/<scope>"
# makes it a rate rather than a fixed level.
sub budget_entry_parse {
	my $entry = shift;
	my $direction = 'floor';
	my $e = $entry;
	if ($e =~ s/^<=//) { $direction = 'ceiling'; }
	elsif ($e =~ s/^>=//) { $direction = 'floor'; }
	my ($body, $scope) = split '/', $e, 2;
	my ($value, $measure);
	if ($body =~ /^\$(.*)$/) { $measure = '$'; $value = $1; }
	elsif ($body =~ /^([0-9.\-]+)([a-zA-Z_]*)$/) { $value = $1; $measure = $2; }
	else { $value = $body; $measure = ''; }
	return { raw => $entry, direction => $direction, value => $value, measure => $measure, scope => $scope, fixed => (defined $scope ? 0 : 1) };
}

# The measure's own trend: a least-squares line through its readings, as
# value-per-day, with the latest reading and the reading count. The stretch it
# reads is the floor given unless the measure is recorded more sparsely than
# that: the window is widened to about a dozen readings when the median gap
# between them is longer than the floor of a dozen dozen, so a level recorded
# once a month or once a year is not judged on the few points a fixed 90 days
# would hold. Times are measured from the first reading so the huge millisecond
# stamps do not cancel the fit.
sub measure_trend($app, $measure, $floor_days) {
	my $floor = ($floor_days || 90) * 86400000;
	my $appts = &subs::db_query('select timestamp,measures from appointments where app = ? and measures is not null order by timestamp desc limit 600', $app)->hashes;
	my @pts;
	foreach my $a ( @{$appts} ) {
		my $ms = eval { return decode_json $a->{'measures'} } || [];
		foreach my $m ( @{$ms} ) {
			next unless defined $m->{$measure} && $m->{$measure} =~ /[0-9]/;
			push @pts, [ ($a->{'timestamp'} + 0), ($m->{$measure} + 0) ];
		}
	}
	@pts = sort { $a->[0] <=> $b->[0] } @pts;
	return (undef, undef, scalar @pts) if scalar @pts < 2;
	# how often it is recorded: the median gap over the recent readings
	my @gaps;
	for (my $i = $#pts; $i > 0 && scalar @gaps < 50; $i--) {
		my $g = $pts[$i][0] - $pts[$i-1][0];
		push @gaps, $g if $g > 0;
	}
	my $window = $floor;
	if (scalar @gaps) {
		my @sorted = sort { $a <=> $b } @gaps;
		my $gap = $sorted[int($#sorted / 2)];
		my $span = $gap * 12;
		$window = $span if $span > $window;
	}
	# fit the readings the window reaches back over, so a sparsely kept level is
	# read over the long stretch it needs and a dense one stays on its recent pace
	my $cut = $pts[-1][0] - $window;
	my @fit = grep { $_->[0] >= $cut } @pts;
	@fit = @pts if scalar @fit < 2;
	my $t0 = $fit[0][0];
	my ($n, $sx, $sy, $sxx, $sxy) = (0, 0, 0, 0, 0);
	foreach my $p ( @fit ) {
		my $x = $p->[0] - $t0;
		$n++; $sx += $x; $sy += $p->[1]; $sxx += $x * $x; $sxy += $x * $p->[1];
	}
	my $denom = $n * $sxx - $sx * $sx;
	return (undef, $fit[-1][1], scalar @pts) if $denom == 0;
	my $slope = ($n * $sxy - $sx * $sy) / $denom;
	return ($slope * 86400000, $fit[-1][1], scalar @pts);
}

# A goal read for one circumstance: the target, where the measure stands now, and
# - the part a budget cannot give a scopeless entry - when the current trend
# carries it to the goal. A trend moving the wrong way has no date.
sub goal_reading($app, $circumstance) {
	my $raw = &subs::setting_grabber({ app => $app, setting => 'goals' });
	return undef unless ($raw || '') =~ /\S/;
	my $entry;
	foreach my $e ( split ',', $raw ) {
		my $p = &budget_entry_parse($e);
		if ($p->{'measure'} eq $circumstance) { $entry = $e; last; }
	}
	return undef unless defined $entry;
	my $reading = &budget_calculator({ app => $app, circumstance => $circumstance, budget => $entry });
	my $target = $reading->{'budgeted'};
	my $current = $reading->{'value'};
	my $dir = $reading->{'direction'} || 'floor';
	my ($slope, $last, $samples) = &measure_trend($app, $circumstance, 90);
	my ($eta_days, $reached);
	# a scoped goal is a rate and already has a period pace; the date-to-goal is
	# what a fixed (scopeless) level is missing
	if ($reading->{'fixed'} && defined $target) {
		my $need = ($dir eq 'ceiling') ? ($current - $target) : ($target - $current);
		if ($need <= 0) { $reached = 1; $eta_days = 0; }
		elsif ($slope) {
			my $toward = ($dir eq 'ceiling') ? -$slope : $slope;
			$eta_days = ($toward > 0) ? ($need / $toward) : undef;
		}
	}
	my $eta_text;
	if ($reached) { $eta_text = 'reached'; }
	elsif (defined $eta_days) { $eta_text = localtime((&subs::rightNow() + $eta_days * 86400000) / 1000)->strftime('%b %d, %Y at %l:%M%P'); $eta_text =~ s/\s+/ /g; }
	return {
		entry => $entry,
		direction => $dir,
		target => $target,
		current => $current,
		slope => $slope,
		samples => ($samples || 0),
		eta_days => $eta_days,
		eta_text => $eta_text,
	};
}


sub budget_calculator($data) {
	my $app = $data->{'app'};

	my $circumstance = $data->{'circumstance'};
	# A measure is any circumstance that is not one of the base budget modes,
	# worked out once with a key test that never autovivifies a measure into the
	# modes (which would make this very test, and later ones, read it wrong).
	my $is_measure = ( scalar grep { $_ eq $circumstance } keys %{$gb::budget_modes} ) == 0;
	my $value = $data->{'value'};
	my $scope = $data->{'scope'};
	# the window the reading is for: the caller says when it is one of the blocks
	# before or after now, so a pace is only read off the one now running
	my $ts = $data->{'ts'} || 'this';
	my $settings = $data->{'settings'} || &subs::settings_grabber({ app => $app });
	my $timestamp = $data->{'timestamp'} || &subs::rightNow();
	my $returner = { app => $app, scope_name => &subs::timespan_widener($scope), value => $value };
	my $budget = $data->{'budget'};
	my $server_time = &subs::rightNow();
	$budget = $data->{'budget'} || &subs::setting_grabber({ 'app' => $app, setting => 'budget' }) unless $data->{'budget'} =~ /[0-9]/gi;
	my @budgets = split ',', $budget;
	foreach my $b ( @budgets ) {
		$returner->{'app'} = $app;
		$returner->{'budget'} = $b;
		# A leading "<=" or ">=" says which way the goal runs: under is good (a
		# ceiling, like a weight to hold at or below) or over is good (a floor, like
		# steps to reach). Nothing, and a bare number, is a floor.
		my $direction = 'floor';
		if ($b =~ s/^<=//) { $direction = 'ceiling'; }
		elsif ($b =~ s/^>=//) { $direction = 'floor'; }
		$returner->{'direction'} = $direction;
		my @bud = split '/', $b;
		next unless $bud[-1];
		# No "/scope" is a fixed level, not a rate: a weight sits at a target, it
		# does not accumulate, so it is read against the column's own window and is
		# never prorated (the pace is what made a 160 lb budget project 756 lb).
		my $fixed = scalar(@bud) == 1 ? 1 : 0;
		$returner->{'fixed'} = $fixed;
		if ($fixed) {
			# A fixed entry ("180weight") has no "/scope"; the only scope it can
			# honour is the caller's, and only when it names a time span. The old
			# test accepted any number+letters, so `180weight` became the window
			# `weight`; timespan_widener then stripped the digits and father_time
			# asked time_span for 'weight', which dies and killed every pull after
			# its merge.
			my $window = 'month';
			if ($scope && $scope =~ /^[0-9]*[a-zA-Z]+$/ && &subs::time_span_length($scope)) {
				$window = $scope;
			}
			$window = 1 . $window unless $window =~ /^[0-9]/;
			$returner->{'scope_name'} = &subs::timespan_widener($window);
			$returner->{'duration'} = &subs::time_abbrev_translator($window, $server_time);
			$returner->{'scope'} = $returner->{'duration'};
		}
		else {
			$bud[-1] = 1 . $bud[-1] unless $bud[-1] =~ /[0-9]/;
			# A malformed scope after the slash must not reach time_span either.
			$bud[-1] = '1month' unless &subs::time_span_length($bud[-1]);
			$returner->{'scope_name'} = &subs::timespan_widener($bud[-1]);
			$returner->{'duration'} = &subs::time_abbrev_translator($bud[-1],&subs::rightNow());
			unless ($scope) {
				$returner->{'scope'} = $returner->{'duration'} ;
			}
			else {
				$returner->{'scope'} = &subs::time_abbrev_translator($bud[-1]);
				$returner->{'duration'} = $returner->{'scope'} unless $value;
			}
		}
		# A fixed quantity budget is a level to keep on hand, not a rate of the
		# appointment stream (the scoped form reads that stream): read the warehouse's
		# signed stock for the item, so its light says whether the shelf holds what it
		# should.
		my $handled;
		if ($circumstance eq 'quantity' && $fixed) {
			$value = &subs::warehouse_on_hand($app, $settings);
			$returner->{'value'} = $value;
			$handled = 1;
		}
		unless ($value || $handled) {
			my ($db) = &subs::database_grabber();
			my $appts = $data->{'appts'};
			unless ($data->{'appts'}) {
				my $ft_data = {
					scope => $returner->{'scope_name'},
					ts => 'this',
					lock => $settings->{'s_lock'},
					timestamp => $timestamp
				};
				my ($bt, $temp_timestamp) = &father_time($ft_data);

				my @params = ( $app, $temp_timestamp, $bt );
				my $query = 'select * from appointments where app = ? and timestamp < ? and timestamp >= ? ';

				if ($settings->{'s_movement'}) {
					my $bail = 0;
					unless ($settings->{'sss_movement'}) {
						$settings->{'sss_movement'} = eval { return decode_json $settings->{'s_movement'} } || [];
					}
					$bail = 1 if grep { $_ eq 'all' } @{$settings->{'sss_movement'}};
					if ($bail == 0) {
						if (scalar @{$settings->{'sss_movement'}} > 0 ) { $query .= 'and ( '; }
						foreach my $sm ( @{$settings->{'sss_movement'}} ) {
							$query .= 'type = ? ' if scalar @params == 3;
							$query .= ' or type = ? ' if scalar @params > 3;
							push @params, $sm;
						}
						if (scalar @{$settings->{'sss_movement'}} > 0 ) { $query .= ' ) '; }
					}
				}
				$query .= ' order by timestamp DESC';
				$appts = &subs::db_query($query, @params)->hashes;
				$data->{'appts'} = $appts;
			}

			my ($m_sum, $m_count) = (0, 0);
			foreach my $appt ( @{$appts} ) {
				if ($circumstance eq 'duration') {
					if ($appt->{'type'} eq 'start' || $appt->{'type'} eq 'record') {
						$appt->{'duration'} = $server_time - $appt->{'timestamp'};
					}
					$value += abs $appt->{'duration'};
				}
				elsif ($circumstance eq 'occurences') {
					$value += 1;
				}
				elsif ($circumstance eq 'total') {
					$value += (abs $appt->{'total'} || 0) if $value;
				}
				elsif ($circumstance eq 'quantity') {
					# the stream the app's movement filter names - beer's poured amount,
					# not its purchases - read as a magnitude, the way a total budget
					# reads the money
					$value += abs( $appt->{'quantity'} || 0 );
				}
				else {
					# a measure: sum, or average, it across the window's appointments -
					# the measure decides (steps summed, weight averaged), so its
					# budget reads right whatever the display is showing.
					next unless $appt->{'measures'};
					unless ($appt->{'measured'}) {
						$appt->{'measures'} = eval { return decode_json $appt->{'measures'} } || [];
						$appt->{'measured'} = 'yes';
					}
					foreach my $m ( @{$appt->{'measures'}} ) {
						next unless defined $m->{$circumstance};
						$m_sum += $m->{$circumstance};
						$m_count++;
					}
				}
			}
			# a measure is not a base mode: its value is the summed or averaged
			# measure, per the measure's own calc
			if ($is_measure) {
				# a fixed level (no scope) is a level, so it reads as an average whatever
				# the measure's own calc is; a rate reads with the measure's calc
				my $mcalc = $fixed ? 'average' : &measure_calc_for($app, $circumstance, $settings->{'s_calc'});
				$value = ( $mcalc eq 'average' && $m_count ) ? ($m_sum / $m_count) : $m_sum;
			}
			$value = 0 if scalar @{$appts} == 0;
			$returner->{'value'} = $value;
		}
		if ($bud[0] =~ /^\$/gi) {
			my $bu = $bud[0];
			$bu =~ s/\$//gi;
			$returner->{'budgets'}->{'total'} = $b;
			if ($circumstance eq 'total') {
				$returner->{'circumstance'} = 'total';
				$returner->{'budgeted'} = abs $bu;
				$returner->{'formatted_value'} = abs $value;
				last;
			}
		}
		elsif ($bud[0] =~ /[a-zA-Z]/gi) {

			if ($circumstance eq 'duration') {
				$returner->{'budgets'}->{'duration'} = $b;
				$returner->{'circumstance'} = 'duration';
				$bud[0] = 1 . $bud[0] unless $bud[0] =~ /[0-9]/;
				$returner->{'budgeted'} = &subs::time_abbrev_translator($bud[0],&subs::rightNow());
				if ($value != 0) {
					$returner->{'formatted_value'} = &subs::duration_sayer($value / 1000);
				}
				else {
					$returner->{'formatted_value'} = 0;
				}
				last;
			}
			elsif ($is_measure) {
				$returner->{'budget_name'} = $bud[0];
				$returner->{'budget_name'} =~ s/[0-9.]//gi;
				next unless $returner->{'budget_name'} eq $circumstance;
				$returner->{'budgeted'} = $bud[0];
				$returner->{'budgets'}->{$circumstance} = $b;
				$returner->{'circumstance'} = $circumstance;

				$returner->{'budgeted'} =~ s/[^0-9.]//gi;
				$returner->{'formatted_value'} = sprintf("%.3f", $value) . $circumstance;
				last;
			}
			elsif ($circumstance eq 'quantity') {
				# a quantity budget names itself the way a measure does
				# ("3.400quantity/week"), so a bare number stays an occurences budget
				my $quantity_name = $bud[0];
				$quantity_name =~ s/[^a-zA-Z]//gi;
				next unless $quantity_name eq 'quantity';
				$returner->{'budgets'}->{'quantity'} = $b;
				$returner->{'circumstance'} = 'quantity';
				$returner->{'budgeted'} = $bud[0];
				$returner->{'budgeted'} =~ s/[^0-9.]//gi;
				$returner->{'formatted_value'} = sprintf("%.3f", $value) . $circumstance;
				last;
			}
		}
		else {
			$returner->{'budgets'}->{'occurences'} = $b;

			if ($circumstance eq 'occurences') {
				$returner->{'circumstance'} = 'occurences';
				$returner->{'budgeted'} = $bud[0];
				$returner->{'formatted_value'} = abs $value;
				last;
			}
		}
	}

	if ($returner->{'budget'} && $returner->{'budgeted'}) {
		if ($returner->{'duration'} eq $returner->{'scope'} && $returner->{'circumstance'} eq $circumstance) {
			$returner->{'is_scope'} = 'yes';
		}

		$returner->{'expected'} = sprintf("%.19f",$returner->{'budgeted'} / $returner->{'duration'});
		$returner->{'formatted_budgeted'} = sprintf("%.3f", $returner->{'expected'} * $returner->{'scope'}) . ($is_measure ? $circumstance : '') . '/' . $returner->{'scope_name'};
		$returner->{'formatted_budgeted'} = &subs::duration_sayer($returner->{'expected'} * $returner->{'duration'} / 1000) . '/' . $returner->{'scope_name'} if $circumstance eq 'duration';
		$returner->{'actual'} = sprintf("%.19f", $returner->{'value'} / $returner->{'scope'});
		$returner->{'threshold'} = $returner->{'expected'} * $returner->{'scope'};
		$returner->{'eval'} = $returner->{'actual'} - $returner->{'expected'};
		$returner->{'timestamp'} = $timestamp;
		if (!$returner->{'fixed'} && $scope ne $returner->{'scope_name'} && $returner->{'circumstance'} eq $circumstance) {
			$returner->{'is_scope'} = 'no';
			my $scoped = $returner->{'scope'} / &subs::time_abbrev_translator(1 . $scope ,&subs::rightNow());
			$returner->{'expected'} = $returner->{'expected'} * $scoped;
			$returner->{'actual'} = $returner->{'actual'} * $scoped;
			$returner->{'expected'} = sprintf("%.19f",$returner->{'budgeted'} / ( $returner->{'duration'} * $scoped));
			$returner->{'actual'} = sprintf("%.19f", ($returner->{'value'} * $scoped) / ($returner->{'scope'} * $scoped));
		}
		# A budget locked to the calendar is read against a period still running:
		# on Monday a week holds a seventh of its value, so holding that part against
		# the whole week's target would call an on-pace start a collapse and leave
		# nothing meaningful to read until the week is done. The pace is read
		# instead - the part of the period the moment stands at - and the target is
		# prorated by that same part, so being on track means the value has reached
		# its share of the period so far, and the projection carries the pace to the
		# period's end. An unlocked window rolls a whole period back from now, so it
		# is already run and its pace is 1, as is any block before or after now.
		# Every column is read this way, not only the one the budget is set to: a
		# weekly budget graphed over the month is still a part-run month, and its
		# column reads the same way (the target was scaled to the column above).
		#
		# The first stretch of a period carries no target, since so little is due that
		# a single blip reads as far ahead of pace, and that stretch is often spent
		# asleep or otherwise away from it. The budget is spread over what is left: a
		# day's first two fifths are the night (so its target only starts around nine
		# in the morning), an hour's first quarter, and the longer clocks their first
		# tenth. The projection keeps the exact elapsed, so it still reads the whole
		# period rather than only the part not slept through.
		my %pace_floor = ( hour => 0.25, day => 0.4, week => 0.1, month => 0.1, year => 0.1 );
		my $unit = $scope ? &subs::timespan_widener($scope) : $returner->{'scope_name'};
		my $elapsed = 1;
		if ($ts eq 'this' && ($settings->{'s_lock'} || '') eq 'on' && $unit =~ /^(?:hour|day|week|month|year)$/) {
			(undef, undef, $elapsed) = &subs::period_bounds($unit, $timestamp);
		}
		# a fixed level is not a period being run: it is not prorated, and its pace
		# is not carried anywhere
		$elapsed = 1 if $returner->{'fixed'};
		my $floor = $pace_floor{$unit} // 0.1;
		my $early = ($elapsed > 0 && $elapsed <= $floor) ? 1 : 0;
		my $pace_elapsed = $early ? 0 : (($elapsed - $floor) / (1 - $floor));
		$pace_elapsed = 0 if $pace_elapsed < 0;
		$pace_elapsed = 1 if $pace_elapsed > 1;
		# the whole target the column's value is held against - already scaled to the
		# column's own period when the budget is set to a different one
		my $full_target = $returner->{'expected'} * $returner->{'scope'};
		$returner->{'elapsed'} = $elapsed;
		$returner->{'early'} = $early;
		$returner->{'pace_floor'} = $floor;
		$returner->{'progress'} = sprintf('%.0f', $elapsed * 100);
		$returner->{'on_target'} = sprintf('%.19f', $full_target * $pace_elapsed);
		$returner->{'on_track'} = ($returner->{'value'} >= $returner->{'on_target'}) ? 'yes' : 'no';
		$returner->{'projected'} = $elapsed > 0 ? sprintf('%.19f', $returner->{'value'} / $elapsed) : $returner->{'value'};
		my $pace_format = sub {
			my $n = shift;
			return '-' unless defined $n;
			return &subs::duration_sayer($n / 1000) if $circumstance eq 'duration';
			return &subs::price_formatter($n) if $circumstance eq 'total';
			return sprintf('%.1f', $n);
		};
		$returner->{'formatted_projected'} = $pace_format->($returner->{'projected'});
		$returner->{'formatted_on_target'} = $early ? '0' : $pace_format->($returner->{'on_target'});
		# The status and the graph line are held against the share of the target due
		# by now, not the whole of it, so an on-pace start reads as on pace rather
		# than a collapse; formatted_budgeted still names the whole period.
		$returner->{'full_expected'} = $returner->{'expected'};
		$returner->{'threshold'} = $full_target * $pace_elapsed;
		if ($early) {
			$returner->{'expected'} = 0;
		}
		elsif ($elapsed > 0 && $elapsed < 1 && $returner->{'expected'} > 0) {
			$returner->{'expected'} = sprintf('%.19f', $returner->{'expected'} * $pace_elapsed);
		}
		$returner->{'eval'} = $returner->{'actual'} - $returner->{'expected'};
		$returner = &budget_status_maker($returner);
		# A ceiling reads the mirror of the floor the status table is written for:
		# at or under the target is settled, over it is the alarm. Re-read the status
		# from the value against the target, not from the ratio.
		if (($returner->{'direction'} || 'floor') eq 'ceiling') {
			my $target = $returner->{'budgeted'} || 0;
			my $value = $returner->{'value'} || 0;
			# a hair of float noise either side of the target is still the target
			my $epsilon = $target * .0000000001;
			$returner->{'on_track'} = ($value <= $target + $epsilon) ? 'yes' : 'no';
			my $ceiling = 'budgeted';
			if ($target > 0 && $value > $target * 1.2) { $ceiling = 'overkill'; }
			elsif ($target > 0 && $value > $target + $epsilon) { $ceiling = 'burnt_out'; }
			# landing exactly on the target spends the whole allowance without
			# passing it - an accomplishment, not merely within budget
			elsif ($target > 0 && $value >= $target - $epsilon) { $ceiling = 'accomplished'; }
			$returner = &{$gb::budget_statuses->{$ceiling}->{'notifier'}}($returner);
		}
	}
	else {
	#	$returner = {};
	}
	return $returner;
}


sub budget_status_maker($returner) {
	# a target of nothing - a period only just opened, or a budget of zero - has
	# nothing to fall behind: the value is read as on track, rather than the
	# ratio's 0 >= 0 landing on "overkill"
	if (!defined $returner->{'expected'} || $returner->{'expected'} <= 0) {
		return &{$gb::budget_statuses->{'budgeted'}->{'notifier'}}($returner);
	}
	my $status;
	if ($returner->{'actual'} < $returner->{'expected'} - ( $returner->{'expected'} * .0000000001) && $returner->{'actual'} >= $returner->{'expected'} - ($returner->{'expected'} * .2)) {
		$status = 'budgeted';
		$returner->{'synth'} = 'play -v .3 "| sox -n -p synth .51 sine 391 && play | sox -n -p synth .51 triangle 500"';
	}
	elsif ($returner->{'actual'} >= $returner->{'expected'} * 2) {
		$status = 'overkill';
		$returner->{'synth'} = 'play -v .15 "| sox -n -p synth .51 pinknoise 1125 && play | sox -n -p synth .51 whitenoise 100"';
	}
	elsif ($returner->{'actual'} >= $returner->{'expected'} * 1.2) {
		$status = 'burnt_out';
		$returner->{'synth'} = 'play -v .15 "| sox -n -p synth .51 square 125 && play | sox -n -p synth .51 square 100"';
	}
	elsif ($returner->{'actual'} >= $returner->{'expected'}) {
		$status = 'accomplished';
		$returner->{'synth'} = 'play -v .15 "| sox -n -p synth .26 pluck 329.64 && play | sox -n -p synth .26 pluck 391.99 && play | sox -n -p synth .26 pluck 369.99 && play | sox -n -p synth .26 pluck 293.672"';
	}
	elsif ($returner->{'actual'} <= $returner->{'expected'} / 4) {
		$status = 'abandoned';
		$returner->{'synth'} = 'play -v .15 "| sox -n -p synth .51 triangle 261.64 && play | sox -n -p synth .51 triangle 261.64"';
	}
	elsif ($returner->{'actual'} <= $returner->{'expected'} / 2) {
		$status = 'neglected';
		$returner->{'synth'} = 'play -v .15 "| sox -n -p synth .26 saw 349.23 && play | sox -n -p synth .26 saw 329.63 && play | sox -n -p synth .26 saw 415.3 && play | sox -n -p synth .26 saw 439.99"';
	}
	elsif ($returner->{'actual'} <= $returner->{'expected'}) {
		$status = 'achievable';
		$returner->{'synth'} = 'play -v .15 "| sox -n -p synth .26 pluck 293.67 && play | sox -n -p synth .26 pluck 349.23 && play | sox -n -p synth .26 pluck 349.23 && play | sox -n -p synth .26 pluck 311.13"';
	}
	$returner = &{$gb::budget_statuses->{$status}->{'notifier'}}($returner);

	return $returner;
}

get '/manager/budget/autocalc' => sub($c) {
	my $app = $c->param('app');
	my $timestamp = $c->param('timestamp');
	my $circumstance = $c->param('circumstance');
	&subs::cache_delete({ app => $app, context => 'autocalc', subcontext => $circumstance });
	&subs::cache_delete({ app => $app, context => 'budget', subcontext => $circumstance });
	my $returner = &budget_autocalc({
		app => $app,
		circumstance => $circumstance,
	});
	$c->render(json => $returner );
};

sub budget_autocalc($data) {
	my $app = $data->{'app'};
	my $scope = $data->{'scope'};
	my $circumstance = $data->{'circumstance'};
	my $timestamp = $data->{'timestamp'};
	my $server_time = &subs::rightNow();
	if (my $cache = &subs::cache_get({ app => $app, context => 'autocalc', subcontext => $circumstance })) {
		return $cache;
	}
	my $returner = {
		minute => { symbol => 'm' },
		hour => { symbol => 'h' },
		day => { symbol => 'd' },
		week => { symbol => 'w' },
		month => { symbol => 'M' },
		year => { symbol => 'y' },
	};
	my $settings = &subs::settings_grabber({ app => $app });
	# The six windows this reads, named once so 'data' (added below) is never
	# mistaken for one of them.
	my @windows = keys %{$returner};
	# A measure is any circumstance the base modes do not name (the same test
	# budget_calculator uses), so 'quantity' reads as the base mode it is; a measure
	# reads with its own calc (steps summed, weight averaged).
	my $is_measure = ( scalar grep { $_ eq $circumstance } keys %{$gb::budget_modes} ) == 0;
	my $mcalc = $is_measure ? &measure_calc_for($app, $circumstance, $settings->{'s_calc'}) : undef;
	# The whole history, not the last thousand: a window can reach a year back, and
	# the cap left the long scopes reading only the recent stretch. Read by
	# timestamp (app,timestamp is indexed) and only the columns the sum needs.
	my $cols = 'timestamp,type';
	$cols .= ',duration' if $circumstance eq 'duration';
	$cols .= ',total' if $circumstance eq 'total';
	$cols .= ',quantity' if $circumstance eq 'quantity';
	$cols .= ',measures' if $is_measure;
	my $appts = $data->{'appts'} || &subs::db_query("select $cols from appointments where app = ? order by timestamp ASC", $app)->hashes;
	if ($scope && $timestamp) {
		my $duration = &subs::time_abbrev_translator(1 . $scope, $server_time);
		my $beginning = $server_time - ( $duration * ($settings->{'s_scope_count'} || 1) );
		@{$appts} = grep { $_->{'timestamp'} > $beginning } @{$appts};
	}
	# The app's own movement filter names the stream a budget reads (beer's poured
	# amount, not its purchases), so the recommendation reads that same stream -
	# 'all', or no filter at all, keeps every appointment.
	my $movement = $settings->{'s_movement'} ? ( eval { return decode_json $settings->{'s_movement'} } || [] ) : [];
	if (scalar @{$movement} && !grep { $_ eq 'all' } @{$movement}) {
		my %wanted = map { $_ => 1 } @{$movement};
		@{$appts} = grep { $wanted{ $_->{'type'} || '' } } @{$appts};
	}

	# Sum the value each appointment offers the reading, and note the span it was
	# offered over: the typical amount in a window is that sum spread over the span,
	# so a 'week' reading is what a week holds. An appointment that carries no such
	# measure offers a measure's reading nothing, and does not stretch its span.
	my $total = 0;
	my $samples = 0;
	my ($first, $last);
	foreach my $appt ( @{$appts} ) {
		my ($value, $count) = (0, 0);
		if ($circumstance eq 'occurences') {
			$value = 1;
		}
		elsif ($circumstance eq 'duration') {
			$value = abs( $appt->{'duration'} || 0 );
		}
		elsif ($circumstance eq 'total') {
			$value = $appt->{'total'} + 0;
		}
		elsif ($circumstance eq 'quantity') {
			$value = abs( $appt->{'quantity'} || 0 );
		}
		elsif ($is_measure) {
			next unless $appt->{'measures'};
			unless ($appt->{'measured'}) {
				$appt->{'measures'} = eval { return decode_json $appt->{'measures'} } || [];
				$appt->{'measured'} = 'yes';
			}
			foreach my $m ( @{$appt->{'measures'}} ) {
				next unless defined $m->{$circumstance};
				$value += $m->{$circumstance};
				$count++;
			}
			next unless $count;
		}
		$total += $value;
		$samples += $count;
		my $ts = $appt->{'timestamp'} + 0;
		$first = $ts if !defined $first || $ts < $first;
		$last = $ts if !defined $last || $ts > $last;
	}
	my $span = (defined $first && defined $last) ? ($last - $first) : 0;

	foreach my $r ( @windows ) {
		my $width = &subs::time_abbrev_translator(1 . $returner->{$r}->{'symbol'}, $server_time);
		$returner->{$r}->{'duration'} = $width;
		# The reading is the sum spread over the span, not the average of the
		# overlapping per-appointment windows the walk used to take. That average
		# read the short scopes far too high - a window centred on an appointment
		# is never empty, so the count could not fall below one a window - and the
		# long ones too low, since a window wider than the history can only hold
		# the whole of it. Spreading the sum holds all six scopes in step, which is
		# what a typical scope is.
		my $result;
		if ($is_measure && $mcalc eq 'average') {
			# an averaged measure is a level, not a rate: the reading is the mean of
			# its samples, so it stands the same at every window
			$result = $samples ? ($total / $samples) : 0;
		}
		elsif ($span > 0) {
			$result = $total * $width / $span;
		}
		else {
			# a lone reading (or none) has no span to rate against; it is its own
			# whole history
			$result = $total;
		}
		$returner->{$r}->{'result'} = $result;
		if ($circumstance eq 'occurences') {
			$returner->{$r}->{'formatted_result'} = sprintf("%.3f", $result) . '/' . $r;
		}
		elsif ($circumstance eq 'total') {
			$returner->{$r}->{'formatted_result'} = &subs::price_formatter( $result ) . '/' . $returner->{$r}->{'symbol'};
		}
		elsif ($circumstance eq 'duration') {
			$returner->{$r}->{'formatted_result'} = &subs::duration_sayer($result / 1000) . '/' . $r;
		}
		else {
			$returner->{$r}->{'formatted_result'} = sprintf("%.3f", $result) . $circumstance . '/' . $r;
		}
	}

	$returner->{'data'} = {};

	$returner->{'data'}->{'circumstance'} = $circumstance;
	$returner->{'data'}->{'app'} = $app;
	$returner->{'data'}->{'formatted_app'} = &subs::format_name($app);
	$returner->{'data'}->{'timestamp'} = &subs::rightNow();

	&subs::cache_set({app => $app, context => 'autocalc', subcontext => $circumstance }, $returner);
	return $returner;
}

get '/manager/notifications/list' => sub($c) {
	my $content = &notification_grabber({});
	my $contents = &window_maker({ user_agent => $c->param('user_agent'), app => 'notifications', title => 'Notifications', contents => $content },$c->param('timestamp'));
	$c->render(text => $contents);
};

get '/manager/notes' => sub($c) {
	# Every note, newest first: the plain rows subs::voice_note_store and the app's
	# own input write. Notes are no longer appointments - a note is just its text.
	my $notes = &subs::db_query('select text, timestamp, uuid from notes order by timestamp desc limit 300')->hashes;
	my $content = $c->render_to_string(
		template => 'notes/notes',
		notes => $notes
	);
	my $contents = &window_maker({ user_agent => $c->param('user_agent'), app => 'notes', title => 'Notes', contents => $content }, $c->param('timestamp'));
	$c->render(text => $contents);
};

get '/manager/camera' => sub($c) {
	# The Camera app: a panel whose buttons drive the app's own camera
	# (window.JawnCamera). In a browser there is no bridge, so the panel says so.
	my $content = $c->render_to_string(template => 'apps/camera');
	my $contents = &window_maker({ user_agent => $c->param('user_agent'), app => 'camera', title => 'Camera', contents => $content }, $c->param('timestamp'));
	$c->render(text => $contents);
};

get '/manager/phone' => sub($c) {
	# The Phone app: the house's numbers (known, and the numbers that are only
	# numbers), recent calls (the appointments whose subtype is 'phone'), the desk's
	# blocked numbers, and the dial pad. The pad places a call on a phone
	# (termux-telephony-call); the app's own address book and live call state ride
	# the native JawnContacts bridge.
	my $calls = &subs::db_query('select app,uuid,timestamp,type,duration,account from appointments where subtype=? order by timestamp desc limit 60', 'phone')->hashes;
	my $directory = &phone_directory();
	my $blocked = &phone_blocked();
	my %blocked_number = map { $_->{'number'} => 1 } @{$blocked};
	# a row says so itself when any of its lines is on the desk's list, and each
	# line carries its own reading (the number, its type, whether it is blocked) so
	# the template joins them without walking the tuples itself
	foreach my $r ( @{ $directory->{'known'} }, @{ $directory->{'numbers'} } ) {
		my $any = 0;
		foreach my $l ( @{ $r->{'numbers'} } ) {
			$l->{'blocked'} = $blocked_number{ &ticket_contact_clean('phone', $l->{'value'}) } ? 1 : 0;
			$l->{'display'} = &subs::contact_line_label($l);
			$any = 1 if $l->{'blocked'};
		}
		$r->{'blocked'} = $any;
	}
	my $content = $c->render_to_string(
		template => 'apps/phone',
		calls => $calls,
		known => $directory->{'known'},
		numbers => $directory->{'numbers'},
		blocked => $blocked,
	);
	my $contents = &window_maker({ user_agent => $c->param('user_agent'), app => 'phone', title => 'Phone', contents => $content }, $c->param('timestamp'));
	$c->render(text => $contents);
};

post '/manager/phone/dial' => sub($c) {
	my $number = $c->param('number') || '';
	$number =~ s/[^\d+#*]//g;
	unless ($number) { $c->render(json => { ok => 0, error => 'No number.' }); return; }
	if (&subs::device_setter() eq 'mobile') {
		my $out = `termux-telephony-call "$number" 2>&1`;
		# a machine with no telephony (a wifi tablet is a 'mobile' device here too)
		# answers this same route: report success only when the dial really went
		# out, so a caller can fall through to the next mobile peer.
		my $ok = ($out =~ /error|exception|unable|denied|not found|no service/i) ? 0 : 1;
		$c->render(json => { ok => $ok, number => $number, out => $out });
		return;
	}
	# Not a phone: hand the call to one through remote_machines, the way an SMS is
	# handed over, so the pad dials for real from the laptop. The phone's own copy
	# of this route is what knows to run the command.
	my $dialled;
	foreach my $rm ( @{ &subs::db_query('select * from remote_machines where connection=? and device=?', 'active', 'mobile')->hashes } ) {
		last if $dialled;
		my $ru = eval { &remote_useragent_maker({ ip => $rm->{'ip'}, signatorial => $rm->{'signatorial'}, rm => $rm }) };
		next unless $ru && $ru->{'ua'} && $ru->{'manager'};
		my $res = eval { $ru->{'ua'}->inactivity_timeout(20)->post($ru->{'manager'} . '/manager/phone/dial?number=' . $number) };
		my $body = eval { decode_json $res->body } || {};
		$dialled = $rm if $body->{'ok'};
	}
	if ($dialled) {
		$c->render(json => { ok => 1, number => $number, via => ($dialled->{'hostname'} || $dialled->{'name'} || $dialled->{'ip'}) });
		return;
	}
	$c->render(json => { ok => 0, error => 'No phone is reachable to dial from.' });
};

post '/manager/phone/call' => sub($c) {
	# The live half of the phone app: 'ring' starts the call's appointment (on the
	# caller's own app when the number is known - the Call screening role supplies
	# it at ring - else the fallback 'phone' app), 'end' stops it and 'miss'
	# cancels it. The house's own call-log poll skips what this wrote, so a live
	# call and its call-log trail are one appointment, not two.
	my $event = $c->param('event') || '';
	my $number = $c->param('number') || '';
	$number =~ s/[^\d+#*]//g;
	my $uuid = $c->param('uuid') || '';
	my $timestamp = &timestamp_adjuster($c);

	my $app = 'phone';
	if ($number) {
		# the caller's own app: their name when the house knows the number, else the
		# number's own app (phone_number_app makes it known), the way the call-log
		# check files an unknown caller - so a stranger's call is an app to rename
		# later rather than a drop on the floor
		$app = &subs::phone_number_app($number) || 'phone';
	}

	if ($event eq 'ring') {
		my $wrote = &appointment_writer($c, {
			app => $app,
			type => 'start',
			subtype => 'phone',
			timestamp => $timestamp,
			account => $number,
			data => encode_json({ direction => ($c->param('direction') || 'incoming'), number => $number }),
		});
		$c->render(json => { ok => 1, app => $app, uuid => $wrote->{'uuid'} });
		return;
	}

	if ($event eq 'ignore') {
		# a call the desk's blacklist turned away: it never rang, so there is no
		# ring to stop - the appointment is written and closed at once, as a
		# cancelled call on the caller's own app. Filing it here also tells the
		# call-log poll (which skips a phone appointment within minutes of a log
		# entry) that this call is already accounted for.
		my $wrote = &appointment_writer($c, {
			app => $app,
			type => 'start',
			subtype => 'phone',
			timestamp => $timestamp,
			account => $number,
			data => encode_json({ direction => 'incoming', number => $number, blocked => 'yes' }),
		});
		unless ($wrote && $wrote->{'uuid'}) {
			$c->render(json => { ok => 0, error => 'no appointment' });
			return;
		}
		&subs::db_update('appointments', {
			type => 'cancel',
			stop_seen => 'yes',
			stop_timestamp => $timestamp,
			server_time => &subs::rightNow(),
		}, { uuid => $wrote->{'uuid'} });
		$c->render(json => { ok => 1, app => $app, uuid => $wrote->{'uuid'} });
		return;
	}

	if ($event eq 'log') {
		# A whole call, filed from the app's own record of it. The dialer role's
		# service sees every call whatever else is running, so this is what makes a
		# call taken with no page up leave an appointment behind (it used to be
		# written only by the page, and a call with the app in the background left
		# nothing). The appointment opens at the ring and closes at the hangup, or
		# cancels when nobody ever answered - a call that went out and was not
		# picked up counts the same way.
		my $started = $c->param('started') || $timestamp;
		my $ended = $c->param('ended') || $started;
		my $answered = ($c->param('answered') || '') eq 'yes';
		my $direction = $c->param('direction') || 'incoming';
		my $wrote = &appointment_writer($c, {
			app => $app,
			type => 'start',
			subtype => 'phone',
			timestamp => $started,
			account => $number,
			data => encode_json({ direction => $direction, number => $number }),
		});
		unless ($wrote && $wrote->{'uuid'}) {
			$c->render(json => { ok => 0, error => 'no appointment' });
			return;
		}
		my %closing = ( stop_seen => 'yes', stop_timestamp => $ended, server_time => &subs::rightNow() );
		if ($answered) {
			$closing{'type'} = 'stop';
			$closing{'duration'} = $ended - $started;
		}
		else {
			$closing{'type'} = 'cancel';
		}
		&subs::db_update('appointments', \%closing, { uuid => $wrote->{'uuid'} });
		$c->render(json => { ok => 1, app => $app, uuid => $wrote->{'uuid'} });
		return;
	}

	if (($event eq 'end' || $event eq 'miss') && $uuid) {
		my $row = &subs::db_select('appointments', undef, { uuid => $uuid })->hashes->[0];
		if ($row && $row->{'app'}) {
			my $data = { stop_seen => 'yes', stop_timestamp => $timestamp, server_time => &subs::rightNow() };
			if ($event eq 'miss') {
				$data->{'type'} = 'cancel';
			}
			else {
				$data->{'type'} = 'stop';
				$data->{'duration'} = $timestamp - $row->{'timestamp'};
			}
			&subs::db_update('appointments', $data, { uuid => $uuid });
		}
		$c->render(json => { ok => 1, event => $event });
		return;
	}

	$c->render(json => { ok => 0, error => 'unknown event' });
};

get '/manager/phone/sync' => sub($c) {
	# What the app's native phone half needs, handed over in one fetch: the desk's
	# blacklist (the CallScreeningService refuses a listed caller before the phone
	# rings), the house's numbers by name (the in-call screen names the caller, and
	# the app's contact list shows the house's own names), and a small picture per
	# person, as a data URI, for the call screen - who is calling, before the phone
	# has finished ringing. The app wears its own logo for anyone without one.
	my %names = %{ &phone_names() };
	my %avatars;
	foreach my $number ( keys %names ) {
		my $picture = &phone_avatar_data($names{$number});
		$avatars{$number} = $picture if $picture;
	}
	$c->render(json => {
		blocked => &ticket_blacklist_numbers(),
		names => \%names,
		avatars => \%avatars,
	});
};

post '/manager/box_office/blacklist/number' => sub($c) {
	# Block a number by hand: the desk's own input, or the Phone app's Block on a
	# recent call. The list is the box office's, so one route serves both. A recent
	# call filed from the device's call log carries the caller's app but not always
	# the number, so an app with no number given is looked up the way the phone's
	# own rows hold it.
	unless (&ticket_desk_allowed($c)) {
		$c->render(json => { error => 'denied' });
		return;
	}
	my $number = $c->param('number') || '';
	my $app = $c->param('app') || '';
	unless ($number =~ /\d/) {
		$number = $app ? (&subs::setting_grabber({ app => $app, setting => 'phone' }) || '') : '';
	}
	my $blocked = &ticket_blacklist_block($number, $c->param('name') || $app, $c->param('note'));
	unless ($blocked) {
		$c->render(json => { ok => 0, error => 'no number' });
		return;
	}
	$log->info('call blacklist: ' . $blocked . ' blocked');
	$c->render(json => { ok => 1, number => $blocked, numbers => &ticket_blacklist_numbers() });
};

post '/manager/configure/notification_sound' => sub($c) {
	# A custom ringtone: the audio an app's notification plays. It lands beside the
	# shipped ones (public/sounds/notifications) so every sound list in Configure
	# picks it up with no further wiring; only audio is accepted, named after the
	# file itself so the list reads well, and never overwriting what is there.
	unless (&authentication_passer($c) eq 'approved') {
		$c->render(json => { ok => 0, error => 'denied' });
		return;
	}
	my $upload = $c->req->upload('sound');
	unless ($upload) {
		$c->render(json => { ok => 0, error => 'no file' });
		return;
	}
	my ($ext) = $upload->filename =~ /\.(mp3|ogg|oga|wav|m4a|aac|opus|flac)$/i;
	unless ($ext) {
		$c->render(json => { ok => 0, error => 'audio files only' });
		return;
	}
	$ext = lc $ext;
	if ($upload->size > 12 * 1024 * 1024) {
		$c->render(json => { ok => 0, error => 'that file is too big' });
		return;
	}
	my $name = $upload->filename;
	$name =~ s/\.[^.]*$//;
	$name = lc $name;
	$name =~ s/[^a-z0-9]+/-/g;
	$name =~ s/^-+|-+$//g;
	$name = 'sound' unless length $name;
	my $dir = 'public/sounds/notifications';
	my $file = "$dir/$name.$ext";
	my $i = 2;
	while (-e $file) { $file = "$dir/$name-" . $i++ . ".$ext"; }
	eval { $upload->move_to($file) };
	unless (-e $file && -s $file > 0) {
		$c->render(json => { ok => 0, error => 'could not save that' });
		return;
	}
	(my $shown = $file) =~ s{.*/}{};
	$shown =~ s/\.[^.]*$//;
	$log->info('notification sound added: ' . $file);
	$c->render(json => { ok => 1, sound => './' . $file, name => &subs::format_name($shown) });
};

post '/manager/note_save' => sub($c) {
	# Write a note by hand, or save one being edited: a uuid that is already a note
	# updates in place, anything else is a new note. Every open Notes window is
	# refreshed, so the list stays live.
	my $uuid = $c->param('uuid');
	my $text = $c->param('text');
	$text = '' unless defined $text;
	$text =~ s/\r\n/\n/g;
	$text =~ s/^\s+|\s+$//g;
	my $now = &subs::rightNow();
	my $exists = $uuid ? &subs::db_select('notes', ['uuid'], { uuid => $uuid })->hash : undef;
	my $created = 0;
	if ($exists && $exists->{'uuid'}) {
		&subs::db_update('notes', { text => $text, server_time => $now }, { uuid => $uuid });
	}
	else {
		$uuid = &subs::random_string_creator(21);
		&subs::db_insert('notes', {
			uuid => $uuid,
			app => 'notes',
			text => $text,
			timestamp => $now,
			server_time => $now
		});
		$created = 1;
	}
	&Websocket::send('tab', { console => 'notesReload();' });
	$c->render(json => { uuid => $uuid, text => $text, created => $created });
};

post '/manager/note_delete' => sub($c) {
	# The Notes app's X (two-click: arm, then delete). Notes live in their own
	# table now, so this is scoped to it.
	my $uuid = $c->param('uuid');
	&subs::db_delete('notes', { uuid => $uuid });
	&Websocket::send('tab', { console => 'notesReload();' });
	$c->render(json => { uuid => $uuid });
};

post '/manager/note_to_appt' => sub($c) {
	# A note dragged onto an appointment window. Dropped on one of the window's
	# appointment rows (an .appointment_detail, which carries its own uuid) the
	# note's text is appended to THAT appointment's notes; dropped anywhere else on
	# the window it becomes a new appointment for the app. Either way the notes are
	# encrypted exactly the way manager_reset encrypts a reset's notes.
	my $uuid = $c->param('uuid');
	my $app = &subs::unformat_name($c->param('app'));
	my $appt_uuid = $c->param('appt_uuid');
	my $note = &subs::db_select('notes', undef, { uuid => $uuid })->hash;
	return $c->render(json => { error => 'no such note' }) unless $note && defined $note->{'text'};
	my $text = $note->{'text'};
	my $suds = &subs::session_suds($c);
	my $now = &subs::rightNow();
	if ($appt_uuid) {
		my $appt = &subs::db_select('appointments', undef, { uuid => $appt_uuid })->hash;
		return $c->render(json => { error => 'no such appointment' }) unless $appt && $appt->{'uuid'};
		my $existing = $appt->{'notes'} ? &subs::note_decrypter($suds, $appt->{'notes'}, $appt->{'server_time'}) : '';
		$existing .= "\n" if $existing =~ /\S/;
		&subs::db_update('appointments', { notes => &subs::note_encrypter($suds, $existing . $text), server_time => $now }, { uuid => $appt->{'uuid'} });
		&Websocket::send('tab', { console => 'appointmentDetailGrabber("' . $app . '","' . $appt->{'uuid'} . '");' });
		return $c->render(json => { app => $app, uuid => $appt->{'uuid'}, created => 0 });
	}
	my $new_uuid = &subs::random_string_creator(21);
	&subs::db_insert('appointments', {
		app => $app,
		timestamp => $now,
		server_time => $now,
		type => 'note',
		pos => &subs::setting_grabber({ app => $app, setting => 'pos' }),
		notes => &subs::note_encrypter($suds, $text),
		uuid => $new_uuid,
		seen => 'yes'
	});
	&Websocket::send('tab', { console => 'appointmentDetailGrabber("' . $app . '","' . $new_uuid . '");' });
	$c->render(json => { app => $app, uuid => $new_uuid, created => 1 });
};

sub notification_grabber($data) {

	my $timestamp = &subs::rightNow();
	my @notifications;
	my $settings = &subs::settings_grabber({ app => 'notifications', benign => 1 });
	my $notifications = { titles => [], apps => [], settings => $settings };
	my ($db,$database,$sql) = &subs::database_grabber();
	my $q = &subs::db_query('select * from notifications order by timestamp DESC LIMIT 100');
	my $more_notifications = $q->hashes;
	if ($device eq 'mobile') {
		my $nl = `termux-notification-list`;
		my $notifications = decode_json($nl);
		foreach my $n ( @{$notifications} ) {
			if ($n->{'title'} && !grep { $_->{'id'} eq $n->{'id'} } @{$more_notifications}) {
				my $ts = &subs::ago_calc($n->{'when'},$timestamp);
				&subs::db_insert('notifications', {
					id => $n->{'id'},
					app => &subs::unformat_name($n->{'title'}),
					timestamp => $ts,
					tag => $n->{'tag'},
					message => $n->{'content'},
					title => $n->{'title'},
					key => $n->{'key'},
					image => "/images/make believe/face.png",
					uuid => &subs::random_string_creator(20)
				});
			}
		}
	}

	$q = &subs::db_query('select * from notifications order by timestamp DESC');
	$more_notifications = $q->hashes;

	foreach my $m ( @{$more_notifications}) {
		push @{$notifications->{'apps'}}, $m->{'app'} unless grep { $m->{'app'} eq $_ } @{$notifications->{'apps'}};
	}

	if ($settings->{'filter'} && $settings->{'filter'} ne '' && $settings->{'filter'} ne 'all') {
		@{$more_notifications} = grep { $_->{'app'} eq $settings->{'filter'} } @{$more_notifications};
	}
	if ($settings->{'search'} && $settings->{'search'} ne '') {
		my $search = $settings->{'search'};
		@{$more_notifications} = grep { $_->{'app'} =~ /\Q$search/gi ||  $_->{'message'} =~ /\Q$search/gi } @{$more_notifications};
	}
	if ($data->{'scroll'} eq 'down') {
		my @now_notifications = splice @{$more_notifications}, $data->{'position'} * 100;
		@{$more_notifications} = @now_notifications;

	}
	unless ($data->{'delete'}) {
		splice @{$more_notifications}, 100;
	}
	my $content;

	my $c = &subs::controller_builder();
	foreach my $m ( @{$more_notifications}) {
		$notifications->{'content'} .= $c->render_to_string(
			n => $m,
			template => 'notification',
		);
	}
	$notifications->{'list'} = $more_notifications;
	return $notifications;
}

post '/manager/notifications/remove' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my $tag = $c->param('tag');
	my $title = $c->param('title');
	my $uuid = $c->param('uuid');
	my $app = $c->param('app');
	my $server_time = $c->param('server_time');
	my $scope = $c->param('scope');
	my ($db,$database,$sql) = &subs::database_grabber();
	my $deletions = [];
	if ($tag) {
		if ($device eq 'mobile') {
			`termux-notification-remove $tag`;
		}
	}
	if ($scope eq 'all') {
		my $notifications = &notification_grabber({ delete => 'yes' });
		foreach my $n ( @{$notifications->{'list'}} ) {
			&subs::db_delete('notifications', { uuid => $n->{'uuid'} });
			push @{$deletions}, $n->{'uuid'};
			&deletion_registration({ table => 'notifications', uuid => $n->{'uuid'}, server_time => $n->{'server_time'} });
		}
	}
	else {
		&subs::db_delete('notifications', { timestamp => $timestamp, title => $title, uuid => $uuid });
		&deletion_registration({ table => 'notifications', uuid => $uuid, server_time => $server_time });
		push @{$deletions}, $uuid;
	}
	$c->render(json => $deletions );
};

