sub embedded_app_deleter($data) {
	my $appt_uuid = $data->{'appt_uuid'};
	my $timestamp = &subs::rightNow();
	my $chip_id = $data->{'chip_id'} || 'all';
	my $chips = &subs::device_lister($timestamp, 'microcontroller', undef, $chip_id);
  &subs::subprocessor(sub {
    Mojo::IOLoop->reset;


		foreach my $watch ( @{$chips} ) {
			if ($watch->{'ip'}) {
				my $od = &subs::setting_grabber({ app => 'microcontroller', setting => 'operator_door', subsetting => $watch->{'chip_id'} });
				my $op_d = (eval { decode_json $od }) ? decode_json $od : {};
				my $watch_home = 'http://' . $watch->{'ip'} . ':' . $config->{'port'} . '/delete_job' . '?appt_uuid=' . $appt_uuid . '&authorization=' . $op_d->{'__specs'}->{'authorization'} . '&timestamp=' . $timestamp;

				my $ua = Mojo::UserAgent->new();
				my $ping = 'timeout .2 ping -c 1 ' . $watch->{'ip'};
				my $ping_test = `$ping`;
				if ($ping_test =~ /ttl/gi) {
					my $res = $ua->insecure(1)->get($watch_home)->result;
				}
			}
		}
	}, { name => 'embedded app deleter' });
}

post '/manager/embedded/toggle' => sub($c) {
	my $app = &subs::unformat_name($c->param('app'));
	my $component = $c->param('component');
	my $pin = $c->param('pin');
	my $ip = $c->param('ip');
	my $edt = $c->param('edt');
	my $chip_id = $c->param('chip_id');
	my $timestamp = $c->param('timestamp');
	my $state = $c->param('state');

	my $returner = &embedded_toggle({
		app => $app,
		pin => $pin,
		ip => $ip,
		edt => $edt,
		component => $component,
		timestamp => $timestamp,
		'state' => $state,
		'when' => 'now',
		chip_id => $chip_id
	});
	$c->render(json => $returner);
};

sub embedded_toggle($data) {
	my $app = $data->{'app'};
	my $pin = $data->{'pin'};
	my $ip = $data->{'ip'};
	my $edt = $data->{'edt'};
	my $state = $data->{'state'};
	my $timestamp = $data->{'timestamp'} || &subs::rightNow();
	my $component = $data->{'component'};
	my $uuid = $data->{'uuid'} || &subs::random_string_creator();
	my $appt_uuid = $data->{'appt_uuid'};
	my $chip_id = $data->{'chip_id'};

	my $measure = $data->{'measure'};
	my $when = $data->{'when'} || 'now';
	my $ebc = $gb::embedded_components->{$component};



	my $syl_count = 10;
	$syl_count = 1 unless $edt eq 'microcontroller';
	my $syl = &subs::shorthand_name($component, $syl_count);
	my $od = &subs::setting_grabber({ app => $edt, setting => 'operator_door', subsetting => $chip_id });
	my $op_d = (eval { decode_json $od }) ? decode_json $od : {};
	my $inverted = $op_d->{$syl . $pin}->{'inverted'};
	my $save_state = $state;
	if ($inverted && $inverted == 1) {
		if ($state eq 'on') {
			$state = 'off';
			$save_state = 'on';
		}
		elsif ($state == 1) {
			$state = 'off';
			$save_state = 'on';
		}
		else {
			$state = 'on';
			$save_state = 'off';
		}
	}
	elsif (!$state && !$data->{'measure'}) {
		$state = &subs::setting_grabber({ app => $app, setting => 'toggle' });
		if ($state eq 'on') {
			$state = 'off';
			$save_state = 'off';
		}
		elsif ($state eq 'off') {
			$state = 'on';
			$save_state = 'on';
		}
		elsif ($state == 1) {
			$state = 'off';
			$save_state = 'off'
		}
		else {
			$state = 'on';
			$save_state = 'on';
		}
	}

	if ($component eq 'servo' && $appt_uuid) {
		$state = ($state / 100) * 180;
	}

	if ($state !~ /[0-9]/) {
		# the enabler is drawn through icon_path in the wrapper; use the set's own
		# glyph here too rather than the hand-drawn fallback
		my $toggle_src = &subs::icon_path($save_state, '/images/decipherable/' . $save_state . '.png');
		&Websocket::send('tab', { console => '$(\'.appointment[app="' . $app . '"]\').find(\'.enabler[type="toggle"\').attr(\'status\',\'' .$save_state . '\').attr(\'src\', \'' . $toggle_src . '\');' });
		&subs::setting_setter({ app => $app, setting => 'toggle', value => $save_state, source => 'toggle' }) if $data->{'counted'} == 0 || !$data->{'counted'};
	}

	# A board on the bridge - or one with no LAN address at all - takes the
	# output command as a BLE `set` message. The state above is already the
	# physical one (the inversion was folded in), so the board applies it
	# directly and answers with a `state` ack. This is what lets a crashed board
	# resume its relays before it has rejoined WiFi.
	if ($chip_id && ($component eq 'led' || $component eq 'relay' || $component eq 'servo')) {
		my $number_state = $state eq 'on' ? 1 : ($state eq 'off' ? 0 : $state);
		# A bridge connect waits for the link (the client gives it 30 seconds), so
		# the send must never run in the request. The worker picks the road: the
		# bridge when the device is BLE or has no LAN address, the HTTP send when
		# it has one and the bridge did not answer.
		&subs::subprocessor(sub {
			Mojo::IOLoop->reset;
			my $watch = &subs::device_lister($timestamp, $edt, undef, $chip_id);
			my $watch_ip = (ref $watch eq 'HASH' && $watch->{'ip'}) ? $watch->{'ip'} : $ip;
			if (ref $watch eq 'HASH' && ($watch->{'ble'} || !$watch->{'ip'})) {
				my $sent = eval {
					&subs::bluetooth_sender({
						intent => 'com.jawn.president.bt.connect',
						chip_id => $chip_id,
						edt => $edt,
						message => { type => 'set', data => {
							component => $component, pin => $pin, state => $state,
							when => $when, uuid => $uuid, appt_uuid => $appt_uuid,
							timestamp => $timestamp, measure => $measure, app => $app
						} }
					});
				};
				return if $sent || !$watch_ip;
			}
			return unless $watch_ip;
			eval {
				my $watch_home = 'http://' . $watch_ip . ':' . $config->{'port'} . '/' . $component . '?appt_uuid=' . $appt_uuid . '&uuid=' . $uuid . '&when=' . $when . '&pin=' . $pin . '&state=' . $state . '&component=' . $component . '&authorization=' . $op_d->{'__specs'}->{'authorization'} . '&timestamp=' . $timestamp . '&measure=' . $measure;
				my $ua = Mojo::UserAgent->new();

				my $res = $ua->insecure(1)->get($watch_home)->result;
				if (eval { $res->result->body }) {
					if (eval { decode_json $res->result->body }) {
						my $rb = decode_json $res->result->body;
						$state = $rb->{'state'};
						$pin = $rb->{'pin'};
					}
				}
			};
		}, { name => 'embedded toggle sender' });
		return { state => $number_state, formatted_state => $state };
	}

  &subs::subprocessor(sub {
    Mojo::IOLoop->reset;
		eval {
			my $watch = &subs::device_lister($timestamp, $edt, undef, $chip_id);

			my $watch_home = 'http://' . $watch->{'ip'} . ':' . $config->{'port'} . '/' . $component . '?appt_uuid=' . $appt_uuid . '&uuid=' . $uuid . '&when=' . $when . '&pin=' . $pin . '&state=' . $state . '&component=' . $component . '&authorization=' . $op_d->{'__specs'}->{'authorization'} . '&timestamp=' . $timestamp . '&measure=' . $measure;
			my $ua = Mojo::UserAgent->new();

			my $res = $ua->insecure(1)->get($watch_home)->result;
			if (eval { $res->result->body }) {
				if (eval { decode_json $res->result->body }) {
					my $rb = decode_json $res->result->body;
					$state = $rb->{'state'};
					$pin = $rb->{'pin'};
				}
			}
			my $number_state = $state eq 'on' ? 1 : 0;
		};
	}, { name => 'embedded toggle sender' });
	my $number_state = $state eq 'on' ? 1 : 0;
	my $returner = { 'state' => $number_state, formatted_state => $state };

	return $returner;
}

post '/manager/embedded/ota_uploader' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my $edt = $c->param('edt');
	my $chip_id = $c->param('chip_id');

	if ($edt eq 'microcontroller') {
		my $watch = &subs::device_lister($timestamp, $edt, undef, $chip_id);
		# The manager serves firmware from a hardwired path, not .pio/build.
		# scripts/stage_firmware.pl copies the newest build here; a stale file
		# here means the OTA ships the previous firmware.
		my $file = './jp/alarmclock/build/rp2040.rp2040.rpipico2w/alarmclock.ino.bin';
		my $total_size = -s $file;
		unless ($total_size) {
			return $c->render(json => { success => 0, result => 'firmware not staged - run perl scripts/stage_firmware.pl' });
		}
		# The device's own Now Me token: handleCreateProcess refuses an upload
		# without it, and this route used to omit it entirely.
		my $od = &subs::setting_grabber({ app => $edt, setting => 'operator_door', device => $device, subsetting => $chip_id });
		my $op_d = eval { decode_json $od } || {};
		my $auth = $op_d->{'__specs'}->{'authorization'} || '';
		unless ($auth) {
			return $c->render(json => { success => 0, result => 'no authorization on record - run Now Me first' });
		}

		my $watch_home = 'http://' . $watch->{'ip'} . ':' . $config->{'port'} . '/upload/alarmclock.bin?total_size=' . $total_size . '&authorization=' . url_escape($auth);
		my $ua = Mojo::UserAgent->new();
    $ua->transactor->add_generator(stream => sub ($transactor, $tx, $path) {
      $tx->req->content->asset(Mojo::Asset::File->new(path => $file));
    });
		&Websocket::send('tab', { console => '$(\'#embedded_ota_uploader_wait\').show()', browser_tab_id => $c->param('browser_tab_id') });
		&Websocket::send('tab', { console => '$(\'#embedded_ota_uploader_fail\').hide()', browser_tab_id => $c->param('browser_tab_id') });
		&Websocket::send('tab', { console => '$(\'#embedded_ota_uploader_success\').hide()', browser_tab_id => $c->param('browser_tab_id') });
		$ua->inactivity_timeout(120000);
    my $res = $ua->insecure(1)->post($watch_home  => stream => $file )->result;

		if ($res->is_success) {
			&Websocket::send('tab', { console => '$(\'#embedded_ota_uploader_wait\').hide()', browser_tab_id => $c->param('browser_tab_id') });
			&Websocket::send('tab', { console => '$(\'#embedded_ota_uploader_success\').show()', browser_tab_id => $c->param('browser_tab_id') });
		}
		else {
			&Websocket::send('tab', { console => '$(\'#embedded_ota_uploader_wait\').hide()', browser_tab_id => $c->param('browser_tab_id') });
			&Websocket::send('tab', { console => '$(\'#embedded_ota_uploader_fail\').show()', browser_tab_id => $c->param('browser_tab_id') });
		}




		$c->render(text => 'yes');
	}
	else {
		$c->render(text => 'no');
	}


};

# the esp32 boards have no build path baked into the manager the way the pico
# does: the panel hands over whatever .bin was picked, we stream it to the
# board's own /update and the board flashes itself and reboots.
post '/manager/embedded/ota_uploader_wifi' => sub($c) {
	my $timestamp = $c->param('timestamp');
	my $ip = $c->param('ip');
	my $firmware = $c->req->upload('firmware');

	if (!$ip || !$firmware) {
		return $c->render(json => { success => 0, result => 'needs a board ip and a .bin' });
	}

	my $image = $firmware->slurp;
	my $boundary = '----jawnos' . int(rand(1000000000));
	my $body =
		"--$boundary\r\n" .
		"Content-Disposition: form-data; name=\"firmware\"; filename=\"" . ($firmware->filename || 'firmware.bin') . "\"\r\n" .
		"Content-Type: application/octet-stream\r\n\r\n" .
		$image . "\r\n--$boundary--\r\n";

	my $ua = Mojo::UserAgent->new();
	$ua->inactivity_timeout(180000);
	my $res = $ua->post('http://' . $ip . '/update' => { 'Content-Type' => "multipart/form-data; boundary=$boundary" } => $body)->result;
	my $result = $res->is_success ? $res->body : ($res->error ? $res->error->{message} : 'board said ' . $res->code);

	$c->render(json => { success => $res->is_success ? 1 : 0, code => $res->code, result => $result });
};

# ---- USB flashing -----------------------------------------------------------
# The esp32 boards are plugged into this machine, so the panel cannot flash them
# itself: it asks the manager, which runs the PlatformIO upload and then polls the
# log for esptool's percentage lines.

sub usb_ports_grabber {
	my %by_id;
	foreach my $link ( glob('/dev/serial/by-id/*') ) {
		my $target = readlink($link);
		next unless $target;
		$target =~ s{.*/}{};
		my $label = $link;
		$label =~ s{.*/}{};
		$label =~ s{-if\d+.*$}{};
		$label =~ s{[_-]}{ }g;
		$by_id{'/dev/' . $target} = &subs::format_name($label);
	}
	my @ports;
	foreach my $path ( glob('/dev/ttyACM*'), glob('/dev/ttyUSB*') ) {
		push @ports, {
			path => $path,
			label => $by_id{$path} || $path,
			acm => ($path =~ /ttyACM/) ? 1 : 0
		};
	}
	return \@ports;
}

get '/manager/embedded/usb_ports' => sub($c) {
	$c->render(json => { ports => &usb_ports_grabber() });
};

post '/manager/embedded/usb_upload' => sub($c) {
	my $edt = $c->param('edt') || 'watch';
	my $chip_id = $c->param('chip_id');
	my $port = $c->param('port');

	my ($project, $environment, $prefer_acm) = $edt eq 'teletype' ? ('./jt', 'deck', 0) : ('./jw', 'watch', 1);

	if ($port && $port !~ m{^/dev/(ttyACM|ttyUSB)\d+$}) {
		return $c->render(json => { started => 0, result => 'that port does not look right' });
	}

	# the watch speaks native USB (ttyACM), the deck sits behind its bridge (ttyUSB);
	# auto-pick when there is exactly one candidate of the right kind
	my $ports = &usb_ports_grabber();
	if (!$port) {
		my @preferred = grep { $_->{'acm'} == $prefer_acm } @{$ports};
		if (@preferred == 1) {
			$port = $preferred[0]->{'path'};
		}
		elsif (scalar @{$ports} == 1) {
			$port = $ports->[0]->{'path'};
		}
	}
	if (!$port) {
		return $c->render(json => { started => 0, result => (scalar @{$ports} ? 'pick a port' : 'no board is plugged in'), ports => $ports });
	}

	my $pio = (-x &subs::home('~/.platformio/penv/bin/pio')) ? &subs::home('~/.platformio/penv/bin/pio') : 'pio';
	my $log = &subs::home('~/.jawnos_usb_upload.log');
	my $project_path = Mojo::File->new($project)->to_abs_path;
	Mojo::File->new($log)->spurt("usb upload to $port starting...\n");
	my $command = 'cd ' . $project_path . ' && exec ' . $pio . ' run -j 4 -e ' . $environment . ' -t upload --upload-port ' . $port;
	system("nohup sh -c '" . $command . "' > " . $log . " 2>&1 &");

	$c->render(json => { started => 1, port => $port, project => $project });
};

get '/manager/embedded/usb_upload_status' => sub($c) {
	my $log = &subs::home('~/.jawnos_usb_upload.log');
	my $text = -e $log ? read_file($log) : '';
	$text = substr($text, -6000) if length($text) > 6000;
	my @percent = ($text =~ m{\((\d+(?:\.\d+)?) %\)}g);
	@percent = ($text =~ m{(\d+(?:\.\d+)?)%}g) unless @percent;
	my $success = ($text =~ m{\[SUCCESS\]}) ? 1 : 0;
	my $failed = (!$success && $text =~ m{\[FAILED\]|error:}) ? 1 : 0;
	my @lines = grep { /\S/ } map { my $l = $_; $l =~ s/^\s+//; $l =~ s/\s+$//; $l } split m{\n}, $text;
	$c->render(json => {
		running => ($success || $failed) ? 0 : 1,
		success => $success,
		failed => $failed,
		percent => (@percent ? $percent[-1] : ''),
		tail => (@lines ? $lines[-1] : '')
	});
};

# Provision a board over its USB serial link: the manager writes the stored WiFi
# and role into config.txt, the board acknowledges and reboots, and it comes up
# on the house network with its pins already restored. This is the out-of-band
# path for a crashed board that is sitting on the desk in its provisioning AP
# (and for a Pico 2 W, which has no Bluetooth stack to fall back on).
post '/manager/embedded/usb_provision' => sub($c) {
	require IO::Select;
	require IO::Handle;
	my $chip_id = $c->param('chip_id');
	my $edt = $c->param('edt') || 'microcontroller';
	my $port = $c->param('port');
	return $c->render(json => { ok => 0, error => 'need a chip_id' }) unless $chip_id;

	unless ($port) {
		my $ports = &usb_ports_grabber();
		my @acm = grep { $_->{'acm'} } @{$ports};
		if (scalar @acm == 1) { $port = $acm[0]->{'path'}; }
		else {
			# More than one board can be plugged in. The USB descriptor carries
			# the Pico's chip id (the serial number), so pick the one that names
			# this chip rather than asking which cable is which.
			my $key = $chip_id;
			$key =~ s/[^0-9A-F]//gi;
			my @match = grep {
				my $label = $_->{'label'} || '';
				$label =~ /\Q$chip_id\E/i || ($key && $label =~ /\Q$key\E/i)
			} @acm;
			if (scalar @match == 1) { $port = $match[0]->{'path'}; }
			else {
				return $c->render(json => { ok => 0, error => 'choose a port', ports => $ports });
			}
		}
	}
	return $c->render(json => { ok => 0, error => 'that port does not look right' }) unless $port =~ m{^/dev/tty(?:ACM|USB)\d+$};

	my $wifi = eval { decode_json &subs::setting_grabber({ app => $edt, setting => 'wifi', subsetting => $chip_id }) } || {};
	return $c->render(json => { ok => 0, error => 'this chip has no stored WiFi' }) unless $wifi->{'ssid'} && $wifi->{'password'};
	my $op = eval { decode_json &subs::setting_grabber({ app => $edt, setting => 'operator_door', subsetting => $chip_id }) } || {};

	# The homebase a board calls is this machine, at the port /watch listens on.
	my $address = &subs::network_interface_reporter();
	my ($my_ip) = map { $address->{$_}->{'ip'} }
		grep { $address->{$_}->{'ip'} && $address->{$_}->{'ip'} !~ /^127\./ } keys %{$address};
	$my_ip ||= '127.0.0.1';

	# Small on purpose: WiFi, identity and the token are all the board needs to
	# rejoin. Its role (components and internal jobs) is the manager's copy and
	# comes back over BLE, or from /watch once the network is up. A 2.5 KB role
	# blob on this CDC link was where the JSON got truncated.
	# No timestamp/offset here: the board takes the clock from /watch/time (and
	# from now_me over BLE). An offset that serialized as an empty token made
	# the whole file unparseable, which is what put the board back in its AP.
	my $payload = {
		ssid => $wifi->{'ssid'},
		password => $wifi->{'password'},
		ap_ssid => $wifi->{'ap_ssid'},
		ap_password => $wifi->{'ap_password'},
		name => $op->{'__specs'}->{'name'} || '',
		authorization => $op->{'__specs'}->{'authorization'} || '',
		homebase => '',
		homebaseIP => $my_ip . ($ENV{'PORT_ARM'} ? ':' . $ENV{'PORT_ARM'} : '')
	};
	my $json = encode_json $payload;

	system('stty', '-F', $port, 'raw', '115200', '-echo') == 0
		or return $c->render(json => { ok => 0, error => 'could not prepare ' . $port });
	open(my $fh, '+<', $port)
		or return $c->render(json => { ok => 0, error => 'could not open ' . $port . ': ' . $! });
	$fh->autoflush(1);
	# The Pico's USB CDC receive ring is small; a 2.5 KB line written in one go
	# overflows it and the JSON arrives truncated (the board still answers OK,
	# because the partial object parses). Feed it in small pieces, paced so the
	# sketch's loop drains each one before the next.
	my $line = "JAWNCFG " . $json . "\n";
	for (my $off = 0; $off < length($line); $off += 64) {
		print {$fh} substr($line, $off, 64);
		select(undef, undef, undef, 0.004);
	}

	my $sel = IO::Select->new($fh);
	my ($buf, $err, $ok) = ('', '', 0);
	my $deadline = time() + 8;
	while (time() < $deadline) {
		my @ready = $sel->can_read(0.25);
		next unless @ready;
		my $chunk = '';
		my $n = sysread($fh, $chunk, 4096);
		last unless defined $n && $n > 0;
		$buf .= $chunk;
		if ($buf =~ /JAWNCFG OK/) { $ok = 1; last; }
		if ($buf =~ /JAWNCFG ERR\s*([^\r\n]*)/) { $err = $1; last; }
	}
	close $fh;
	# Never hand the echoed command back: it carries the WiFi password and the
	# device authorization. An older firmware echoes it; strip that line.
	my $reply = $buf;
	$reply =~ s/JAWNCFG \{[^\n]*\n?//g;
	$c->render(json => {
		ok => $ok,
		port => $port,
		bytes => length($json),
		reply => $reply,
		error => $ok ? undef : ($err || 'no reply from the board')
	});
};

# A manual nudge for the bridge's adopt scan. The scan already runs every 30 s;
# this button exists so a device that was just powered on can be met at once.
# It runs off the request (the scan takes several seconds) and the Dev panel
# refreshes after it.
post '/manager/configure/ble_scan' => sub($c) {
	&subs::subprocessor(sub { &subs::ble_adopt_scan(); }, { name => 'manual ble adopt scan' });
	$c->render(json => { ok => 1, scanning => 1 });
};

# A peer machine hands over one device-to-device relay envelope. The receiving
# manager sends it only if it may serve the target chip; it never fans it out
# again (from_mesh), so one relay cannot loop around the mesh.
post '/manager/ble/relay' => sub($c) {
	my $relay = eval { decode_json($c->param('payload') || '') };
	my $ok = ($relay && ref $relay eq 'HASH') ? &subs::ble_relay_route($relay, { from_mesh => 1 }) : 0;
	$c->render(json => { ok => $ok ? 1 : 0 });
};

get '/manager/embedded/teletype_backup' => sub($c) {
	my $ip = $c->param('ip');
	my $mac = $c->param('mac');
	my $timestamp = $c->param('timestamp');
	my $teletype = &subs::device_lister($timestamp,'teletype');
	my $chip_id = $c->param('chip_id');
	$c->param('reason' => 'teletype_backup');
  &subs::subprocessor(sub {
    Mojo::IOLoop->reset;

		if ($teletype->{'ip'} && !$teletype->{'uuid'} && $teletype->{'ip'} eq $ip) {
			my $ping = 'timeout .2 ping -c 1 ' . $teletype->{'ip'};
			my $ping_test = `$ping`;
			my $backup = &subs::backup_now($c);
			$backup = encode_json $backup;
			if ($ping_test =~ /ttl/gi) {
				my $teletype_url = 'http://' . $teletype->{'ip'} . ':' . $config->{'port'} . '/backup?backup=' . $backup . '&timestamp=' . $timestamp;
				my $ua = Mojo::UserAgent->new();
				my $res = $ua->insecure(1)->get($teletype_url)->result;
			}
		}
	}, { name => 'teletype backup' });
};

get '/manager/embedded/jobs' => sub($c) {
	my $ip = $c->param('ip');
	my $mac = $c->param('mac');
	my $edt = $c->param('edt');
	my $chip_id = $c->param('chip_id');
	my $timestamp = $c->param('timestamp');
	my $mc = &subs::device_lister($timestamp, $edt, undef, $chip_id);

	my $wat_set = &subs::setting_grabber({ app => $edt, setting => 'operator_door', device => $device, subsetting => $chip_id });;
	my $watch_settings = eval { return decode_json $wat_set } || {};

	my $auth = $watch_settings->{'__specs'}->{'authorization'};
	my $author = `echo $auth | base64 --decode`;
	my $authorization = &subs::note_decrypter($watch_settings->{'__shutup'}->{'patience'}, $author);





	my $url = 'http://' . $mc->{'ip'} . ':' . $config->{'port'} . '/jobs?authorization=' . $authorization;
	my $ua = Mojo::UserAgent->new();
	my $res = $ua->insecure(1)->get($url)->result;
	my $returner = {};
	if ($res->is_success) {
		my $jobs = eval { return decode_json $res->body } || {};
		$returner->{'jobs'} = $jobs;
		$returner->{'html'} = $c->render_to_string(
			template => 'embedded/jobs',
			jobs => $jobs,
			op_d => $watch_settings
		);
	}

	$c->render(json => $returner);

};

post '/manager/embedded/delete_job' => sub($c) {
	my $appt_uuid = $c->param('appt_uuid');
	my $chip_id = $c->param('chip_id');
	my $uuid = $c->param('uuid');
	&embedded_app_deleter({ appt_uuid => $appt_uuid, $chip_id });
	$c->render(json => { uuid => $uuid, appt_uuid => $appt_uuid });
};

post '/manager/watch/assign' => sub($c) {
	my $edt = $c->param('edt');
	my $ip = $c->param('ip');
	my $timestamp = $c->param('timestamp');
	my $app = &subs::unformat_name($c->param('app'));
	my $pre_value = $c->param('pre_value');
	my $numero = $c->param('numero');
	my $component = $c->param('component');
	my $chip_id = $c->param('chip_id');
	my $syl_count = 10;
	$syl_count = 1 unless $edt eq 'microcontroller';
	my $syl = &subs::shorthand_name($component, $syl_count);
	my $type = 'text';
	($app,$type) = &subs::typesetter($app);
	&subs::setting_setter({ app => $app, setting => 'pos', value => $type });
	my $init = &subs::setting_initializer($app,$timestamp);
	$app = $init->{'app'};
	my $od = &subs::setting_grabber({ app => $edt, setting => 'operator_door', subsetting => $chip_id });
	my $op_d = (eval { decode_json $od }) ? decode_json $od : {};
	my $colour = &subs::setting_grabber({ app => $app, setting=> 'colour' });
	$colour =~ s/^#//gi;
	my @rgb = map $_ , unpack 'C*', pack 'H*', $colour;
	$op_d->{$syl . $numero} = {
		'colour' => $colour,
		rgb => \@rgb,
		shorthand_name => &subs::shorthand_name(&subs::format_name($app)),
		app => $app,
		movement => $op_d->{$syl . $numero}->{'movement'} || 'command',
		inverted => $op_d->{$syl . $numero}->{'inverted'},
		numero => $numero,
		measure => $op_d->{$syl . $numero}->{'measure'},
		toggle => $op_d->{$syl . $numero }->{'toggle'} || 0,
		direction => $gb::embedded_components->{$component}->{'direction'},
		component => $component,
		uuid => &subs::random_string_creator(),
		name => $op_d->{$syl . $numero}->{'name'}
	};
	if ($app eq '') {
		delete $op_d->{$syl . $numero};
	}
	my $json_od = encode_json $op_d;
	&subs::setting_setter({ app => $edt, setting => 'operator_door', value => $json_od, subsetting => $chip_id });
	my $pia = eval { return decode_json &subs::setting_grabber({ app => $pre_value, setting => 'ia' }) } || {};
	delete $pia->{$chip_id}->{$numero};
	my $jpia = encode_json $pia;
	&subs::setting_setter({ app => $pre_value, setting => 'ia', value => $jpia });
	my $ia = eval { return decode_json &subs::setting_grabber({ app => $app, setting => 'ia'}) } || {};
	$ia->{$chip_id}->{$numero} = {
		movement =>	$op_d->{$syl . $numero}->{'movement'},
		ip => $ip,
		edt => $edt,
		pin => $numero,
		direction => $gb::embedded_components->{$component}->{'direction'},
		component => $component
	};
	my $jia = encode_json $ia;
	&subs::setting_setter({ app => $app, setting => 'ia', value => $jia });
	my $returner = &embedded_pin_grabber({
		edt => $edt,
		numero => $numero,
		component => $component,
		chip_id => $chip_id,
		timestamp => $timestamp,
		component => $component
	});
	my $res = &now_me({ c => $c, timestamp => $timestamp, edt => $edt, chip_id => $chip_id, browser_tab_id => $c->param('browser_tab_id') });
	$c->render('json' => { app => $app, formatted_name => &subs::format_name($app ), html => $returner->{'html'} });
};

post '/manager/watch/setting' => sub($c) {
	my $edt = $c->param('edt');
	my $timestamp = $c->param('timestamp');
	my $numero = $c->param('numero');
	my $movement = $c->param('movement');
	my $setting = $c->param('setting');
	my $component = $c->param('component');
	my $syl_count = 10;
	my $chip_id = $c->param('chip_id');
	my $percentage = $c->param('percentage');
	$syl_count = 1 unless $edt eq 'microcontroller';
	my $syl = &subs::shorthand_name($component, $syl_count);
	my $od = &subs::setting_grabber({ app => $edt, setting => 'operator_door', subsetting => $chip_id });
	my $op_d = (eval { decode_json $od }) ? decode_json $od : {};
	my $app = $op_d->{$syl . $numero}->{app};
	$op_d->{$syl . $numero}->{$setting} = $movement;
	if ($percentage) {
		$op_d->{$syl . $numero}->{$setting . '_percentage'} = $percentage;
	}
	my $json_od = encode_json $op_d;
	&subs::setting_setter({ app => $edt, setting => 'operator_door', value => $json_od, timestamp => $timestamp, subsetting => $chip_id });
	my $jia = &subs::setting_grabber({ app => $app, setting => 'ia' });
	if ($jia) {
		my $ia = eval { return decode_json $jia } || {};
		$ia->{$chip_id}->{$numero}->{$setting} = $movement;
		if ($percentage) {
			$ia->{$chip_id}->{$numero}->{$setting . '_percentage'} = $percentage;
		}
		my $jia = encode_json $ia;
		&subs::setting_setter({ app => $app, setting => 'ia', value => $jia });
	}
	my $returner = &embedded_pin_grabber({
		edt => $edt,
		numero => $numero,
		component => $component,
		chip_id => $chip_id,
		timestamp => $timestamp
	});
	my $res = &now_me({ c => $c, timestamp => $timestamp, edt => $edt, chip_id => $chip_id, browser_tab_id => $c->param('browser_tab_id') });
	$c->render(json => $returner );
};

get '/manager/watch/diagram' => sub($c) {
	my $uuid = $c->param('uuid');
	my $edt = $c->param('edt');
	my $chip_id = $c->param('chip_id');
	my $diagrams = eval { return decode_json &subs::setting_grabber({ app => 'embedded', setting => 'diagrams' }) } || [];
	@{$diagrams} = grep { $_->{'uuid'} eq $uuid } @{$diagrams};
	my $diagram = $diagrams->[0];

	my $op_d = eval { return decode_json &subs::setting_grabber({ app => $edt, setting => 'operator_door', subsetting => $chip_id }) } || {};
	my $returner = { uuid => $uuid, diagram => $diagram };
	$returner->{'html'} = $c->render_to_string(
		template => 'embedded/diagram',
		d => $diagram,
		op_d => $op_d
	);
	$c->render(json => $returner);
};

post '/manager/watch/diagram' => sub($c) {
	my $edt = $c->param('edt');
	my $chip_id = $c->param('chip_id');
	my $timestamp = $c->param('timestamp');
	my $diagram = eval { return decode_json $c->param('diagram') } || {};
	my $op_d = eval { return decode_json &subs::setting_grabber({ app => $edt, setting => 'operator_door', subsetting => $chip_id }) } || {};

	my $diagrams = eval { return decode_json &subs::setting_grabber({ app => 'embedded', setting => 'diagrams'}) } || [];
	my $returner = { diagram => $diagram };
	foreach my $d ( @{$diagrams} ) {
		if ($d->{'uuid'} eq $diagram->{'file'}->{'uuid'}) {
			$d->{'components'} = $diagram->{'components'};
		}
	}
	my $jdiagrams = encode_json $diagrams;
	&subs::setting_setter({ app => 'embedded', setting => 'diagrams', value => $jdiagrams });
	$returner->{'diagrams'} = $diagrams;
	$c->render(json => $returner);
};


post '/manager/watch/measure' => sub($c) {
	my $edt = $c->param('edt');
	my $component = $c->param('component');
	my $numero = $c->param('numero');
	my $syl_count = 10;
	my $chip_id = $c->param('chip_id');
	my $timestamp = $c->param('timestamp') || &subs::rightNow();
	$syl_count = 1 unless $edt eq 'microcontroller';
	my $syl = &subs::shorthand_name($component, $syl_count);
	my $measure = $c->param('measure');

	my $od = &subs::setting_grabber({ app => $edt, setting => 'operator_door', subsetting => $chip_id });
	my $op_d = eval { return decode_json $od } || {};

	$op_d->{$syl . $numero}->{'measure'} = $measure;
	my $app = $op_d->{$syl . $numero}->{'app'};
	my $jopd = encode_json $op_d;
	&subs::setting_setter({ app => $edt, setting => 'operator_door', subsetting => $chip_id, value => $jopd });
	my $jia = &subs::setting_grabber({ app => $app, setting => 'ia' });
	if ($jia) {
		my $ia = eval { return decode_json $jia } || {};
		$ia->{$chip_id}->{$numero}->{'measure'} = $measure;

		$jia = encode_json $ia;
		&subs::setting_setter({ app => $app, setting => 'ia', value => $jia });
	}
	my $returner = &embedded_pin_grabber({
		edt => $edt,
		numero => $numero,
		component => $component,
		chip_id => $chip_id,
		timestamp => $timestamp
	});
	$c->render(json => $returner);
};

sub send_telephone($app,$msg) {
	my $timestamp = &subs::rightNow();
	foreach my $w ( qw/teletype watch microcontroller/ ) {
		my $chips = &subs::device_lister($timestamp,$w,undef, 'all');
		foreach my $watch ( @{$chips} ) {
			my $od = &subs::setting_grabber({ 'app' => $watch->{'purpose'}, 'setting' => 'operator_door', subsetting => $watch->{'chip_id'}  });
			my $op_d = (eval { decode_json $od }) ? decode_json $od : {};
			if ($watch->{'ip'} && !$watch->{'uuid'}) {
				my $ping = 'timeout .2 ping -c 1 ' . $watch->{'ip'};
				my $ping_test = `$ping`;


				if ($ping_test =~ /ttl/gi) {
					my $watch_home = 'http://' . $watch->{'ip'} . ':' . $config->{'port'} . '/send_telephone?app=' . $app . '&msg=' .
					&subs::unformat_name($msg) . '&timestamp=' . $timestamp;
			    &subs::subprocessor(sub {
				    Mojo::IOLoop->reset;

						my $ua = Mojo::UserAgent->new();
						my $res = $ua->insecure(1)->get($watch_home)->result;
					}, { name => 'send telephone' });
				}
				sleep 2;
			}
		}
	}
}

sub now_me($data) {
	my $timestamp = $data->{'timestamp'};
	my $edt = $data->{'edt'};
	my $ip = $data->{'ip'};
	my $chip_id = $data->{'chip_id'};
	my $name = $data->{'name'};
	my $method = $data->{'method'};
	# an explicit homebase: the address a BLE bridge is re-homing the watch to.
	# now_me's own choice trusts the watch's LAN, where two machines share a /24
	# and cannot be told apart, so the bridge names the address instead.
	my $forced_home = $data->{'homebase'};
	my $server_time = time();



	my $watch = &subs::device_lister($timestamp, $edt, undef, $chip_id);
	# A Bluetooth-only watch belongs to one machine. A different machine must not
	# rotate its homebase and authorization, or re-push the watch onto itself -
	# bluetooth_sender refuses the send anyway, so a Now Me here would only
	# desync the record. The edit that triggered it still saves; the watch gets
	# it from its homebase. Leave the record alone.
	# A Bluetooth-only watch belongs to one machine, and a machine that is not the
	# homebase must not quietly rewrite the pairing. But an EXPLICIT "BT Now Me"
	# (method 'bluetooth', the watch-row action) is the person moving the watch to
	# this machine on purpose, so let that one through - it is how you re-home a
	# watch whose homebase is gone (a phone that died) onto the machine in hand.
	if ($watch->{'ble'} && !&subs::ble_owns($edt, $chip_id) && ($method || '') ne 'bluetooth') {
		$log->info('Now Me for ' . ($chip_id || '?') . ' skipped: homebase is ' . ($watch->{'homebase'} || '?'));
		return 'hosted elsewhere';
	}
	my $watch_port = $ENV{PORT_ARM};

	my $ws_port = $ENV{PORT_MSG};
	# The current record may have been written by a House machine of another
	# class; Now Me must read it, or a fallback machine would rewrite it blank.
	my $od = &subs::embedded_operator_door($edt, $chip_id)
		|| &subs::setting_grabber({ app => $edt, setting => 'operator_door', device => $device, subsetting => $chip_id });
	my $op_d = eval { decode_json $od } || {};
	$name = $op_d->{'__specs'}->{'name'} unless $data->{'name'};
	my $address = &subs::network_interface_reporter();
	unless (&subs::same_net_test($watch->{'homebase'},$ip,'127.0.0.1') eq 'yes') {
		foreach my $nic ( keys %{$address} ) {
			if (&subs::same_net_test($address->{$nic}->{'ip'},$ip,'override') eq 'yes') {
				$watch->{'homebase'} = $address->{$nic}->{'ip'};
			}
		}
	}
	$ip = $watch->{'homebase'};# unless $ip;

	$op_d->{'__specs'}->{'room_count'} = $op_d->{'__specs'}->{'room_count'} || &subs::setting_grabber({'app' => 'me', setting => 'room_count'}) || $op_d->{'__specs'}->{'room_count'} || 2;
	$op_d->{'__specs'}->{'homebase'} = ($forced_home || $watch->{'homebase'}) . ':' . $watch_port;
	$op_d->{'__specs'}->{'ip'} = $forced_home || $watch->{'homebase'};
	$op_d->{'__specs'}->{'edt'} = $edt;
	$op_d->{'__specs'}->{'name'} = $name;
	my @t = localtime(time);
	# $offset already carries DST: timelocal() honours the zone's DST rules, so
	# it is -4 h in summer and -5 h in winter here. The old winter branch added
	# 1000*3600 (the milliseconds in an hour) to a seconds epoch -- about 42
	# days, not an hour -- so it never did what it looked like; drop it.
	my $offset = timegm(@t) - timelocal(@t);
	$op_d->{'__specs'}->{'time'} = {
		sec => $t[0],
		min => $t[1],
		hour => $t[2],
		day => $t[3],
		month => $t[4] + 1,
		year => $t[5] + 1900
	};
	my $computer_name = &subs::config_reader()->{'name'} || &subs::setting_grabber({ app => 'me', setting => 'computer_name' }) || `hostname`;
	$computer_name =~ s/^\s+|\s+$//g;
	$op_d->{'__specs'}->{'computer'} = &manager_file_maker() || $op_d->{'__specs'}->{'homebase'};
	my $room_count = $op_d->{'__specs'}->{'room_count'};
	if ($edt eq 'watch') {
		$op_d->{'__specs'}->{'room_max'} = 6;
	}
	elsif ($edt eq 'teletype') {
		$op_d->{'__specs'}->{'room_max'} = 8;
	}
	else {
		$op_d->{'__specs'}->{'room_max'} = 1;
	}
	my $room_max = $op_d->{'__specs'}->{'room_max'};
	my $screen_timeout = ($op_d->{'__specs'}->{'screen_timeout'} || 20) * 1000;
	# the authorization rotates on every Now Me, bluetooth included now that the
	# bridge can deliver it; reusing the stored one left the phone and the watch
	# disagreeing whenever the panel ran anywhere else
	#
	# A rotation invalidates the pair the device is still holding, and the push that
	# would hand it the new one can be missed - a link that is down, a bridge that
	# is away, an endpoint that times out. Park the pair being replaced, with its
	# time, so embeddedAuthorizer can keep accepting it for a grace window and a
	# missed push costs a moment instead of locking the device out of /watch (the
	# Gate, and with it an empty room).
	if ($op_d->{'__specs'}->{'authorization'} && $op_d->{'__shutup'}->{'patience'}) {
		$op_d->{'__shutup'}->{'previous'} = {
			patience      => $op_d->{'__shutup'}->{'patience'},
			authorization => $op_d->{'__specs'}->{'authorization'},
			at            => time(),
		};
	}
	my $patience = &subs::random_string_creator(36);
	my $au = &subs::random_string_creator(27);
	my $auth = &subs::note_encrypter($patience, $au );
	my $authorization = `(echo $auth) | base64 -w 0`;
	$op_d->{'__shutup'}->{'patience'} = $patience;
	$op_d->{'__specs'}->{'authorization'} = $authorization;

	# A device that loses its homebase must still have a House to reach, so Now
	# Me carries the other machines on its LAN with the ports it dials. mDNS
	# refreshes this on the device; the list is what makes a board that cannot
	# browse mDNS (and a device whose last Now Me predates the House) recover.
	my $house_nodes = &subs::house_nodes_list($watch->{'homebase'} || $watch->{'ip'});

	my $params = {
		name           => $name,
		ip             => $watch->{ip},
		homebase       => ($forced_home || $watch->{homebase}) . ":$watch_port",
		screen_timeout => $screen_timeout,
		timestamp      => $server_time,
		offset         => $offset,
		authorization  => $authorization,
		room_count     => $room_count,
		browser_tab_id => $data->{browser_tab_id},
		room_max       => $room_max,
		# how the watch should start a voice capture: off / vad / a wake word. The
		# watch defaults to off when it is absent.
		voice_trigger  => $op_d->{'__specs'}->{'voice_trigger'},
		# the frame RMS a wake capture holds above once the voice has stopped: 'auto'
		# follows the watch's own room reading, a number pins it. Absent means auto.
		voice_floor    => $op_d->{'__specs'}->{'voice_floor'},
		# whether the guide associate's answers are spoken on the device as well as
		# shown (the Embedded panel's Audio replies toggle); absent means on
		audio_replies  => $op_d->{'__specs'}->{'audio_replies'},
		# the machine serving this device, by the name a person knows it by (the
		# same name the neighbour list shows); the watch prints it in the status bar
		computer_name  => $computer_name,
		twshomebase    => "$watch->{homebase}:$ENV{PORT_COMS}",
		thomebase      => "$watch->{homebase}:$ENV{PORT_BESTOW}",
		# encoded JSON, so it travels as one query value or one BLE field
		houses         => encode_json($house_nodes),
	};

	my $watch_home = Mojo::URL->new("http://$watch->{ip}:$config->{port}/now_me")
		->query($params)
		->to_string;

	# Bounded: a watch off its LAN has a dead IP, and an unbounded blocking fetch
	# used to sit on the whole request until the connect gave up, which the panel
	# showed as a stalled/red Now Me. A fast local device answers well inside these.
	my $ua = Mojo::UserAgent->new(connect_timeout => 3, inactivity_timeout => 5);
	foreach my $gah ( qw/project person community club team/ ) {
		my $pros = &subs::db_query('select * from settings where (setting=? or setting =?) and value=?', 'pos','mab',$gah);
		my $professionals = $pros->hashes;
		$op_d->{'__specs'}->{'chat'}->{$gah} = "";
		foreach my $sc ( keys %{$gb::social_constructs} ) {
			if ($gb::social_constructs->{$sc}->{'sing'} eq $gah) {
				$op_d->{'__specs'}->{'chat'}->{$gah} .= $gb::social_constructs->{$sc}->{'def'} . "\n";
			}
		}

		foreach my $pro ( @{$professionals} ) {
			$op_d->{'__specs'}->{'chat'}->{$gah} .= &subs::format_name($pro->{'app'}) . "\n";
		}
	}
	my $contacters = &subs::db_query('select * from tickets where status = ?', 'active' );
	my $contacts = $contacters->hashes;
	$op_d->{'__specs'}->{'chat'}->{'contacts'} = "";
	foreach my $conmen ( @{$contacts} ) {
		$op_d->{'__specs'}->{'chat'}->{'contacts'} .= $conmen->{'name'} . "\n";
	}
	$ip = $watch->{'ip'};
	my $json_op = encode_json $op_d;

	# One millisecond stamp for the local row and the peer copies: the table
	# orders by server_time, and a seconds value here (the now_me clock above is
	# in seconds) sorts below the row it is meant to replace.
	my $row_time = &subs::rightNow();
	&subs::setting_setter({ app => $edt, setting => 'operator_door', value => $json_op, subsetting => $chip_id, server_time => $row_time });
	# The device probes a fallback House machine with this pair, so every peer
	# on this LAN must hold this rotation now, not on a later sync tick. Done
	# inside the request (a couple of seconds) rather than in a forked relay:
	# the prefork worker's subprocess did not reliably reach the peers.
	my $door_peers = eval { &subs::operator_door_push($edt, $chip_id, $json_op, $row_time, &subs::device_setter()) } || 0;
	$log->info('operator door push: ' . $door_peers . ' peer(s) for ' . $chip_id) if $log;
	# Which link actually carries this Now Me? An explicit 'bluetooth' asks for the
	# bridge; otherwise the watch's own LAN is tried, and a watch that answers is
	# fetched over HTTP. A watch bridged over BLE and off its access point cannot
	# answer that ping, and the push used to be dropped in silence - the Embedded
	# panel then red-dotted and the button never landed. When this machine can
	# drive the bridge and the device carries a bluetooth address, fall through to
	# the very push bt_now_me sends.
	my $link = $method && $method eq 'bluetooth' ? 'bluetooth' : undef;
	unless ($link) {
		my $ping = 'timeout .2 ping -c 1 ' . $watch->{'ip'};
		my $ping_test = `$ping`;
		$link = 'http' if $ping_test =~ /ttl/gi;
		$link = 'bluetooth' if !$link && &subs::ble_bridge_capable() && $watch->{'mac_addresses'}->{'bluetooth'};
	}
	if ($link && $link eq 'bluetooth') {
		my $returner = &subs::bluetooth_sender({
			intent => 'com.jawn.president.bt.connect',
			chip_id => $chip_id,
			edt => $edt,
			message => { type => 'now_me', data => $params }
		});
		# The role follows the params. A watch/deck draws its buttons from the room
		# payload; a board gets the compact form (no chat lists, no pairing
		# patience) so it can be carried as plain JSON and applied without a zlib
		# inflater on the microcontroller.
		if ($edt eq 'microcontroller') {
			my $board_payload = &subs::board_config_payload({ edt => $edt, chip_id => $chip_id });
			if ($board_payload) {
				&subs::bluetooth_sender({
					intent => 'com.jawn.president.bt.connect',
					chip_id => $chip_id,
					edt => $edt,
					message => { type => 'board_config', data => $board_payload }
				});
			}
		}
		else {
			my $room_payload = &subs::watch_room_payload({ edt => $edt, chip_id => $chip_id });
			if ($room_payload) {
				&subs::bluetooth_sender({
					intent => 'com.jawn.president.bt.connect',
					chip_id => $chip_id,
					edt => $edt,
					message => { type => 'room', data => { room => 1, payload => $room_payload } }
				});
			}
		}
		# say so, rather than fall through to the empty {} the caller then
		# rendered as HASH(0x...) and read as a button that did nothing
		return 'pushed over bluetooth';
	}
	elsif ($link && $link eq 'http') {
		my $res = $ua->insecure(1)->get($watch_home)->result;
		if ($edt eq 'microcontroller') {
			if (eval { $res->result->body }) {
				if (eval { decode_json $res->result->body }) {
					my $rb = decode_json $res->result->body;
					foreach my $info ( keys %{$rb} ) {
						$op_d->{'__specs'}->{$info} = $res->{$info};
					}
				}
			}
			$json_op = encode_json $op_d;
			&subs::setting_setter({ app => $edt, setting => 'operator_door', value => $json_op, subsetting => $chip_id });
		}
		return $res;
	}
	return {};
}

get '/manager/watch/set_proxy' => sub ($c) {
	my $edt = $c->param('edt');
	my $timestamp = $c->param('timestamp');
	my $uuid = $c->param('uuid');
	my $lat_calc = 110.574;
	my $long_calc = (111.320 * cos($lat_calc));
	my $scope = $c->param('scope') || 20;
	my $chip_id = $c->param('chip_id');
	my $q = &subs::db_query('select * from continent where uuid = ? and timestamp=?',$uuid, $timestamp);
	my $locations = $q->hashes;

	&subs::setting_setter({ app => $edt, setting => 'watch_scope', value => $scope, subsetting => $chip_id });
	my $proxies = { near => $locations, far => [], here => {}, scope => $scope };
	foreach my $l ( @{$locations} ) {
		my $operator_door = &subs::setting_grabber({ app => $edt, setting => 'operator_door', subsetting => $chip_id });
		my $od = decode_json $operator_door;
		my $operator = $od->{'b1'}->{'app'};
		&subs::db_update('continent', {
			operator => $operator,
			operator_door => $operator_door,
			type => 'proxy_set',
			scope => $scope
		},{ uuid => $l->{'uuid'}, timestamp => $timestamp });
		my $sloop = &subs::db_query('select * from continent where timestamp=? and uuid=?',$timestamp, $l->{'uuid'});
		my $slur = $sloop->hashes;
		my $sl = $slur->[0];
		$proxies->{'here'} = $sl;
	}

	$c->render(json => $proxies);
};

get '/manager/watch/list_proxy' => sub($c) {
	my $edt = $c->param('edt');
	my $timestamp = $c->param('timestamp');
	my $uuid = $c->param('uuid');
	my $chip_id = $c->param('chip_id');
	my $q = &subs::db_query('select * from continent where uuid = ? and timestamp=?',$uuid,$timestamp);
	my $locations = $q->hashes;
	my $scope = $c->param('scope') ? $c->param('scope') : 20;
	&subs::setting_setter({ app => $edt, setting => 'watch_scope', value => $scope, subsetting => $chip_id });
	my $proxies = { near => [], far => [], here => {}, scope => $scope };
	my $operator_door = &subs::setting_grabber({ app => $edt, setting => 'operator_door', subsetting => $chip_id });
	my $od = decode_json $operator_door;
	foreach my $l (@{$locations}) {

		my $operator = $od->{'b1'}->{'app'};
		&subs::db_update('continent',{
			operator => $operator,
			operator_door => $operator_door,
			type => 'proxy_load'
		}, {
			uuid => $l->{'uuid'}, timestamp => $l->{'timestamp'}
		});

		my $similar = &subs::db_query('select * from continent where type=?', 'proxy_set');

		foreach my $sl (@{$similar->hashes}) {
			my $lat = ($sl->{'longitude'} - $l->{'longitude'});
			my $long = ($sl->{'longitude'} - $l->{'longitude'});
			my $radius = 6372.8;
			my @BNA = (deg2rad($l->{'longitude'}), deg2rad(90 - $l->{'latitude'}));
			my @LAX = (deg2rad($sl->{'longitude'}), deg2rad(90 - $sl->{'latitude'}));

			my $distance = great_circle_distance(@BNA, @LAX, $radius);
			my $metres = $distance * 1000;

			$sl->{'distance'} = sprintf("%.2f", $metres);
			$sl->{'ago'} = &subs::duration_sayer(($timestamp - $sl->{'timestamp'}) / 1000);

			if ($metres <= $scope) {
				push @{$proxies->{'near'}}, $sl;
			}
		}
		push @{$proxies->{'near'}}, $l;
		$proxies->{'here'} = $l;
	}
	$proxies->{'html'} = $c->render_to_string(
		template => 'embedded/proxy',
		proxies => $proxies,
	);

	$c->render(json => $proxies);
};


post '/manager/watch/proxy_load' => sub($c) {
	my $edt = $c->param('edt');
	my $uuid = $c->param('uuid');
	my $chip_id = $c->param('chip_id');
	my $timestamp = $c->param('timestamp');
	my $locations = &subs::db_query('select * from continent where uuid=?', $uuid)->hashes;
